function makeEnemy(type,x,y,z,boss=false){const hp=boss?(BOSS_HEALTH[type]||72):3+z;if(boss&&type==='spore'){x=480;y=320}const tuned=!boss?({blob:{hp:16.2,r:32,contactDamage:2},brute:{hp:10,r:29},worm:{hp:2,r:11},thorn:{hp:12},fly:{hp:3,r:19}}[type]||{}):{};const enemy={x,y,type,boss,r:boss?40:20,hp,max:hp,t:boss&&type==='spore'?1/1.2:random(.6,2),flash:0,phase:random(0,6),...tuned,max:tuned.hp||hp,level:z};const health=(tuned.hp||hp)*(!boss&&z===1?1.25:!boss&&z===0?({crawler:1.75,spitter:1.5,fly:1.5}[type]||1):1);enemy.hp=enemy.max=type==='worm'&&!boss?2:health*(!boss&&((z===1&&['shambler','stalker'].includes(type))||(z===2&&['seedling','moldling'].includes(type)))?1.25:1);enemy.hp*=boss?difficultySettings().bossHealth:difficultySettings().health;if(!boss&&z===0)enemy.hp*= ['spitter','fly'].includes(type)?.7:.85;enemy.max=enemy.hp;return enemy}
