function makeZone(level){return NODES.map((n,i)=>{const scale=n.type==='boss'?1:FIELD_ROOM_SCALE,config=LEVELS[level],obstacles=makeRoomObstacles(level,i),monoType=n.mono?config.pool[Math.floor(random(0,config.pool.length))]:null;let enemies=[];if(n.type==='fight'){const positions=ENCOUNTER_FORMATIONS[i],count=n.mono?5:3+level+(i===5?1:0);enemies=Array.from({length:count},(_,j)=>{const type=n.mono?monoType:config.pool[(i===3?j+1:i===5?config.pool.length-1-j%config.pool.length:j)%config.pool.length],pos=positions[j];return makeEnemy(type,pos[0],pos[1],level)})}if(n.type==='boss')enemies=[makeEnemy(config.bossType,690,300,level,true)];for(const o of obstacles){o.x*=scale;o.y*=scale;o.r*=scale}for(const e of enemies){e.x*=scale;e.y*=scale}const scenery=makeRoomScenery(level,i,makeRoomObstacles(level,i));for(const o of scenery){o.x*=scale;o.y*=scale}return {...n,name:ROOM_NAMES[level][i],monoType,seen:i===0,clear:!enemies.length,enemies,drops:[],hazards:[],stains:[],reward:false,read:false,obstacles,scenery}})}
function makeRoomObstacles(level,index){if(index===6)return[];const layouts={0:[[250,180,28],[700,460,32]],1:[[400,290,28],[580,350,28],[215,445,25]],3:[[385,320,29],[575,320,29],[480,160,25]],5:[[240,320,28],[720,320,28],[480,190,24]],7:[[390,320,28],[570,320,28],[480,170,23]]},points=layouts[index]||[[300,190,25],[660,450,28]],kinds=level===0?['rubble','cage','tank']:level===1?['rubble','medical','bed']:['rock','stump','roots'];return points.map(([x,y,r],i)=>({x,y,r,kind:kinds[(i+index)%kinds.length]}))}
function makeRoomScenery(level,index,obstacles){const props=[];for(let i=0;i<27;i++){const p={x:110+(i*139+index*31)%740,y:115+(i*83+index*19)%410,kind:i%4,seed:i*.73+index};if((Math.abs(p.x-480)<72&&(p.y<145||p.y>495))||(Math.abs(p.y-320)<65&&(p.x<180||p.x>790))||obstacles.some(o=>distance(o,p)<o.r+25)||(index===0&&distance(p,{x:120,y:320})<75))continue;props.push(p)}return props}

