 const p=state.player,health=enemy?1:p.hp/p.maxHp,low=health<=.25,tired=health<=.5,hurt=enemy?0:clamp((p.hurtPoseTime||0)/.38,0,1),hx=enemy?0:(p.headX||0),hy=enemy?0:(p.headY||0);
