 ctx.fillStyle=tired&&!enemy?withScenePaint('raw',()=>artGradient(-8,-15,48,top,bottom)):artGradient(-8,-15,48,top,bottom);head();ctx.fill();ctx.save();ctx.clip();ellipse(ctx,9,20,38,13,'#4f61382d');ellipse(ctx,-11,-25,22,9,'#eef1bf66');ellipse(ctx,-22,-17,5,9,'#f3f1c94d');
 if(tired){ellipse(ctx,-22,6,12,5,low?'#93758d66':'#b49f9055');ellipse(ctx,23,4,9,4,'#a1839255');ctx.strokeStyle=low?'#6d536e':'#7f8166';ctx.lineWidth=1.6;ctx.beginPath();ctx.moveTo(-26,-17);ctx.lineTo(-21,-10);ctx.lineTo(-25,-4);if(low){ctx.lineTo(-17,1);ctx.moveTo(17,-30);ctx.lineTo(12,-22);ctx.lineTo(16,-16)}ctx.stroke()}
