drawRuins(state.levelIndex,state.room);drawInfectedLab(state.levelIndex,state.room);drawWorldPatina(state.levelIndex,state.room);ctx.restore();drawBossEntranceScenery(r);for(let stain of r.stains)drawEnemyRemains(stain);drawRoomScenery(r,state.levelIndex);drawSporeHazards(r);for(let o of r.obstacles)if(!o.solidProp)drawThemedObstacle(o,state.levelIndex);drawBossRoomEntrance(r);
if(r.type==='entry'){ctx.save();ctx.scale(rs,rs);ellipse(ctx,120,320,35,20,'#aaba7c55');ctx.fillStyle='#d9e5a4';ctx.font='11px monospace';ctx.textAlign='center';ctx.fillText('E · VOLVER AL BÚNKER',150,370);ctx.save();ctx.translate(110,320);ctx.rotate(-Math.PI/2);ctx.fillStyle='#afb58a66';ctx.font='bold 18px monospace';ctx.textAlign='center';ctx.fillText('BÚNKER 07',0,0);ctx.restore();ctx.fillStyle='#b0b477';ctx.font='16px monospace';ctx.fillText(`NIVEL ${z.code} · ALA CLAUSURADA →`,650,515);ctx.restore()}
if(r.type==='archive'){ctx.save();ctx.scale(rs,rs);drawArchive();ctx.restore()}if(r.type==='boss'&&r.clear)drawBossExit(r)
