function updateActorMotion(dt,before){const p=state.player;if(!p.anim)p.anim={move:0,phase:0,lean:0,look:0};const a=p.anim;if(state.paused||state.map||!['play','bunker'].includes(state.mode))return;const same=state.mode===before.mode&&state.room===before.room&&state.levelIndex===before.level,dx=same?p.x-before.x:0,dy=same?p.y-before.y:0,speed=Math.hypot(dx,dy)/Math.max(dt,.001),target=clamp(speed/190,0,1),ease=1-Math.exp(-12*dt);a.move+=(target-a.move)*ease;const travel=Math.hypot(dx,dy);a.phase+=travel/characterRig(p).stride*Math.PI*2;if(travel>.01){if(Math.abs(dx)>Math.abs(dy)*1.1)a.direction=dx<0?'left':'right';else if(Math.abs(dy)>Math.abs(dx)*1.1)a.direction=dy<0?'up':'down';else if(!a.direction)a.direction=dy<0?'up':'down'}a.lean+=(clamp(dx/Math.max(dt,.001)/190,-1,1)-a.lean)*ease;if(Math.abs(dx)>.01)a.look+=(Math.sign(dx)-a.look)*ease;else a.look*=Math.exp(-3*dt);const shooting=state.elapsed-(p.lastShotAt??-999)<.7,moving=speed>2;let hx=p.headX||0,hy=p.headY||0;if(shooting){hx=Math.cos(p.facing);hy=Math.sin(p.facing)}else{const ix=Number(keys.has('d'))-Number(keys.has('a'))+TOUCH.move.x,iy=Number(keys.has('s'))-Number(keys.has('w'))+TOUCH.move.y,intent=Math.hypot(ix,iy);if(intent>.15){hx=ix/intent;hy=iy/intent;if(Math.abs(ix)>Math.abs(iy)*1.1)a.direction=ix<0?'left':'right';else if(Math.abs(iy)>Math.abs(ix)*1.1)a.direction=iy<0?'up':'down'}else if(moving){hx=dx/Math.hypot(dx,dy);hy=dy/Math.hypot(dx,dy)}}const headEase=1-Math.exp(-18*dt);p.headX=(p.headX||0)+(hx-(p.headX||0))*headEase;p.headY=(p.headY||0)+(hy-(p.headY||0))*headEase;}
function drawMoho(){const p=state.player,a=p.anim||{move:0,phase:0,lean:0},breath=Math.sin(state.elapsed*2.8),step=Math.sin(a.phase),squash=step*a.move*.045;ctx.save();ctx.translate(p.x,p.y-Math.abs(step)*a.move*3+breath*.8);const recoil=p.shotPulse||0,hurt=clamp((p.hurtPoseTime||0)/.38,0,1);ctx.translate(-Math.cos(p.facing||0)*recoil*2,Math.sin(state.elapsed*54)*hurt*2);ctx.rotate(a.lean*.065+Math.sin(state.elapsed*36)*hurt*.05);ctx.scale(1+squash+breath*.008+recoil*.035+hurt*.06,1-squash-breath*.012-recoil*.025-hurt*.08);clay(0,0,1,'#b4c997');ctx.restore()}
