 ellipse(ctx,platform.x,platform.y+7,64,46,'#3f51342b');ellipse(ctx,platform.x,platform.y,62,44,'#81946955');ctx.strokeStyle='#d6d7a4';ctx.lineWidth=3;ctx.setLineDash([8,6]);ctx.beginPath();ctx.ellipse(platform.x,platform.y,61,44,0,0,Math.PI*2);ctx.stroke();ctx.setLineDash([]);ctx.save();ctx.fillStyle='#d5d8ab88';ctx.font='bold 48px Georgia';ctx.textAlign='center';ctx.textBaseline='middle';ctx.fillText('P',platform.x,platform.y-1);ctx.restore();ctx.font='9px monospace';ctx.textAlign='center';ctx.fillStyle='#394c30';ctx.fillText(platform.floorElevator?'ASCENSOR / PISO 2':ALLY_PROFILE.unlocked?'ELEGIR PERSONAJE':'SUJETO / RESERVADO',platform.x,platform.y+65);
 const board=BUNKER_OBJECTS.find(o=>o.id==='missions'),hatch=BUNKER_OBJECTS.find(o=>o.id==='tutorial');
