 ctx.save();ctx.translate(731.25,117.75);roundedInkRect(-20,-18,40,36,'#4a5942');ctx.rotate(t*.6);ctx.fillStyle='#8f9c79';for(let i=0;i<3;i++){ctx.rotate(Math.PI*2/3);ctx.beginPath();ctx.moveTo(0,0);ctx.quadraticCurveTo(23,-10,13,10);ctx.closePath();ctx.fill()}ctx.restore();
 for(let i=1;i<=3;i++)bunkerDoor(BUNKER_OBJECTS.find(o=>o.id===(i===1?'exit':`zone${i}`)),i);
