const ITEM_IMAGE_CACHE=new Map();
function itemIllustration(item){const path=ITEM_DRAWINGS[item.id];if(!path)return item.icon;return `<svg viewBox="0 0 48 48" aria-hidden="true" xmlns="http://www.w3.org/2000/svg"><path d="${path}" fill="#b9c59c33" stroke="currentColor" stroke-width="2.6" stroke-linecap="round" stroke-linejoin="round"/></svg>`}
function drawWorldItemGlyph(item,x,y){const path=ITEM_DRAWINGS[item.id];if(!path){ctx.fillText(item.icon,x,y+8);return}if(globalThis.CONVERSATION_RENDER_SCALE>1){ctx.save();ctx.translate(x-14,y-14);ctx.scale(28/48,28/48);const art=new Path2D(path);ctx.fillStyle='#c9d3a344';ctx.strokeStyle='#e3e1b5';ctx.lineWidth=2.8;ctx.lineCap='round';ctx.lineJoin='round';ctx.fill(art);ctx.stroke(art);ctx.restore();return}if(!ITEM_IMAGE_CACHE.has(item.id)){const picture=new Image(),svg=`<svg xmlns="http://www.w3.org/2000/svg" width="48" height="48" viewBox="0 0 48 48"><path d="${path}" fill="#c9d3a344" stroke="#e3e1b5" stroke-width="2.8" stroke-linecap="round" stroke-linejoin="round"/></svg>`;picture.src='data:image/svg+xml;charset=utf-8,'+encodeURIComponent(svg);ITEM_IMAGE_CACHE.set(item.id,picture)}const picture=ITEM_IMAGE_CACHE.get(item.id);if(picture.complete&&picture.naturalWidth)ctx.drawImage(picture,x-14,y-14,28,28);else ctx.fillText(item.icon,x,y+8)}
function drawRefinedBossBar(boss,z){ctx.save();ctx.fillStyle='#182a20e8';ctx.strokeStyle='#9eaa7955';ctx.lineWidth=1.5;ctx.beginPath();ctx.moveTo(292,54);ctx.lineTo(668,54);ctx.lineTo(680,66);ctx.lineTo(680,113);ctx.lineTo(280,113);ctx.lineTo(280,66);ctx.closePath();ctx.fill();ctx.stroke();ctx.fillStyle='#101c15';ctx.fillRect(297,65,366,12);const hp=ctx.createLinearGradient(300,66,300,77);hp.addColorStop(0,'#e0d8af');hp.addColorStop(1,z.accent);ctx.fillStyle=hp;ctx.fillRect(300,67,360*clamp(boss.hp/boss.max,0,1),7);ctx.fillStyle='#dfe3c3';ctx.textAlign='center';ctx.font='bold 11px monospace';ctx.fillText(z.boss.toUpperCase(),480,93);ctx.font='9px monospace';ctx.fillStyle='#c7c59d';ctx.fillText(bossAttackLabel(boss),480,107);ctx.restore()}

// High-contrast silhouettes and internal details preserve each projectile's collision radius.
const drawDetailedHostileBase=drawHostileBullet;
function drawLevelCProjectile(b){const radius=b.r||7;ctx.save();ctx.translate(b.x,b.y);ctx.strokeStyle='#211b26';ctx.lineWidth=3;ctx.fillStyle=b.kind==='cloud'?'#99617d':'#edbc82';if(b.kind==='needle'){ctx.rotate(Math.atan2(b.vy,b.vx));ctx.beginPath();ctx.moveTo(18,0);ctx.lineTo(-11,-5);ctx.lineTo(-7,0);ctx.lineTo(-11,5);ctx.closePath();ctx.fill();ctx.stroke()}else{ctx.beginPath();ctx.arc(0,0,radius,0,Math.PI*2);ctx.fill();ctx.stroke();ctx.strokeStyle=b.kind==='robot'?'#d7ffff':b.kind==='cloud'?'#f5cadf':'#fff0c1';ctx.lineWidth=1.4;ctx.beginPath();ctx.arc(0,0,Math.max(1,radius-1.3),0,Math.PI*2);ctx.stroke()}ctx.restore();drawDetailedHostileBase(b);ctx.save();ctx.translate(b.x,b.y);if(b.kind==='cloud'){ctx.strokeStyle='#f5c7db';ctx.lineWidth=1.5;ctx.beginPath();ctx.arc(0,0,radius-.8,-2.7,-.6);ctx.stroke();for(let i=0;i<3;i++){const a=i*2.1;ellipse(ctx,Math.cos(a)*radius*.4,Math.sin(a)*radius*.4,1.4,1.4,'#fff1db')}}else if(b.kind==='robot'){ctx.strokeStyle='#324750';ctx.lineWidth=1.5;ctx.strokeRect(-radius*.4,-radius*.4,radius*.8,radius*.8);ellipse(ctx,0,0,1.5,1.5,'#eaffff')}else if(b.kind!=='needle'){ctx.strokeStyle='#6e3d48';ctx.lineWidth=1;ctx.beginPath();ctx.arc(1,1,radius*.55,.2,1.8);ctx.stroke();ellipse(ctx,-radius*.3,-radius*.35,1.5,1.5,'#fff9df')}ctx.restore()}
drawHostileBullet=function(b){if(state.levelIndex===2){drawLevelCProjectile(b);return}const r=b.r||7;ctx.save();ctx.translate(b.x,b.y);ctx.lineJoin='round';ctx.lineCap='round';if(b.kind==='needle'){ctx.rotate(Math.atan2(b.vy,b.vx));ctx.fillStyle=artGradient(0,0,16,'#ffb199','#bd264b');ctx.strokeStyle='#421e32';ctx.lineWidth=3;ctx.beginPath();ctx.moveTo(18,0);ctx.lineTo(-11,-5);ctx.lineTo(-7,0);ctx.lineTo(-11,5);ctx.closePath();ctx.fill();ctx.stroke();artLine([[-7,-2],[10,0]],'#ffe5d2',1.5)}else{const cloud=b.kind==='cloud';ctx.fillStyle=artGradient(-2,-2,r,cloud?'#f59291':b.kind==='robot'?'#ff8d83':'#ff9b85',cloud?'#a93a60':'#bd2449');ctx.strokeStyle='#401c2f';ctx.lineWidth=3;ctx.beginPath();ctx.arc(0,0,r,0,Math.PI*2);ctx.fill();ctx.stroke();ctx.strokeStyle='#ffc1a6';ctx.lineWidth=1.3;ctx.beginPath();ctx.arc(0,0,Math.max(1,r-1.5),-2.8,-.3);ctx.stroke();if(cloud){for(let i=0;i<5;i++){const a=i*Math.PI*2/5;ellipse(ctx,Math.cos(a)*r*.55,Math.sin(a)*r*.55,r*.42,r*.42,'#ef6f7d77')}for(let i=0;i<3;i++){const a=i*2.1;ellipse(ctx,Math.cos(a)*r*.4,Math.sin(a)*r*.4,1.5,1.5,'#ffd5bd')}}else if(b.kind==='robot'){ctx.strokeStyle='#7c2344';ctx.lineWidth=1.5;ctx.strokeRect(-r*.4,-r*.4,r*.8,r*.8);ellipse(ctx,0,0,2,2,'#ffe3d1')}else if(b.kind==='spore'){for(let i=0;i<3;i++){const a=i*2.1;ellipse(ctx,Math.cos(a)*r*.45,Math.sin(a)*r*.45,1.4,1.4,'#ffd9c4')}ellipse(ctx,-1,-2,1.5,1.3,'#fff0dd')}else{ctx.strokeStyle='#8c2845';ctx.lineWidth=1;ctx.beginPath();ctx.arc(1,1,r*.55,.2,1.8);ctx.stroke();ellipse(ctx,-r*.3,-r*.35,2,1.5,'#ffe4cb')}}ctx.restore()};

































































































































































































































































































































































































































































































































































































































































































































































































































































































































































































































































































































































































































































































































































































































































































































































































































































































































































































































































































































































































































































































