// Shared lifecycle signals: systems subscribe instead of wrapping transitions.
const GAME_EVENTS=(()=>{const listeners=new Map();return Object.freeze({
 on(name,listener){if(!listeners.has(name))listeners.set(name,new Set());listeners.get(name).add(listener);return()=>listeners.get(name)?.delete(listener)},
 emit(name,payload){for(const listener of [...(listeners.get(name)||[])])listener(payload)}
})})();

// Personal backpack limits, passive categories, and canonical equipment references.
const DESKTOP_EQUIPMENT=true; // Expanded equipment is now shared by desktop and touch.
const characterBackpackRanks={};
if(DESKTOP_EQUIPMENT)Object.assign(EQUIP_SLOTS,{
 passive:['PASIVO COMÚN 1','Sin pasivo común','✧'],
 passive2:['PASIVO COMÚN 2','Sin pasivo común','✧'],
 passive3:['PASIVO COMÚN 3','Sin pasivo común','✧'],
 bossPassive:['PASIVO DE JEFE 1','Sin pasivo de jefe','◆'],
 bossPassive2:['PASIVO DE JEFE 2','Sin pasivo de jefe','◆']
});
function backpackRank(p=state?.player){return DESKTOP_EQUIPMENT?characterBackpackRanks[p?.characterId||'moho']||0:0}
function backpackCapacityAtRank(rank){rank=clamp(Math.floor(Number(rank)||0),0,7);return 7+Math.min(rank,1)*2+Math.min(Math.max(rank-1,0),3)}
function backpackCapacity(p=state?.player){return DESKTOP_EQUIPMENT?backpackCapacityAtRank(backpackRank(p)):10}
function isBossPassive(item){return item?.slot==='passive'&&Object.values(BOSS_ITEMS).some(drops=>Object.values(drops).some(i=>i.id===item.id))}
function passiveSlots(boss=false,p=state?.player){if(!DESKTOP_EQUIPMENT)return ['passive'];const rank=backpackRank(p);return boss?['bossPassive',...(rank>=5?['bossPassive2']:[])]:['passive','passive2',...(rank>=6?['passive3']:[])]}
function equipmentSlotKeys(p=state?.player){return ['weapon','charm','active',...passiveSlots(false,p),...(DESKTOP_EQUIPMENT?passiveSlots(true,p):[])]}
function equipmentSlotAccepts(slot,item){return slot==='passive'?item.slot==='passive':slot.startsWith('bossPassive')?isBossPassive(item):slot.startsWith('passive')?item.slot==='passive'&&!isBossPassive(item):item.slot===slot}
function isItemEquipped(item,p=state.player){return Object.values(p.equipment||{}).some(i=>i?.uid===item.uid)}
function passiveCount(effect,p=state.player){return equipmentSlotKeys(p).filter(slot=>p.equipment?.[slot]?.slot==='passive'&&p.equipment[slot][effect]).length}
function passiveEffect(effect,p=state.player){return passiveCount(effect,p)>0}
function canAddPassive(item,equipped,p=state.player){
 const counts=new Map();for(const i of equipped)if(i?.slot==='passive')counts.set(i.id,(counts.get(i.id)||0)+1);
 const copies=counts.get(item.id)||0;
 return !copies||backpackRank(p)>=7&&copies===1&&![...counts.values()].some(n=>n>=2);
}
function normalizeEquipment(p){
 p.capacity=backpackCapacity(p);
 const previous=Object.values(p.equipment||{}).filter(Boolean),next=Object.fromEntries(Object.keys(EQUIP_SLOTS).map(slot=>[slot,null])),seen=new Set();
 for(const saved of previous){const template=typeof allItemTemplates==='function'?allItemTemplates().find(i=>i.id===saved.id):null,item=template&&typeof restoreItemInstance==='function'?restoreItemInstance(template,saved):saved;if(!item||seen.has(item.uid)||p.characterId==='infected'&&['sporeHeart','vossEmber'].includes(item.id))continue;
  const slots=item.slot==='passive'?passiveSlots(isBossPassive(item),p):[item.slot];
  if(item.slot==='passive'&&!canAddPassive(item,Object.values(next),p))continue;
  const slot=slots.find(s=>Object.hasOwn(next,s)&&!next[s]);if(slot){next[slot]=item;seen.add(item.uid)}
 }
 p.equipment=next;p.bag=(p.bag||[]).filter(item=>!seen.has(item.uid));if(typeof state!=='undefined'&&p===state.player&&Array.isArray(state.selected))state.selected=state.selected.filter(uid=>p.bag.some(item=>item.uid===uid));
}
function unequipItem(item,p=state.player){let passive=false;for(const slot of Object.keys(p.equipment)){if(p.equipment[slot]?.uid===item.uid){passive||=item.slot==='passive';p.equipment[slot]=null}}if(passive)clearPassiveEffects()}
function equipmentTargets(item,p=state.player){
 if(!item||p.characterId==='infected'&&['sporeHeart','vossEmber'].includes(item.id))return [];
 const slots=item.slot==='passive'?passiveSlots(isBossPassive(item),p):[item.slot];
 return slots.filter(slot=>equipmentSlotAccepts(slot,item)&&(item.slot!=='passive'||canAddPassive(item,Object.entries(p.equipment).filter(([key])=>key!==slot).map(([,equipped])=>equipped),p))).sort((a,b)=>Number(!!p.equipment[a])-Number(!!p.equipment[b]));
}
function equipItemIntoSlot(item,slot,p=state.player){
 normalizeEquipment(p);const index=p.bag.findIndex(other=>other.uid===item?.uid);if(index<0||!equipmentTargets(item,p).includes(slot))return false;
 const old=p.equipment[slot];p.bag.splice(index,1);state.selected=state.selected.filter(uid=>uid!==item.uid);if(old)p.bag.push(old);p.equipment[slot]=item;if(item.slot==='passive'||old?.slot==='passive')clearPassiveEffects();notify(old?`${item.name} equipado. ${old.name} volvió a la mochila.`:`${item.name} equipado. Ya no ocupa espacio en la mochila.`);return true;
}
function returnEquippedItem(slot,p=state.player){
 normalizeEquipment(p);const item=p.equipment[slot];if(!item)return false;if(p.bag.length>=p.capacity){notify(`Mochila llena (${p.bag.length}/${p.capacity}). Soltá un objeto antes de desequipar ${item.name}.`);return false}
 p.equipment[slot]=null;p.bag.push(item);if(item.slot==='passive')clearPassiveEffects();notify(`${item.name} volvió a la mochila.`);return true;
}
function toggleEquippedItem(item){
 const p=state.player;normalizeEquipment(p);
 if(p.characterId==='infected'&&['sporeHeart','vossEmber'].includes(item.id)){notify(item.id==='vossEmber'?'El fuego marchitaría al infectado. No puede equipar esta ascua.':'El infectado reconoce ese corazón y se niega a usarlo.');return false}
 const slots=equipmentTargets(item,p);if(!slots.length){notify(item.slot==='passive'?(backpackRank(p)>=7?'Solo podés usar un par de pasivos iguales, sin triples ni un segundo par.':'Los pasivos equipados deben ser distintos.'):'Ese objeto no se puede equipar.');return false}
 if(!isMobileGame()&&item.slot==='passive'&&window.ITEM_PICKUP?.offer)return ITEM_PICKUP.offer(item,slots[0]);
 const free=slots.find(slot=>!p.equipment[slot]);if(free)return equipItemIntoSlot(item,free,p);
 if(window.ITEM_PICKUP?.offer)return ITEM_PICKUP.offer(item,slots[0]);return false;
}

