// Retired content is removed from old inventories without rejecting the rest of a save.
const RETIRED_ITEM_IDS=new Set(['causticFlask','resin','discardPulse']);
function migrateRetiredItemRecord(record){const p=record?.progress;if(!p)return;const retired=i=>RETIRED_ITEM_IDS.has(i?.id);if(Array.isArray(p.bag))p.bag=p.bag.filter(i=>!retired(i));for(const slot of Object.keys(p.equipment||{}))if(retired(p.equipment[slot])){p.equipment[slot]=null;if(slot==='active'){p.cool=0;p.activeCooldown=0}};if(Array.isArray(record.selected)&&Array.isArray(p.bag))record.selected=record.selected.filter(uid=>p.bag.some(i=>i.uid===uid))}

