// Every fungal presentation uses the combat colony, including legacy preview paths.
function puppetFungus(time,roar){
 ctx.save();ctx.scale(1/1.65,1/1.65);
 renderMonster({type:'spore',boss:true,x:0,y:0,r:40,hp:200,max:200,phase:0,attackMode:'normal',attackFlash:roar*.12},time);
 ctx.restore();
}
function drawBossPuppetFrame(intro,time){
 const c=intro.canvas.getContext('2d'),previous=ctx;ctx=c;
 try{withScenePaint('raw',()=>{
  const cfg=BOSS_PUPPET_INTROS[intro.type],progress=clamp(time/intro.duration,0,1),arrive=puppetEase(time/.95),roar=Math.sin(clamp((time-2.3)/1.25,0,1)*Math.PI),reduce=intro.reduced;
  ctx.clearRect(0,0,960,540);const light=ctx.createRadialGradient(480,280,20,480,280,590);light.addColorStop(0,'#38433b');light.addColorStop(1,'#101616');ctx.fillStyle=light;ctx.fillRect(0,0,960,540);
  // Inked backdrop, surgical spotlight and paper-cut scenery.
  ctx.fillStyle='#ddd6b510';ctx.beginPath();ctx.moveTo(390,0);ctx.lineTo(570,0);ctx.lineTo(850,540);ctx.lineTo(110,540);ctx.closePath();ctx.fill();
  ctx.strokeStyle='#c9c6a21c';ctx.lineWidth=1;for(let i=0;i<13;i++){ctx.beginPath();ctx.moveTo(i*85-100,0);ctx.lineTo(i*85+70,540);ctx.stroke()}
  for(let i=0;i<16;i++){const x=(i*173)%960,y=(i*97+time*(reduce?0:7+i%3*4))%540;ellipse(ctx,x,y,1+i%2,1+i%2,cfg.accent+'38')}
  ellipse(ctx,480,449,190,25,'#00000055');
  const bob=reduce?0:Math.sin(time*3)*3,zoom=reduce?2.25:2.15+arrive*.15,offset=reduce?0:(1-arrive)*180;
  ctx.save();ctx.translate(480,326+offset+bob);ctx.scale(zoom,zoom);
  withScenePaint(intro.type==='patient'?'patient':null,()=>{if(intro.type==='mother')puppetRat(reduce?0:time,reduce?0:roar);else if(intro.type==='patient')puppetPatient(reduce?0:time,reduce?0:roar);else puppetFungus(reduce?0:time,reduce?0:roar)});ctx.restore();
  if(intro.type==='spore')for(let i=0;i<12;i++){const a=i*Math.PI/6+time*(reduce?0:.3),r=160+Math.sin(time+i)*15;ellipse(ctx,480+Math.cos(a)*r,285+Math.sin(a)*r*.7,3+i%3,3+i%3,cfg.accent+'55')}
  const curtain=reduce?0:Math.max(0,1-time/.65);ctx.fillStyle='#101616';ctx.fillRect(0,0,960,95*curtain);ctx.fillRect(0,540-95*curtain,960,95*curtain);
  ctx.strokeStyle=cfg.accent+'66';ctx.lineWidth=2;ctx.strokeRect(16,16,928,508);ctx.fillStyle=cfg.accent;ctx.textAlign='left';ctx.font='bold 13px monospace';ctx.fillText(cfg.kicker,35,45);
  ctx.textAlign='right';ctx.fillText(`${Math.min(100,Math.round(progress*100))}%`,923,45);
  if(time>1.1){ctx.globalAlpha=Math.min(1,(time-1.1)*2);ctx.textAlign='center';ctx.font='bold 14px monospace';ctx.fillText(time>intro.duration-.7?'CONTENCIÓN PERDIDA':cfg.reveal,480,500);ctx.globalAlpha=1}
 })}finally{ctx=previous}
}
function bossPuppetSound(type){
 if(!SOUND.ctx||!SOUND.enabled||!SOUND.sfxEnabled)return;
 const now=SOUND.ctx.currentTime;audioTone(type==='mother'?135:type==='patient'?85:58,.65,.12,'sawtooth',SOUND.sfx,now,35);audioNoise(.35,.09,type==='patient'?1600:550);
 if(type==='mother')audioTone(650,.4,.08,'triangle',SOUND.sfx,now+.05,100);
}
function cancelBossPuppet(){const intro=state?.bossIntro;if(intro?.raf)cancelAnimationFrame(intro.raf);$('#overlay').classList.remove('puppet-intro')}
showBossIntro=function(enemy){
 const room=state.rooms[state.room],drama=BOSS_DRAMA[enemy.type],cfg=BOSS_PUPPET_INTROS[enemy.type];if(!drama||room.introShown)return;
 room.introShown=true;cancelBossPuppet();const reduced=matchMedia('(prefers-reduced-motion:reduce)').matches;
 const intro=state.bossIntro={type:enemy.type,room:state.room,elapsed:0,duration:reduced?2.5:cfg.duration,reduced,last:null,raf:0,sounded:false};
 state.paused=true;state.dialog=false;keys.clear();resetTouchInput();mouse.down=false;
 const el=$('#overlay');el.hidden=false;el.classList.add('boss-intro','puppet-intro');el.style.setProperty('--boss-color',cfg.accent);
 el.innerHTML=`<div class="eyebrow">NÚCLEO DE CONTENCIÓN / NIVEL ${LEVELS[state.levelIndex].code}</div><canvas class="boss-puppet-stage" width="960" height="540" role="img" aria-label="Presentación animada de ${drama.subtitle}"></canvas><h2>${drama.subtitle}</h2><p>${drama.tagline}</p><div class="puppet-progress" aria-hidden="true"><i></i></div><button id="boss-begin" class="quiet">Saltar presentación →</button><small>La pelea comienza al terminar · Enter para saltar</small>`;
 intro.canvas=el.querySelector('canvas');$('#boss-begin').onclick=finishBossIntro;$('#boss-begin').focus({preventScroll:true});drawBossPuppetFrame(intro,0);soundSfx('warning');
 const frame=now=>{
  if(state.bossIntro!==intro||state.mode!=='play'||state.room!==intro.room)return;
  const dt=intro.last===null?0:Math.min(.08,Math.max(0,(now-intro.last)/1000));intro.last=now;if(!document.hidden&&!mobileNeedsRotation())intro.elapsed+=dt;
  drawBossPuppetFrame(intro,intro.elapsed);const progress=el.querySelector('.puppet-progress i');if(progress)progress.style.width=`${Math.min(100,intro.elapsed/intro.duration*100)}%`;
  if(!intro.sounded&&intro.elapsed>=intro.duration*.48){intro.sounded=true;bossPuppetSound(intro.type)}
  if(intro.elapsed>=intro.duration){finishBossIntro();return}intro.raf=requestAnimationFrame(frame);
 };intro.raf=requestAnimationFrame(frame);
};
const puppetFinishBase=finishBossIntro;
finishBossIntro=function(){if(!state.bossIntro)return;const room=state.rooms[state.bossIntro.room];cancelBossPuppet();puppetFinishBase();room.entryDelay=0};
const puppetClearBase=clearItemEffects;
clearItemEffects=function(){cancelBossPuppet();puppetClearBase()};
const puppetResetBase=reset;
reset=function(){cancelBossPuppet();puppetResetBase()};

// In-world entrances replace the separate cinematic stage. The existing puppet
// pieces remain reusable, but their clock and effects now live in the real room.
const BOSS_ROOM_ENTRANCES={mother:{duration:5.6,impact:1.05},patient:{duration:6.6,impact:2.15,slam:4.2},spore:{duration:5.2,impact:.7}};
const entranceSmooth=x=>{x=clamp(x,0,1);if(x>=1-1e-10)return 1;return x*x*x*(x*(x*6-15)+10)};
function bossRoomEntrancePose(intro){
 const t=intro.elapsed,type=intro.type,ease=puppetEase;
 if(type==='mother')return{visible:t>=1.05,x:690+340*(1-ease((t-1.05)/1.1)),y:320,rage:false,rubble:clamp((t-2.4)/2,0,1)};
 if(type==='patient'){const settle=clamp((t-2.15)/.38,0,1);return{visible:t>=1.05,x:480,y:320-740*(1-entranceSmooth((t-1.05)/1.1))+Math.sin(settle*Math.PI)*4*(1-settle),rage:t>=2.5&&t<3.5,arms:entranceSmooth((t-3.5)/.45)*(1-entranceSmooth((t-4.65)/.85)),slam:entranceSmooth((t-3.95)/.25)}}
 return{visible:t>=.8,x:480,y:320+155*(1-ease((t-.8)/2.4)),rage:false,hole:ease((t-.5)/.85)};
}
function entranceFloorHole(amount=1){
 ctx.save();ctx.translate(480,342);ctx.scale(Math.max(.01,amount),Math.max(.01,amount));
 ellipse(ctx,0,5,109,61,'#25362a66');ellipse(ctx,0,0,103,57,'#11191d',true);ellipse(ctx,0,5,84,40,'#080e12');
 ctx.strokeStyle='#7c8d68';ctx.lineWidth=4;ctx.beginPath();ctx.ellipse(0,0,103,57,0,0,Math.PI*2);ctx.stroke();
 for(let i=0;i<15;i++){const a=i*Math.PI*2/15,x=Math.cos(a)*100,y=Math.sin(a)*55;artLine([[x,y],[x*1.15,y*1.12],[x*1.25+Math.sin(i)*5,y*1.28]],'#465340',2);if(i%2)artLine([[x,y],[x*.8,y*.65+11]],'#8b7899',2.2)}
 ctx.restore();
}
function entranceRatRubble(amount=1,time=0){
 if(amount<=0)return;ctx.save();
 const count=Math.floor(31*amount);for(let i=0;i<count;i++){
  const drop=clamp(amount*31-i,0,1),x=918+Math.sin(i*2.1)*24,y=242+(i*47)%167-(1-drop)*48,r=7+(i*7)%9;
  ctx.fillStyle=i%3?'#6f7164':'#8e917c';ctx.strokeStyle='#303b33';ctx.lineWidth=2;ctx.beginPath();ctx.moveTo(x-r,y-r*.4);ctx.lineTo(x-r*.4,y-r);ctx.lineTo(x+r*.8,y-r*.6);ctx.lineTo(x+r,y+r*.5);ctx.lineTo(x-r*.2,y+r*.7);ctx.closePath();ctx.fill();ctx.stroke();artLine([[x-r*.4,y-r*.5],[x+r*.4,y-r*.3]],'#bbc0a044',1.3);
 }ctx.restore();
}
function entrancePatientCracks(amount=1){
 for(const x of [288,672]){ellipse(ctx,x,446,30*amount,10*amount,'#30302d55');for(let i=0;i<5;i++){const a=i*Math.PI*2/5;artLine([[x,444],[x+Math.cos(a)*22*amount,444+Math.sin(a)*13*amount],[x+Math.cos(a+.2)*43*amount,444+Math.sin(a+.2)*24*amount]],'#40493b99',1.7)}}
}
function drawBossEntranceScenery(room){
 if(room.type!=='boss')return;const intro=state.bossIntro?.inRoom&&state.bossIntro.room===state.room?state.bossIntro:null,props=room.entranceSet||{};
 if(props.fungalHole)entranceFloorHole();else if(intro?.type==='spore'&&intro.elapsed>.5)entranceFloorHole(bossRoomEntrancePose(intro).hole);
 if(props.ratRubble)entranceRatRubble();
 if(props.patientImpact)entrancePatientCracks();
 if(intro?.type==='mother'&&intro.elapsed>=1.05){
  ctx.fillStyle='#111916';ctx.strokeStyle='#343e30';ctx.lineWidth=4;ctx.beginPath();ctx.moveTo(915,239);ctx.lineTo(952,249);ctx.lineTo(961,306);ctx.lineTo(947,394);ctx.lineTo(916,408);ctx.lineTo(897,356);ctx.lineTo(908,287);ctx.closePath();ctx.fill();ctx.stroke();entranceRatRubble(bossRoomEntrancePose(intro).rubble);
 }
 if(intro?.type==='patient'&&intro.elapsed>=4.2)entrancePatientCracks(puppetEase((intro.elapsed-4.2)/.2));
}
function drawEntranceDebris(x,y,time,start,kind){
 const t=time-start;if(t<0||t>1.5)return;
 ctx.save();ctx.globalAlpha=clamp(1-t/1.5,0,1);
 for(let i=0;i<16;i++){const angle=i*2.399,travel=t*(40+i%5*18),px=x+Math.cos(angle)*travel,py=y+Math.sin(angle)*travel*.45-t*35+t*t*38;ellipse(ctx,px,py,3+i%3,2+i%3,kind==='spore'?'#a697b999':'#b1ae9299')}
 ctx.restore();
}
function bossEntranceActor(enemy,pose){return{...enemy,x:pose.x,y:pose.y,lookDirection:enemy.type==='mother'?-1:enemy.lookDirection,flash:0,enraged:enemy.type==='patient'&&pose.rage,entranceArms:enemy.type==='patient'?(pose.arms||0):0,attackMode:'normal'}}
function drawBossRoomEntrance(room){
 const intro=state.bossIntro;if(!intro?.inRoom||intro.room!==state.room)return;
 const t=intro.elapsed,pose=bossRoomEntrancePose(intro),enemy=room.enemies.find(e=>e.boss),reduce=intro.reduced;if(!enemy)return;
 if(intro.type==='mother'&&t<1.05&&t>.25){ctx.strokeStyle='#d2c39388';ctx.lineWidth=2;ctx.beginPath();ctx.moveTo(934,263);ctx.lineTo(923,288);ctx.lineTo(938,309);ctx.lineTo(921,341);ctx.lineTo(933,366);ctx.stroke()}
 if(intro.type==='patient'&&t<2.5){artLine([[453,45],[453,Math.max(48,pose.y-40)]],'#a9b7a37f',2);artLine([[507,45],[507,Math.max(48,pose.y-40)]],'#a9b7a37f',2)}
 if(pose.visible){
  ctx.save();if(intro.type==='spore'){ctx.beginPath();ctx.rect(280,30,400,Math.min(590,317+Math.max(0,t-3.1)*100));ctx.clip()}
  // All bosses retain their combat model from their first visible frame.
  const gesture=reduce?0:Math.sin(clamp((t-2.3)/1.2,0,1)*Math.PI);
  ctx.translate(pose.x,pose.y);ctx.rotate(intro.type==='mother'&&t<2.15&&!reduce?Math.sin(t*14)*.018:0);
  if(intro.type==='mother')ctx.scale(1+gesture*.018,1-gesture*.012);ctx.translate(-pose.x,-pose.y);
  renderMonster(bossEntranceActor(enemy,pose),state.elapsed+(reduce?0:t));
  ctx.restore();
 }
 if(intro.type==='patient'&&pose.arms>0){
  withScenePaint(pose.rage?'patientRage':'patient',()=>{const lift=1-pose.slam;for(const side of [-1,1]){
   const a=pose.arms,normalHandY=pose.y+1.65*(24+Math.sin((state.elapsed+(reduce?0:t))*7+side)*2);
   const root={x:480+side*36.3,y:pose.y-13.2},end={x:480+side*(57.75+134.25*a),y:normalHandY+(446-normalHandY-lift*148)*a};
   const elbow={x:480+side*(54.45+45.55*a),y:pose.y+9.9-lift*80*a};
   puppetLimb([[root.x,root.y],[elbow.x,elbow.y],[end.x,end.y]],'#c5b6a1',8.25);artOval(elbow.x,elbow.y,8.25,8.25,'#899a86','#40584c');
   for(let i=0;i<3;i++)artLine([[end.x+(i-1)*7,end.y],[end.x+(i-1)*9,end.y+14]],'#cad7ac',3);
  }});
 }
 drawEntranceDebris(intro.type==='mother'?918:480,intro.type==='mother'?320:342,t,intro.type==='mother'?1.05:intro.type==='patient'?2.15:.8,intro.type);
 if(intro.type==='patient'&&t>=4.2){drawEntranceDebris(288,446,t,4.2,'patient');drawEntranceDebris(672,446,t,4.2,'patient')}
 if(intro.type==='spore'&&t>.8&&t<4.2){ctx.save();ctx.globalAlpha=.28;for(let i=0;i<12;i++){const a=i*2.399+t*.3;ellipse(ctx,480+Math.cos(a)*(65+i%4*13),350-(t-.8)*28-i%3*12,4+i%3,4+i%3,'#c3abc9')}ctx.restore()}
}
function drawBossRoomLighting(){
 const intro=state.bossIntro;if(!intro?.inRoom)return;const t=intro.elapsed;
 if(intro.type==='patient'&&t<2.3&&!intro.reduced){const dim=[.88,.03,.94,.02,.86][Math.min(4,Math.floor(t/.46))];ctx.save();ctx.fillStyle=`rgba(3,10,12,${dim})`;ctx.fillRect(0,0,W,H);ctx.restore()}
}
function cancelBossRoomEntrance(){const intro=state?.bossIntro;if(intro?.raf)cancelAnimationFrame(intro.raf);$('#boss-room-title')?.remove();$('#overlay').classList.remove('puppet-intro','boss-intro')}
cancelBossPuppet=cancelBossRoomEntrance;
showBossIntro=function(enemy){
 const room=state.rooms[state.room],drama=BOSS_DRAMA[enemy.type];if(!drama||room.introShown)return;
 cancelBossRoomEntrance();room.introShown=true;
 const intro=state.bossIntro={type:enemy.type,room:state.room,inRoom:true,elapsed:0,duration:BOSS_ROOM_ENTRANCES[enemy.type].duration,reduced:matchMedia('(prefers-reduced-motion:reduce)').matches,last:null,raf:0,cues:{}};
 state.paused=true;state.dialog=false;keys.clear();resetTouchInput();mouse.down=false;$('#overlay').hidden=true;
 soundSfx('warning');draw();
 const frame=now=>{
  if(state.bossIntro!==intro||state.mode!=='play'||state.room!==intro.room)return;
  const dt=intro.last===null?0:Math.min(.08,Math.max(0,(now-intro.last)/1000));intro.last=now;if(!document.hidden&&!mobileNeedsRotation())intro.elapsed+=dt;
  const cfg=BOSS_ROOM_ENTRANCES[intro.type];if(!intro.cues.impact&&intro.elapsed>=cfg.impact){intro.cues.impact=true;bossPuppetSound(intro.type)}
  if(intro.type==='patient'&&!intro.cues.slam&&intro.elapsed>=cfg.slam){intro.cues.slam=true;soundSfx('break')}

  draw();if(intro.elapsed>=intro.duration){finishBossIntro();draw();return}intro.raf=requestAnimationFrame(frame);
 };intro.raf=requestAnimationFrame(frame);
};
const roomEntranceFinishBase=finishBossIntro;
finishBossIntro=function(){
 const intro=state.bossIntro;if(!intro||intro.inRoom&&intro.elapsed<intro.duration)return;
 if(intro.inRoom){const room=state.rooms[intro.room],boss=room.enemies.find(e=>e.boss);room.entranceSet={...(room.entranceSet||{}),ratRubble:intro.type==='mother',patientImpact:intro.type==='patient',fungalHole:intro.type==='spore'};if(boss){boss.x=intro.type==='mother'?690:480;boss.y=320;if(intro.type==='mother')boss.lookDirection=-1}}
 roomEntranceFinishBase();cameraKey='';if(state.levelCheckpoint?.room===state.room)captureLevelCheckpoint();
};

// Small reusable cutout rigs: torso, head, upper arms and forearms rotate separately.
const SCIENTIST_RIGS=Object.freeze({
 vera:Object.freeze({id:'vera',coat:'#b9c9b8',shade:'#748f85',skin:'#c7aa85',hair:'#9c6048',ink:'#303a39',accent:'#d59e62'}),
 ibarra:Object.freeze({id:'ibarra',coat:'#c3c2b0',shade:'#7e8991',skin:'#bcae92',hair:'#4d555b',ink:'#2e353b',accent:'#849ba5'})
});
function scientistCoat(rig){
 const high=rig.id==='ibarra',w=high?19:23;
 ctx.fillStyle=artGradient(-10,-13,45,rig.coat,rig.shade);ctx.strokeStyle=rig.ink;ctx.lineWidth=2.8;
 ctx.beginPath();ctx.moveTo(-w+5,-12);ctx.quadraticCurveTo(0,-20,w-5,-12);ctx.lineTo(w+2,22);ctx.lineTo(8,26);ctx.lineTo(1,20);ctx.lineTo(-7,27);ctx.lineTo(-w-1,23);ctx.closePath();ctx.fill();ctx.stroke();
 artLine([[0,-2],[0,18]],rig.shade,1.6);
 if(!high){artLine([[-12,-9],[-5,2],[0,-4],[6,2],[13,-9]],'#e4dcc3',2);artLine([[-2,-3],[2,10]],'#b77e58',3)}
 for(let i=0;i<3;i++)ellipse(ctx,high?3:5,5+i*6,1.1,1.1,rig.ink);
 ctx.fillStyle=rig.shade;ctx.fillRect(-15,6,9,9);artLine([[-14,9],[-7,9]],'#e8ddba',1.2);
 if(high){artLine([[9,-3],[9,7]],rig.accent,2);artLine([[13,-3],[13,6]],'#a76c5e',1.7)}
 else{ctx.fillStyle='#e5d7b8';ctx.strokeStyle=rig.ink;ctx.lineWidth=1;ctx.fillRect(10,2,8,10);ctx.strokeRect(10,2,8,10);ctx.fillStyle='#a57558';ctx.fillRect(12,4,4,3)}
}
function scientistHead(rig,time,look,expression='idle',lookY=0){
 const worried=expression==='worried',surprised=expression==='surprised',indifferent=rig.id==='ibarra',blink=(time+(indifferent?2.1:0))%5.7>5.52;
 ctx.fillStyle=rig.skin;ctx.strokeStyle=rig.ink;ctx.lineWidth=2.8;
 ctx.beginPath();if(indifferent){ctx.moveTo(-17,-15);ctx.quadraticCurveTo(-21,-30,-2,-29);ctx.quadraticCurveTo(20,-30,19,-12);ctx.lineTo(15,11);ctx.quadraticCurveTo(-2,19,-16,7)}else{ctx.moveTo(-18,-12);ctx.bezierCurveTo(-21,-29,19,-31,20,-9);ctx.quadraticCurveTo(19,15,1,15);ctx.quadraticCurveTo(-18,15,-18,-12)}ctx.closePath();ctx.fill();ctx.stroke();
 if(indifferent){
  ctx.fillStyle=rig.hair;ctx.beginPath();ctx.moveTo(-20,-14);ctx.lineTo(-18,-30);ctx.lineTo(-10,-26);ctx.lineTo(-2,-35);ctx.lineTo(10,-32);ctx.lineTo(19,-23);ctx.lineTo(20,-12);ctx.quadraticCurveTo(1,-17,-20,-14);ctx.fill();ctx.stroke();
  // Square spectacles and low eyelids carry the expression; there is no visible mouth.
  for(const x of [-16,3]){ctx.fillStyle='#c0cfcc';ctx.strokeStyle=rig.ink;ctx.lineWidth=1.8;ctx.beginPath();ctx.roundRect(x,-11,14,10,1.5);ctx.fill();ctx.stroke();const ex=x+7+look;artLine([[x+2,worried?(x<0?-8:-12):surprised?-12:-8],[x+12,worried?(x<0?-12:-8):surprised?-12:-6]],'#5e6564',1.8);if(!blink)ellipse(ctx,ex,(surprised?-5:-4.5)+lookY,1.4,worried?3.1:surprised?3.6:1.9,'#303b3a');else artLine([[x+4,-4],[x+10,-4]],rig.ink,1.3)}
  artLine([[-2,-7],[3,-7]],rig.ink,1.8);artLine([[0,-1],[-2,4],[2,5]],'#7e7968',1.3);
 }else{
  // A tied copper bun, round raised goggles and a bright, asymmetrical face.
  artOval(-19,-17,9,10,rig.hair,rig.ink);ctx.fillStyle=rig.hair;ctx.strokeStyle=rig.ink;ctx.lineWidth=2.5;ctx.beginPath();ctx.moveTo(-19,-10);ctx.quadraticCurveTo(-24,-32,0,-32);ctx.quadraticCurveTo(20,-30,21,-13);ctx.lineTo(11,-20);ctx.lineTo(6,-12);ctx.lineTo(3,-20);ctx.quadraticCurveTo(-8,-21,-19,-10);ctx.fill();ctx.stroke();
  artLine([[-15,-21],[16,-21]],'#515e61',5);for(const x of [-8,8]){artOval(x,-22,6,5,'#95b9bd',rig.ink);artLine([[x-2,-25],[x+1,-23]],'#e0e6d5',1.2)}
  for(const x of [-8,9]){artLine([[x-4,surprised?-12:-6],[x+3,surprised?-13:-8]],'#705442',1.8);if(!blink){ellipse(ctx,x,-2,2.6,3.5,'#f0dfbb');ellipse(ctx,x+look+.5,-1.5+lookY,1.3,2.3,rig.ink)}else artLine([[x-3,-2],[x+3,-2]],rig.ink,1.4)}
  artLine([[1,-2],[4,3],[0,4]],'#927e62',1.3);ctx.strokeStyle='#684d42';ctx.lineWidth=1.6;ctx.beginPath();if(expression==='talking'){ctx.ellipse(2,8,3.5,1.2+Math.abs(Math.sin(time*19))*2.8,0,0,Math.PI*2)}else if(surprised)ctx.ellipse(2,8,3.5,4.5,0,0,Math.PI*2);else{ctx.moveTo(-5,8);ctx.quadraticCurveTo(2,11,8,6)}ctx.stroke();ellipse(ctx,-11,5,3,1.4,'#b87c6366');
 }
}
function scientistAttention(x,y,pose={}){
 // Authored cinematic poses retain their own gaze, independent of gameplay.
 if(pose.look!==undefined)return {x:pose.look,y:pose.lookY||0};
 const p=state.player,range=Math.hypot(p.x-x,p.y-y),weight=clamp((205-range)/55,0,1);
 if(!weight)return {x:0,y:0};
 const target=playerAimOrigin(),dx=target.x-x,dy=target.y-(y-35),length=Math.max(45,Math.hypot(dx,dy));
 return {x:dx/length*1.5*weight,y:dy/length*.8*weight};
}
scientist=function(x,y,name,coat,index=0,pose={}){
 const rig=index?SCIENTIST_RIGS.ibarra:SCIENTIST_RIGS.vera,t=pose.time??state.elapsed,breath=Math.sin(t*2.1+index*2)*.6,attention=scientistAttention(x,y,pose),look=attention.x,indifferent=rig.id==='ibarra';
 ctx.save();ctx.translate(x,y);if(!isLegacyMobileContent()){ctx.translate(0,29);ctx.scale(.9,.9);ctx.translate(0,-29)}ctx.lineCap='round';ctx.lineJoin='round';ellipse(ctx,0,28,24,7,'#19251a55');
 for(const side of [-1,1]){artLine([[side*9,14],[side*12,28]],'#414c50',7);artOval(side*14,29,8,3,'#525e60',rig.ink)}
 ctx.translate(0,breath);
 // Hands and props stay simple enough to reuse in dialogue/cinematic poses.
 for(const side of [-1,1])puppetJoint(side*(indifferent?17:20),-7,Math.sin(t*1.8+side)*.025+(pose.arms?.[side<0?0:1]||0),()=>{
  const bent=(!indifferent&&side===1&&!pose.noTablet),elbow=[side*6,14],hand=[side*(bent?-2:7),bent?10:24];
  puppetLimb([[0,0],elbow,hand],rig.coat,7);artOval(hand[0],hand[1],3.5,4.5,rig.skin,rig.ink);
  if(bent){ctx.fillStyle='#4a6969';ctx.strokeStyle=rig.ink;ctx.lineWidth=2;ctx.beginPath();ctx.roundRect(-12,4,20,25,2);ctx.fill();ctx.stroke();artLine([[-8,10],[4,10]],'#b9c8a4',1.5);artLine([[-8,16],[0,16]],'#b9c8a4',1.2)}
 });
 scientistCoat(rig);
 if(!indifferent&&!pose.noTablet){ctx.save();ctx.translate(20,1);ctx.rotate(-.12);ctx.fillStyle='#4a6969';ctx.strokeStyle=rig.ink;ctx.lineWidth=2;ctx.beginPath();ctx.roundRect(-3,-2,17,25,2);ctx.fill();ctx.stroke();artLine([[0,4],[10,4]],'#b9c8a4',1.5);artLine([[0,10],[7,10]],'#b9c8a4',1.2);artOval(-3,13,3,4,rig.skin,rig.ink);ctx.restore()}

 puppetJoint(look*(pose.lookDown?1.2:0),-29+(pose.lookDown||0)*1.5,look*(pose.headTurn??.035)+(pose.lookDown||0)*.12+Math.sin(t*.8+index)*.012,()=>scientistHead(rig,t,look,pose.expression,attention.y));
 if(indifferent){
  // A stiff, tall collar sits in front of the lower face and hides the mouth.
  ctx.fillStyle=artGradient(0,-24,35,'#d4d0bb','#869199');ctx.strokeStyle=rig.ink;ctx.lineWidth=2.5;ctx.beginPath();ctx.moveTo(-20,-23);ctx.quadraticCurveTo(0,-18,20,-23);ctx.lineTo(18,-3);ctx.lineTo(4,2);ctx.lineTo(-18,-4);ctx.closePath();ctx.fill();ctx.stroke();artLine([[3,-20],[3,-2]],'#6c7b82',1.5);artLine([[-15,-15],[-6,-13]],'#e5dec6',1.2);
 }
 ctx.restore();ctx.save();ctx.textAlign='center';ctx.fillStyle='#e7dec0';ctx.strokeStyle='#35402f';ctx.lineWidth=3;ctx.font='bold 11px monospace';ctx.strokeText(name,x,y+48);ctx.fillText(name,x,y+48);ctx.restore();
};

// Preserve the actor palette even when the whole bunker uses a gray paint scope.
const coloredScientist=scientist;
scientist=function(...args){return withScenePaint('raw',()=>coloredScientist(...args))};

// In-game inventory and responsive camera. Room geometry defines the world bounds independently of the screen.
let portraitRendering=false;
let inventoryWasPaused=false,closeView=true,cameraKey='',cameraX=480,cameraY=320;
let screenProjection={x:0,y:0,w:W,h:H,dx:0,dy:0,dw:W,dh:H};
const worldFrame=document.createElement('canvas');worldFrame.width=W;worldFrame.height=H;
const worldFrameContext=worldFrame.getContext('2d');
function screenToWorld(x,y,width,height){const p=screenProjection,sx=x*canvas.width/width,sy=y*canvas.height/height;return{x:clamp(p.x+(sx-p.dx)/p.dw*p.w,0,worldSize().width),y:clamp(p.y+(sy-p.dy)/p.dh*p.h,0,worldSize().height)}}
function customSceneProjection(ww,wh,focusX,focusY,closeHeight=640){
 if(!closeView){const scale=Math.min(canvas.width/ww,canvas.height/wh),dw=ww*scale,dh=wh*scale;return{x:0,y:0,w:ww,h:wh,dx:(canvas.width-dw)/2,dy:(canvas.height-dh)/2,dw,dh}}
 const aspect=canvas.width/canvas.height;let h=Math.min(wh,closeHeight),w=h*aspect;if(w>ww){w=ww;h=w/aspect}return{x:clamp(focusX-w/2,0,Math.max(0,ww-w)),y:clamp(focusY-h/2,0,Math.max(0,wh-h)),w,h,dx:0,dy:0,dw:canvas.width,dh:canvas.height}
}
function drawCustomScene(drawer,ww,wh,focusX,focusY,closeHeight,bg='#101715',offsetX=0,offsetY=0){
 const p=customSceneProjection(ww,wh,focusX,focusY,closeHeight);p.x=clamp(p.x-offsetX*p.w/p.dw,0,Math.max(0,ww-p.w));p.y=clamp(p.y-offsetY*p.h/p.dh,0,Math.max(0,wh-p.h));ctx.save();ctx.setTransform(1,0,0,1,0,0);ctx.fillStyle=bg;ctx.fillRect(0,0,canvas.width,canvas.height);ctx.beginPath();ctx.rect(p.dx,p.dy,p.dw,p.dh);ctx.clip();ctx.setTransform(p.dw/p.w,0,0,p.dh/p.h,p.dx-p.x*p.dw/p.w,p.dy-p.y*p.dh/p.h);withScenePaint('raw',drawer);ctx.restore();screenProjection=p;return p
}
function inventoryVisible(){return !$('#inventory-screen').hidden}
function hideInventory(){ $('#inventory-screen').hidden=true;document.body.classList.remove('inventory-open');$('#touch-equipment').setAttribute('aria-expanded','false') }
function openInventory(){
 if(typeof originIntro!=='undefined'&&originIntro||typeof allyEncounter!=='undefined'&&allyEncounter||typeof characterSelection!=='undefined'&&characterSelection)return;
 if(!['play','bunker'].includes(state.mode)||state.bossIntro)return;
 inventoryWasPaused=state.paused&&!state.dialog&&!$('#overlay').hidden;
 state.dialog=false;state.paused=true;state.map=false;keys.clear();resetTouchInput();mouse.down=false;$('#overlay').hidden=true;
 $('#inventory-screen').hidden=false;document.body.classList.add('inventory-open');$('#touch-equipment').setAttribute('aria-expanded','true');
 $('#touch-back').textContent=inventoryWasPaused?'Volver a pausa':'Volver al juego';
 refresh();$('#touch-back').focus({preventScroll:true});
}
function closeInventory(){hideInventory();keys.clear();resetTouchInput();mouse.down=false;state.dialog=false;if(inventoryWasPaused){state.paused=true;showPauseMenu()}else{state.paused=false;$('#overlay').hidden=true}$('#touch-equipment').focus({preventScroll:true})}
function syncInterface(){
 if(!state)return;const p=state.player;
 $('#inventory-screen .inventory-heading p').textContent=state.mode==='bunker'?'Elegí tu equipo antes de salir.':'La partida está pausada. Organizá tu equipo.';
 $('#shield-heart-status').hidden=!p.shieldHeart;
 $('#inventory-screen .subject h2').textContent=p.characterId==='voss'?'DR. DARÍO VOSS':p.characterId==='infected'?'HUMANO INFECTADO':'MOHO';
 $('#inventory-screen .subject p').textContent=p.characterId==='voss'?'Investigador · Fuego y vuelo':p.characterId==='infected'?'Floración partida':'Arcilla viviente';
 $('#inventory-screen .inventory-heading h2').textContent=p.characterId==='voss'?'Mochila de Darío':p.characterId==='infected'?'Mochila del infectado':'Mochila de MOHO';
 $('#hud-player-level').textContent=`${characterRig(p).name} · NIV. ${p.level}`;
 $('#equipment-slot-count').textContent=`${equipmentSlotKeys().length} RANURAS`;
 $('#hud-xp').textContent=`${p.xp} / ${xpTarget()} XP · ${p.bag.length}/${p.capacity} objetos`;
 for(const button of $('#inventory').querySelectorAll('[data-equip]')){const item=p.bag[Number(button.dataset.equip)],card=button.closest('.bag-item');card.classList.toggle('equipped',isItemEquipped(item,p))}
}
function updateBattleInterface(){
 const room=state.rooms[state.room],boss=state.mode==='play'?room.enemies.find(e=>e.boss&&e.hp>0):null;
 const hud=$('#boss-hud');hud.hidden=!boss||state.map||!!state.bossIntro;
 if(boss){const name=LEVELS[state.levelIndex].boss.toUpperCase(),phase=bossAttackLabel(boss),hp=`${healthNumber(boss.hp)} / ${healthNumber(boss.max)}`;if($('#boss-hud-name').textContent!==name)$('#boss-hud-name').textContent=name;if($('#boss-hud-phase').textContent!==phase)$('#boss-hud-phase').textContent=phase;$('#boss-hud-health').textContent=hp;$('#boss-hud-fill').style.width=`${clamp(boss.hp/boss.max,0,1)*100}%`}
 const countdown=$('#encounter-countdown'),waiting=state.mode==='play'&&room.entryDelay>1e-8&&!state.bossIntro&&!state.map&&!window.COLLECTOR_MINIBOSS?.active&&!window.BULL_SHARK_MINIBOSS?.active&&!window.SCRAPY_TITAN_BOSS?.active;countdown.hidden=!waiting;if(waiting)countdown.innerHTML=`${Math.ceil(room.entryDelay)}<small>PREPARATE</small>`;
 const toast=$('#game-toast'),near=state.mode==='bunker'?nearestBunkerObject():null,message=state.toastTime>0?state.toast:near?(near.decorative?`${near.label} · Próximamente`:`Usar · ${near.action} — ${near.label}`):'';toast.hidden=!message||inventoryVisible()||state.map||!!state.bossIntro;if(!toast.hidden&&toast.textContent!==message)toast.textContent=message;
 const caption=$('#boss-death-caption'),words=state.bossLastWords;caption.hidden=!words||state.map;if(words&&!caption.hidden){const content=`<small>${words.name}</small>«${words.text}»`;if(caption.innerHTML!==content)caption.innerHTML=content}
}
function sizeGameSurface(){
 const mobile=isMobileGame(),portrait=matchMedia('(pointer:coarse), (max-width:760px)').matches&&innerHeight>innerWidth,desired=portrait?900:640;
 // Keep the world in logical units; the backing surface follows screen density on all platforms.
 const bounds=canvas.getBoundingClientRect(),physicalWidth=Math.min(3072,Math.max(960,bounds.width*Math.min(2,devicePixelRatio||1))),width=Math.floor(physicalWidth/3)*3,height=Math.round(width*(mobile?desired/960:2/3));
 if(canvas.width!==width||canvas.height!==height){canvas.width=width;canvas.height=height;cameraKey=''}
 canvas.style.aspectRatio=mobile?`960 / ${desired}`:'3 / 2';canvas.style.imageRendering='auto';return mobile&&portrait;
}
const interfaceDrawBase=draw;
draw=function(){
 const portrait=sizeGameSurface(),ww=worldSize().width,wh=worldSize().height;
 const desktopHD=true; // All platforms render vectors at screen resolution.
 if(!desktopHD){if(worldFrame.width!==ww||worldFrame.height!==wh){worldFrame.width=ww;worldFrame.height=wh}
 const screenContext=ctx;ctx=worldFrameContext;try{ctx.clearRect(0,0,ww,wh);interfaceDrawBase()}finally{ctx=screenContext}}
 ctx.save();ctx.setTransform(1,0,0,1,0,0);ctx.fillStyle='#17221f';ctx.fillRect(0,0,canvas.width,canvas.height);
 const full=!closeView||state.map||!!state.rooms[state.room]?.training||state.bossIntro?.inRoom||state.mode==='bunker'&&state.bunkerFloor===1;
 if(full){const scale=Math.min(canvas.width/ww,canvas.height/wh),dw=ww*scale,dh=wh*scale,dx=(canvas.width-dw)/2,dy=(canvas.height-dh)/2;if(!desktopHD)ctx.drawImage(worldFrame,0,0,ww,wh,dx,dy,dw,dh);screenProjection={x:0,y:0,w:ww,h:wh,dx,dy,dw,dh}}
 else{const aspect=canvas.width/canvas.height,fw=portrait?H*aspect:W/1.08,fh=fw/aspect,key=`${state.mode}:${state.levelIndex}:${state.room}:${canvas.height}`,targetX=clamp(state.player.x,fw/2,ww-fw/2),targetY=clamp(state.player.y,fh/2,wh-fh/2);if(cameraKey!==key){cameraX=targetX;cameraY=targetY;cameraKey=key}else{cameraX+=(targetX-cameraX)*.15;cameraY+=(targetY-cameraY)*.15}const x=cameraX-fw/2,y=cameraY-fh/2;if(!desktopHD)ctx.drawImage(worldFrame,x,y,fw,fh,0,0,canvas.width,canvas.height);screenProjection={x,y,w:fw,h:fh,dx:0,dy:0,dw:canvas.width,dh:canvas.height}}
 // Draw vectors through the camera directly, matching conversation quality without enlarging a bitmap.
 if(desktopHD){
  const p=screenProjection,quality=window.CONVERSATION_RENDER_SCALE;
  try{
   window.CONVERSATION_RENDER_SCALE=Math.min(4,Math.max(2,Math.ceil(p.dw/p.w)));
   ctx.imageSmoothingEnabled=true;ctx.imageSmoothingQuality='high';ctx.lineJoin='round';ctx.lineCap='round';ctx.miterLimit=2;
   ctx.beginPath();ctx.rect(p.dx,p.dy,p.dw,p.dh);ctx.clip();
   ctx.setTransform(p.dw/p.w,0,0,p.dh/p.h,p.dx-p.x*p.dw/p.w,p.dy-p.y*p.dh/p.h);
   interfaceDrawBase();
  }finally{window.CONVERSATION_RENDER_SCALE=quality;ctx.restore()}
 }else ctx.restore();updateBattleInterface();
};
// Enlarge bodies around their existing world positions, preserving the hand-drawn proportions.
const interfaceMonsterBase=renderMonster;
renderMonster=function(enemy,time){ctx.save();ctx.translate(enemy.x,enemy.y);const scale=portraitRendering?1:enemy.boss?1.16:enemy.type==='brute'?1.16:1.23;ctx.scale(scale,scale);ctx.translate(-enemy.x,-enemy.y);interfaceMonsterBase(enemy,time);ctx.restore()};
const interfaceMohoBase=drawMoho;
drawMoho=function(){const p=state.player;ctx.save();ctx.translate(p.x,p.y);const rig=characterRig(p),scale=rig.renderScale*(p.r/18);ctx.scale(scale,scale);ctx.translate(-p.x,-p.y-rig.groundAnchor);interfaceMohoBase();ctx.restore();drawMohoShield()};
const interfacePortraitBase=makeBossPortrait;
makeBossPortrait=function(enemy){const oldHeight=canvas.height;portraitRendering=true;canvas.height=H;try{return interfacePortraitBase(enemy)}finally{portraitRendering=false;canvas.height=oldHeight;cameraKey='';draw()}};
// These world-space captions are replaced by larger, screen-anchored UI.
drawRefinedBossBar=function(){};drawRoomEntryCountdown=function(){};drawBossLastWords=function(){};
const interfaceRefreshBase=refresh;
refresh=function(){interfaceRefreshBase();syncInterface()};
const interfaceCloseBase=closeDialog;
closeDialog=function(){hideInventory();interfaceCloseBase()};
const interfaceResetBase=reset;
reset=function(){hideInventory();cameraKey='';interfaceResetBase()};
const interfacePauseBase=showPauseMenu;
showPauseMenu=function(){interfacePauseBase();const button=document.createElement('button');button.id='pause-inventory';button.textContent='Mochila y equipo →';button.onclick=openInventory;$('#overlay .pause-actions').append(button)};
const interfaceTogglePause=togglePause;
togglePause=function(){if(inventoryVisible()){closeInventory();return}interfaceTogglePause()};
$('#touch-equipment').onclick=()=>openInventory();$('#touch-back').onclick=()=>closeInventory();
$('#inventory-sort').onclick=()=>{const order={weapon:0,charm:1,active:2,passive:3};state.player.bag.sort((a,b)=>(order[a.slot]-order[b.slot])||a.name.localeCompare(b.name,'es'));notify('Mochila ordenada por tipo.');refresh()};
$('#prepare-exit').onclick=()=>{hideInventory();prepareExit()};
enterTutorial=function(){prepareExit()};
$('#view-toggle').onclick=()=>{closeView=!closeView;cameraKey='';$('#view-toggle').textContent=closeView?'Vista completa':'Vista cercana';draw()};
$('#inventory-screen .panel-title').style.display='none';
function spawnTestShieldHeart(){
 if(state.mode!=='play'){notify('Entrá al tutorial para probar el corazón de escudo con I.');return false}
 if(state.paused||state.map||state.bossIntro)return false;
 const room=state.rooms[state.room],p=state.player,bounds=roomBounds();
 const candidates=Array.from({length:8},(_,i)=>({x:clamp(p.x+Math.cos(i*Math.PI/4)*52,bounds.left,bounds.right),y:clamp(p.y+Math.sin(i*Math.PI/4)*52,bounds.top,bounds.bottom)}));
 const point=candidates.find(q=>distance(q,p)>30&&!room.obstacles.some(o=>distance(q,o)<o.r+20))||{x:p.x,y:p.y};
 room.drops.push({kind:'shield',...point});notify('Prueba: corazón de escudo generado · Solo podés llevar una carga.');return true;
}
window.addEventListener('keydown',event=>{
 if(typeof originIntro!=='undefined'&&originIntro||typeof allyEncounter!=='undefined'&&allyEncounter||typeof characterSelection!=='undefined'&&characterSelection)return;
 if(typeof infectedAllyPreview!=='undefined'&&infectedAllyPreview)return;
 const key=event.key.toLowerCase();
 if(inventoryVisible()){
  if(['escape','b'].includes(key)){event.preventDefault();event.stopImmediatePropagation();if(!event.repeat)closeInventory();return}
  if(key==='tab'){const controls=[...$('#inventory-screen').querySelectorAll('button:not([disabled])')].filter(e=>e.getClientRects().length);const first=controls[0],last=controls[controls.length-1];if(event.shiftKey&&document.activeElement===first){event.preventDefault();last.focus()}else if(!event.shiftKey&&document.activeElement===last){event.preventDefault();first.focus()}}return;
 }
 if(key==='i'&&!event.repeat){event.preventDefault();event.stopImmediatePropagation();spawnTestShieldHeart();return}
 if(key==='b'&&!event.repeat&&!state.bossIntro&&['play','bunker'].includes(state.mode)){event.preventDefault();event.stopImmediatePropagation();openInventory()}
},true);

// Equipped items live in their slots; the backpack contains only unequipped objects.
(function installInventoryExchange(){
 function decorate(){
  if(!state?.player)return;const p=state.player,slots=equipmentSlotKeys();
  [...$('#equipment').children].forEach((card,index)=>{const slot=slots[index],item=p.equipment[slot];card.dataset.equipmentSlot=slot;if(item&&!card.querySelector('[data-unequip-slot]')){const button=document.createElement('button');button.className='equipment-return';button.dataset.unequipSlot=slot;button.textContent='Guardar en mochila';card.append(button)}});
  if(state.mode==='bunker')for(const [index,card]of [...$('#inventory').querySelectorAll('.bag-item')].entries())if(!card.querySelector('[data-discard-index]')){const button=document.createElement('button');button.className='drop';button.dataset.discardIndex=index;button.textContent='Soltar';card.append(button)}
  $('#inventory-help').textContent=state.mode==='bunker'?`Mochila: ${p.bag.length}/${p.capacity}. Todo su contenido y el equipo puesto viajan con vos. Guardá en la caja lo que quieras dejar.`:`Mochila: ${p.bag.length}/${p.capacity}. El equipo puesto no ocupa espacio.`;
 }
 const refreshBase=refresh;refresh=function(){refreshBase();decorate()};
 $('#equipment').addEventListener('click',event=>{const button=event.target.closest('[data-unequip-slot]');if(!button||!['play','bunker'].includes(state.mode))return;if(returnEquippedItem(button.dataset.unequipSlot))refresh()});
 $('#inventory').addEventListener('click',event=>{const button=event.target.closest('[data-discard-index]');if(!button||state.mode!=='bunker')return;const p=state.player,index=Number(button.dataset.discardIndex),item=p.bag[index];if(!item)return;p.bag.splice(index,1);state.selected=state.selected.filter(uid=>uid!==item.uid);notify(`${item.name} fue descartado para liberar espacio.`);refresh()});
 prepareExit=function(){if(state.mode!=='bunker')return;const p=state.player,equipped=equipmentSlotKeys(p).map(slot=>p.equipment[slot]).filter(Boolean);dialog('¿Listo para salir?',`Tu mochila completa (${p.bag.length} ${p.bag.length===1?'objeto':'objetos'}) y tu equipo puesto (${equipped.length}) viajarán con vos. Guardá en la caja lo que quieras dejar en el búnker.`, 'Entrar al tutorial A →',launchExpedition)};
 const launchBase=launchExpedition;launchExpedition=function(){if(state.mode!=='bunker')return launchBase();const equipped={...state.player.equipment},result=launchBase();if(result){state.player.equipment=equipped;normalizeEquipment(state.player);refresh()}return result};
})();

