  if(!rear){line([[0,-32],[1,-9]],shade,1.6);for(let i=0;i<3;i++)for(const n of [-1,1])line([[n*2,-29+i*6],[n*9,-26+i*6],[n*12,-28+i*6]],'#7c7b60',1.2);ellipse(ctx,1,0,1.4,2,model.dark)}
