 for(const button of el.querySelectorAll('[data-ally-model]'))button.onclick=()=>{infectedAllyModel=preview.model=button.dataset.allyModel;const ally=state.rooms[state.room]?.infectedAlly;if(ally)ally.model=preview.model;for(const b of el.querySelectorAll('[data-ally-model]'))b.setAttribute('aria-pressed',String(b===button))};
 for(const button of el.querySelectorAll('[data-ally-view]'))button.onclick=()=>{preview.view=button.dataset.allyView;for(const b of el.querySelectorAll('[data-ally-view]'))b.setAttribute('aria-pressed',String(b===button))};
