function originAudioUpdate(intro=originIntro){
 if(!intro||document.hidden)return;const audio=originEnsureAudio(intro);if(!audio||audio.closed||!SOUND.enabled)return;
 const beat=Math.floor(intro.elapsed/.4),shot=originShotAt(intro.elapsed);
 if(SOUND.musicEnabled&&audio.lastBeat!==beat){
  audio.lastBeat=beat;const now=SOUND.ctx.currentTime+.01,warm=shot.index>=7,tense=shot.index>=4&&shot.index<=6,root=warm?48:tense?40:45,seq=warm?[12,16,19,23,19,16,14,19]:[12,19,15,22,19,12,15,14],hz=n=>440*Math.pow(2,(n-69)/12);
  const note=(midi,duration,volume,type='triangle',delay=0)=>{audioTone(hz(midi),duration,volume,type,audio.music,now+delay);audio.notes++;SOUND.noteCount++};
  if(beat%2===0)note(root+seq[(beat/2)%8],tense?.25:.65,tense?.055:.075,warm?'sine':'triangle');
  if(beat%8===0){for(const interval of [0,warm?4:3,7])note(root+interval,2.2,.048,'sine');note(root-12,1.25,.07,'sine')}
 }
 // Only cues near the current frame are played; enabling sound later never
 // replays earlier events in a burst, and hidden tabs do not advance the film.
 for(const event of ORIGIN_SOUND_EVENTS)if(intro.elapsed>=event.time&&!intro.cues.has(event.id)){intro.cues.add(event.id);if(intro.elapsed-event.time<.25&&SOUND.sfxEnabled)originFoley(intro,event.kind)}
}
function stopOriginAudio(intro){
 const audio=intro?.audio;if(!audio||audio.closed)return;audio.closed=true;
 for(const source of audio.noise){try{source.stop()}catch{}}audio.noise.clear();
 const at=SOUND.ctx.currentTime;audio.music.gain.setTargetAtTime(0,at,.015);audio.sfx.gain.setTargetAtTime(0,at,.015);setTimeout(()=>{audio.music.disconnect();audio.sfx.disconnect();for(const node of audio.ambience||[])node.disconnect()},90);
}
