 function drawUpperMap(c,w,h,ox=0,oy=0){c.save();c.translate(ox,oy);c.fillStyle='#472c3d';c.fillRect(0,0,w,h);c.scale(w/1080,h/720);for(const r of furnishings){c.fillStyle='#c088ad';c.fillRect(r.x-r.w/2,r.y-r.h/2,r.w,r.h)}ellipse(c,platform.x,platform.y,30,24,'#e5a4d0');const npc=guestPosition();if(guestIsHere())ellipse(c,npc.x,npc.y,14,14,'#bd85aa');ellipse(c,state.player.x,state.player.y,14,14,'#ffbdef');c.restore()}
 function talkToGuest(){
  if(state.mode!=='bunker'||elevator||!guestIsHere())return;const other=waitingCharacter();
  const swap=()=>{if(window.BUNKER_SWAP){BUNKER_SWAP.exchange(other);closeDialog();return}const npc={...(window.RESIDENT_ROUTINE?.owns(other)?RESIDENT_ROUTINE.spawnFor(other):guestPosition())},old={x:state.player.x,y:state.player.y};applyCharacter(other);state.player.x=npc.x;state.player.y=npc.y;state.guestPosition=state.bunkerFloor===1?old:{...seat};window.RESIDENT_ROUTINE?.sync();closeDialog();cameraKey='';refresh();notify(other==='infected'?'Ahora jugás con el humano infectado. Moho se queda descansando.':'Ahora jugás con Moho. Tu amigo se queda descansando.')};
  if(window.CHARACTER_CONVERSATIONS){
   const lines=other==='infected'?[
    'Me encerré en esa habitación porque todavía podía decidir. Vi tus peleas por la rendija. Cuando volviste después de vencer al hongo… pensé que tal vez podía confiar en alguien otra vez.',
    'Todavía me cuesta sentarme cerca de una ventana. Me acostumbré a mirar todo desde una puerta cerrada. Gracias por no intentar abrirla a golpes.',
    'Mis disparos son lentos y apenas golpean, pero el veneno se acumula. Si acierto cuatro veces, puedo frenarlos. No hace falta que peleemos igual para ayudarnos.',
    'Cuando esquivo, dejo esporas. Cuando me lastiman, el hongo reacciona y suelta una nube. No me gusta que lo haga sin preguntar… pero estoy aprendiendo a usarlo.',
    'Ese Corazón del micelio… sé de dónde viene. Sentí esa misma red dentro de mí cuando todavía intentaba controlarme. No me gusta tenerlo cerca; bastante llevo ya bajo la piel.',
    'Vera me preguntó si quería descansar antes de estudiarme. Fue raro que alguien preguntara primero. Ibarra fingió que no le importaba y después me dejó una manta.',
    'Allá adentro pensé que todos eran enemigos. Después apareció una bolita de arcilla y me ofreció una mano absurdamente detallada. Todavía me río cuando lo recuerdo.'
   ]:[
    'Moho te mira, asiente y deja un lugar a su lado. Después señala la puerta y levanta la mano: parece dispuesto a acompañarte de nuevo.',
    'Moho se estira entre los almohadones y te saluda con entusiasmo. No dice nada, pero su sonrisa deja bastante claro que se alegra de verte.',
    'Moho observa tus hongos, se señala a sí mismo y mueve los brazos como si estuviera peleando. Después te ofrece la mano. La invitación se entiende sin palabras.'
   ];
   return CHARACTER_CONVERSATIONS.start(other,lines[guestChatIndex++%lines.length],{anchor:{...guestPosition()},reaction:'happy',secondaryAction:other==='infected'?'Jugar como el infectado':'Jugar como Moho',secondaryCallback:swap});
  }
  dialog(other==='infected'?'Humano infectado':'MOHO',other==='infected'?'El humano levanta la mirada y sonríe. «Vi cómo peleabas allá abajo. Ahora… me gustaría ayudarte. Mis disparos son lentos, pero el veneno crece con cada impacto. Si acierto cuatro veces, también puedo frenarlos. Mi esquiva deja gas, y al recibir daño libero una nube. Cada nube puede sumar veneno o renovar el máximo una vez por enemigo. ¿Me dejás intentarlo?»':'Moho descansa entre los almohadones. Al verte, levanta su mano y sonríe. Parece dispuesto a volver a explorar.',other==='infected'?'Jugar como el humano infectado':'Jugar como Moho',swap);
 }

 function scientistWelcome(options={}){
  const text=!isMobileGame()?'Tenemos una habitación para huéspedes en el segundo piso. La plataforma P del centro es el ascensor. Arriba hay una cama y un sofá para descansar. Tu amigo te espera allí: subí a visitarlo y, cuando termine el día, podrás acostarte con Moho para pasar al siguiente.':'«Teníamos preparado un segundo piso para huéspedes… pero todavía no habíamos tenido ninguno. Me alegra que hayas encontrado un nuevo amigo. Podemos conocerlo mejor y estudiarlo, si él quiere. La plataforma P del centro es el ascensor: arriba hay una cama, un sofá enorme y un lugar tranquilo para descansar. Tu amigo ya te está esperando.»';
  const done=()=>{ALLY_PROFILE.guestBriefed=true;saveAllyProfile();closeDialog();notify('La plataforma P sube a la habitación de huéspedes.');refresh();GAME_EVENTS.emit('ally:guest-briefed',{})};
  if(!isMobileGame()&&options.arrival)return CHARACTER_CONVERSATIONS.start('vera',text,{action:'Ir a conocer la habitación',unskippable:true,chain:true,minWidth:1000,protectedActors:options.protectedActors,reaction:'happy',callback:done});
  dialog('Dra. Vera · Un huésped, por fin',text,'Ir a conocer la habitación',done);
 }

 function cancelElevator(){if(!elevator)return;if(elevator.raf)cancelAnimationFrame(elevator.raf);stopOriginAudio(elevator);elevator=null;$('#guest-elevator')?.remove()}
