   const f=clamp(trip.elapsed/trip.duration,0,1),motion=entranceSmooth(f),y=trip.to===1?510-motion*690:-80+motion*590;
   ctx.fillStyle='#1b242b';ctx.fillRect(0,0,960,640);for(let i=0;i<9;i++){const gy=((i*110+motion*(trip.to?720:-720))%780+780)%780-70;originRect(282,gy,396,86,'#354149','#18252d',4);artLine([[302,gy+14],[658,gy+14]],'#65716f',2)}
   for(const x of [300,660])artLine([[x,0],[x,640]],'#aaa99a',5);
   ctx.save();ctx.translate(0,y);drawLiftPad(480,12,trip.elapsed);drawGuestCharacter(state.player.characterId||'moho',480,-8,trip.elapsed);ctx.restore();
