  hideInventory();state.paused=true;keys.clear();resetTouchInput();mouse.down=false;
  const layer=document.createElement('section');layer.id='guest-elevator';layer.setAttribute('role','dialog');layer.setAttribute('aria-label','Ascensor del búnker');layer.style.cssText='position:absolute;inset:0;z-index:40;background:#1b242b;display:grid;place-items:center;pointer-events:auto';layer.innerHTML='<canvas width="960" height="640" style="width:100%;height:100%;object-fit:contain" aria-label="La plataforma P viaja entre los dos pisos"></canvas>';
  $('.viewport').append(layer);elevator={to,elapsed:0,last:null,duration:2.2,raf:0,canvas:layer.querySelector('canvas'),cues:new Set()};soundSfx('door');drawElevator();
  const trip=elevator,frame=now=>{if(elevator!==trip)return;const dt=trip.last===null?0:Math.min(.08,(now-trip.last)/1000);trip.last=now;if(!document.hidden&&!mobileNeedsRotation())trip.elapsed+=dt;drawElevator();if(trip.elapsed>=trip.duration){finishElevator();return}trip.raf=requestAnimationFrame(frame)};trip.raf=requestAnimationFrame(frame);
