   const id=playableCharacterAllowed(ALLY_PROFILE.selected)?ALLY_PROFILE.selected:'moho';if(!records[id])records[id]=freshRecord(seed,id);state.player={...state.player,...restore(records[id],id),characterId:id};clearTransient(state.player);state.selected=(records[id].selected||[]).filter(uid=>state.player.bag.some(i=>i.uid===uid));baseApply(id,false);
