 function updateHud(){
  const infected=state.player.characterId==='infected';document.body.classList.toggle('infected-hud',infected);hud.hidden=!infected;
  if(!infected)return;const p=state.player,item=p.equipment.active,cooldown=p.activeCooldown||(item?.cooldown||3);
  hud.querySelector('b').textContent=item?.name||'Paso de esporas';hud.querySelector('small').textContent=p.cool>0?`RECARGA · ${p.cool.toFixed(1)} s`:item?'LISTO · ACTIVABLE':'LISTO · GAS VENENOSO';hud.style.setProperty('--ready',`${Math.round((1-clamp(p.cool/cooldown,0,1))*100)}%`);hud.classList.toggle('native-recharging',p.cool>0);
 }
 const baseActive=useEquippedActive;
 useEquippedActive=function(dx=0,dy=0){
  if(!native())return baseActive(dx,dy);
  const p=state.player;if(state.mode!=='play'||state.paused||state.map||p.cool>0||state.rooms[state.room].entryDelay>1e-8)return false;
  const len=Math.hypot(dx,dy),a=p.lastMoveAngle??p.facing;p.activeDashX=len?dx/len:Math.cos(a);p.activeDashY=len?dy/len:Math.sin(a);p.dash=.11;p.dashVictims=[];p.cool=3;p.activeCooldown=3;p.inv=Math.max(p.inv,.18);p.activeReadyFlash=0;
  const cloud={kind:'infectedGas',infectionId:++gasId,infectionVictims:[],infectionPower:INFECTED_INFECTION.infectionPower()*INFECTED_INFECTION.sporeDamage(),x:p.x-p.activeDashX*12,y:p.y-p.activeDashY*12,trail:[],r:38*1.25*INFECTED_INFECTION.sizeBonus(),life:3*INFECTED_INFECTION.durationBonus(),tick:0,damagePerTick:INFECTED_INFECTION.infectionPower()*.5*INFECTED_INFECTION.sporeDamage()};cloud.trail.push({x:cloud.x,y:cloud.y});state.friendlyHazards.push(cloud);p.nativeGasCloud=cloud;soundSfx('dash');burst(p.x,p.y,'#b4c39a',7);updateActiveButton();updateHud();return true;
 };
 const baseMove=moveBody;moveBody=function(body,dx,dy,dt){if(body===state.player&&body.characterId==='infected'&&body.nativeGasCloud&&body.dash>0){dx*=2.2/3.2;dy*=2.2/3.2}baseMove(body,dx,dy,dt)};
 const baseEffects=updateBossItemEffects;
 updateBossItemEffects=function(dt){baseEffects(dt);const p=state.player,cloud=p.nativeGasCloud;if(!cloud)return;if(p.dash>0&&state.friendlyHazards.includes(cloud)){const point={x:p.x-p.activeDashX*12,y:p.y-p.activeDashY*12},last=cloud.trail[cloud.trail.length-1];if(distance(point,last)>=8)cloud.trail.push(point)}else p.nativeGasCloud=null};
