   while(e.t<=0&&volleys++<4){const count=Math.min(cfg.count,Math.max(0,1000-state.bullets.length));if(count){soundSfx('enemyShot');for(let i=0;i<count;i++){const aim=angle+(cfg.count>1?(i/(cfg.count-1)-.5)*1.6:0),speed=cfg.speed*(controlState.unlocked?1:difficultySettings().bullet);state.bullets.push({x:e.x,y:muzzleY,vx:Math.cos(aim)*speed,vy:Math.sin(aim)*speed,r:cfg.size,life:Math.min(12,Math.max(2,1200/cfg.speed)),kind:'normal',trainingBullet:true})}}e.t+=1/cfg.rate}
