 const baseMove=moveBody;moveBody=function(body,dx,dy,dt){if(body!==state.player||!nativeInside()){baseMove(body,dx,dy,dt);return}const count=Math.max(1,Math.ceil(Math.hypot(dx,dy)*dt/5));for(let i=0;i<count;i++){baseMove(body,dx,dy,dt/count);for(const r of state.rooms[state.room].obstacles.filter(o=>o.shopSolid)){const x=clamp(body.x,r.x,r.x+r.w),y=clamp(body.y,r.y,r.y+r.h),vx=body.x-x,vy=body.y-y,d=Math.hypot(vx,vy);if(d<body.r){if(d>.001){body.x=x+vx/d*(body.r+.1);body.y=y+vy/d*(body.r+.1)}else{const edges=[{axis:'x',value:r.x-body.r-.1,d:body.x-r.x},{axis:'x',value:r.x+r.w+body.r+.1,d:r.x+r.w-body.x},{axis:'y',value:r.y-body.r-.1,d:body.y-r.y},{axis:'y',value:r.y+r.h+body.r+.1,d:r.y+r.h-body.y}];const edge=edges.sort((a,b)=>a.d-b.d)[0];body[edge.axis]=edge.value}}}}};
 const baseShoot=shootPlayer;shootPlayer=function(angle){const p=state.player,start=state.shots.length;baseShoot(angle);const weapon=p.equipment.weapon;for(const b of state.shots.slice(start)){if(weapon?.pierces||weapon?.returningBlade){b.piercesLeft=weapon.returningBlade?99:weapon.pierces;b.hitTargets=[]}if(b.piercesLeft>0)b.pierceCapacity=b.piercesLeft;if(weapon?.returningBlade){b.shopReturnAge=0;b.life=1.4*(b.infectedShot?INFECTED_INFECTION.durationBonus():1)}if(passiveEffect('walkCharge')&&p.shopWalk>=300)b.damage*=1+.6*passiveCount('walkCharge')};if(state.shots.length>start&&passiveEffect('walkCharge')&&p.shopWalk>=300){p.shopWalk=0;soundSfx('shield')}};
 const baseActive=useEquippedActive;useEquippedActive=function(dx=0,dy=0){const p=state.player,item=p.equipment.active;let result;if(item?.shopSedative){if(state.mode!=='play'||state.paused||state.map||p.cool>0||state.rooms[state.room].entryDelay>0)return false;for(const e of state.rooms[state.room].enemies)if(e.hp>0&&distance(e,p)<=190+e.r){if(e.boss)e.shopSedated=2;else e.charmTime=4}p.cool=16;p.activeCooldown=16;state.activePulse={x:p.x,y:p.y,life:.4,radius:190};soundSfx('spore');result=true}else result=baseActive(dx,dy);if(result&&p.equipment.charm?.shopCooldown){p.cool*=p.equipment.charm.shopCooldown;p.activeCooldown=p.cool}if(result)updateActiveButton();return result};
 const baseFactor=enemyMovementFactor;enemyMovementFactor=function(e){return baseFactor(e)*(e.shopSedated>0?.75:1)};
 const baseHit=hitByPlayerShot;hitByPlayerShot=function(e,b){const before=e.hp;baseHit(e,b);const p=state.player;if(before>e.hp&&!b.fromAlly&&!b.shopShard&&!b.fragment&&passiveEffect('glassRosary')){p.shopGlass=(p.shopGlass||0)+1;if(p.shopGlass>=10){p.shopGlass=0;PROJECTILE_SYNERGIES.emitRosary(b);soundSfx('break')}}};
 const itemTick=tick;tick=function(dt){const p=state.player,run=state.mode==='play'&&!state.paused&&!state.map&&!(state.rooms[state.room].entryDelay>0),x=p.x,y=p.y,dash=p.dash; if(run){for(const e of state.rooms[state.room].enemies)e.shopSedated=Math.max(0,(e.shopSedated||0)-dt);for(const b of state.shots)if(b.shopReturnAge!==undefined){b.shopReturnAge+=dt;if(b.shopReturnAge>=.45){if(!b.shopReturning){b.shopReturning=true;b.hitTargets=[]}const a=Math.atan2(p.y-b.y,p.x-b.x),speed=Math.hypot(b.vx,b.vy);b.vx=Math.cos(a)*speed;b.vy=Math.sin(a)*speed;if(distance(b,p)<16)b.life=0}}if(p.equipment.charm?.id==='shopSutureWrap')for(const drop of state.rooms[state.room].drops)if(drop.kind!=='item'&&distance(drop,p)<175&&distance(drop,p)>10){const a=Math.atan2(p.y-drop.y,p.x-drop.x);drop.x+=Math.cos(a)*Math.min(140*dt,distance(drop,p));drop.y+=Math.sin(a)*Math.min(140*dt,distance(drop,p))}}itemTick(dt);if(run&&state.mode==='play'){if(passiveEffect('walkCharge')&&dash<=0&&p.dash<=0)p.shopWalk=Math.min(300,(p.shopWalk||0)+Math.min(20,Math.hypot(p.x-x,p.y-y)));else if(!passiveEffect('walkCharge'))p.shopWalk=0;if(!passiveEffect('glassRosary'))p.shopGlass=0}};
 const baseActiveLabel=updateActiveButton;updateActiveButton=function(){baseActiveLabel();if(state.player.equipment.active?.shopSedative){const b=$('#touch-dash');if(b)b.textContent=state.player.cool>0?`Sedante · ${state.player.cool.toFixed(1)} s`:'Sedante'}};
