   ctx.fillStyle=dark;ctx.beginPath();for(let i=0;i<15;i++){const a=i*Math.PI*2/15,size=r*(.58+rand()*.43),x=Math.cos(a)*size,y=Math.sin(a)*size*.55;if(i)ctx.lineTo(x,y);else ctx.moveTo(x,y)}ctx.closePath();ctx.fill();
