    if((i+(stain.type==='thorn'?1:0))%2){ctx.fillStyle='#8fa474';ctx.strokeStyle='#425e42';ctx.lineWidth=1;ctx.beginPath();ctx.moveTo(-6,0);ctx.quadraticCurveTo(0,-8,8,-1);ctx.quadraticCurveTo(3,5,-6,0);ctx.fill();ctx.stroke();artLine([[-5,0],[6,-1]],'#c0c793',1)}
