 try{const saved=JSON.parse(PROGRESS_STORE.getItem(key)||'null');if(['normal','hard'].includes(saved?.difficulty))selectedMode=saved.difficulty;for(const id of ['vera','ibarra'])if(Number.isSafeInteger(saved?.dialogues?.[id])&&saved.dialogues[id]>=0)doctorIndex[id]=saved.dialogues[id]%1000000}catch{}
