 function guidedEquipmentWarning(){pendingGuide=false;dialog('Tutorial guiado sin objetos','«Para practicar desde cero, este recorrido empieza sin objetos. Guardá en la caja compartida todo lo que tengas en la mochila y también el equipo puesto. Cuando no lleves nada encima, volvé a pulsar Tutorial guiado.»','Volver al búnker',closeDialog);return false}
 function declineGuided(){pendingGuide=false;state.guidedTutorial=false;state.guidance=null;const p=state.player;p.headX=-1;p.headY=0;notify(`${p.characterId==='infected'?'El humano infectado':'Este personaje'} mira el panel sin interés. El tutorial guiado es solo para Moho.`);return false}
