 const baseBossTest=startBossTest;startBossTest=function(...args){if(!sentencing)return baseBossTest(...args)};
 const baseReset=reset;reset=function(){if(sentencing)return;baseReset();if(recovered){baseline=recovered;recovered=null;sentencing=true;condemn()}else{baseline=null;rollbackDone=false}};
 const baseDraw=drawMoho;drawMoho=function(){baseDraw();if(!sentencing||rollbackDone)return;const p=state.player;ctx.save();withScenePaint('raw',()=>{originRect(p.x+15,p.y-28,11,18,'#263d3d','#bfd0a5',1.5);originRect(p.x+17,p.y-25,7,10,'#9aba93','#9aba93',0)});ctx.restore()};
 window.IBARRA_FARMING=Object.freeze({get active(){return sentencing&&!rollbackDone},get count(){return state.rooms[state.room]?.ibarraFlyKills||0},get lines(){return [...lines]}});
