 const guidedEnd=()=>tuned()&&!!state.guidedTutorial;
 const baseSpread=patientArmSpread;patientArmSpread=function(e){const spread=baseSpread(e);if(e.attackMode!=='spin')return spread;const swing=Math.sin((e.spinElapsed||0)*Math.PI/3);return spread*(1+.05*swing*swing-.15*swing)};
 const baseSpeed=patientSpinSpeed;patientSpinSpeed=function(e,progress){const base=baseSpeed(e,progress),elapsed=e.spinElapsed||0;return tuned()?base*(1-.2*clamp((elapsed-15)/.75,0,1)):base};
