   const size=roomSize();state.player.x=size.width/2;state.player.y=size.height/2;cameraKey='';
   if(TUTORIAL_PHONE.enqueue(lines,{key:'normal-mission',important:true,campaign:true})){PROGRESS_STORE.setItem(key,JSON.stringify({version:1,seen:true}));captureLevelCheckpoint()}
