 function roomLinks(index){return state.rooms[index]?.links||DOORS[index]||[]}
 function roomSymbol(room,index){if(index===state.room)return '●';if(room.type==='boss')return '☠';if(room.monoType)return '2×';if(room.shop)return '$';if(room.type==='cache')return '✦';if(room.type==='archive')return '≡';if(room.type==='entry')return 'E';return room.clear?'✓':'·'}
