// First contact after the bunker airlock opens onto the uncontrolled exterior.
(function installExteriorDepartureCall(){
 const key='moho.exterior-departure-call.v1';let queued=false;
 const lines=[
  {id:'vera',text:'¿Moho? Bien, la señal sigue estable. Ya estás afuera. Recordá esto: el tutorial era una sala de pruebas preparada por nosotros. Acá no controlamos el terreno, las criaturas ni lo que pueda encontrarte.'},
  {id:'ibarra',text:'Afuera estás cien por ciento por tu cuenta. Podemos vigilar tu señal y hablarte mientras haya conexión, pero no controlamos nada de ese lado ni vamos a poder ayudarte mucho.'},
  {id:'vera',text:'Tu cuerpo lleva un teletransportador de emergencia. Si morís, la baliza recuperará lo que quede de vos y lo traerá al búnker. Consideralo nuestro seguro de vida.'},
  {id:'ibarra',text:'No es inmortalidad. Es la diferencia entre perderte para siempre y tener que despegarte del piso con una espátula. Tratá de no comprobarlo por curiosidad.'},
  {id:'vera',text:'Es muy probable que encuentres a Scrapy, nuestro robot recolector. No hablamos con él desde hace años, pero todavía usa una rejilla conectada al exterior para dejarnos recursos, piezas y cosas con las que trabajar o experimentar. Cada vez lo hace con menos frecuencia.'},
  {id:'ibarra',text:'Scrapy fue quien te trajo hasta nosotros. Si lo ves, decile gracias, papá… Aunque nosotros llamábamos hijos a nuestros inventos.'},
  {id:'vera',text:'Entonces, si Scrapy es nuestro hijo y él te encontró, ¿vos serías nuestro nieto? Creo que esta explicación se nos está yendo de las manos.'},
  {id:'ibarra',text:'Agradecele por encontrarte y después decile que mejore su trabajo. La última entrega parecía una montaña de pañales mojados.',objective:'Buscá a Scrapy entre la basura'}
 ];
 function seen(){try{return JSON.parse(PROGRESS_STORE.getItem(key)||'null')?.seen===true}catch{return false}}
 function schedule(){
  if(queued||seen()||!window.EXTERIOR_ZONE_ONE?.active||state.mode!=='play')return false;
  if(!TUTORIAL_PHONE.enqueue(lines,{key:'exterior-departure',important:true,campaign:true}))return false;
  queued=true;PROGRESS_STORE.setItem(key,JSON.stringify({version:1,seen:true}));captureLevelCheckpoint();return true
 }
 const baseTick=tick;tick=function(dt){const result=baseTick(dt);schedule();return result};
 const baseReturn=returnBunker;returnBunker=function(){queued=false;return baseReturn()};
 const baseReset=reset;reset=function(){queued=false;return baseReset()};
 window.EXTERIOR_DEPARTURE_CALL=Object.freeze({schedule,get seen(){return seen()},get lines(){return lines.map(line=>({...line}))}});
})();

