 people.forEach(person=>Object.assign(person,residentProfiles[person.name]));

 const night=()=>!isMobileGame()&&!!window.DAY_CYCLE?.night;
 const nocturnal=new Set(['Grieta','Portón','Guiño','Óxido','Migas']);
 const awakePeople=()=>night()?people.filter(p=>nocturnal.has(p.name)):people;
