 let speechSerial=0,villageSpeech=null,relocateTimer=24,scrapyWave=0,scrapyNear=false;
 function residentSpotSafe(person,x,y,placed){const r=residentRadius(person)+12;if(x<r+26||x>W-r-26||y<105||y>H-105)return false;if(Math.abs(x-ENTRY_X)<50)return false;if(buildings.some(o=>x>o.x-r-12&&x<o.x+o.w+r+12&&y>o.y-r-50&&y<o.y+o.h+r+22))return false;if(buildings.some(o=>o.entrance&&Math.hypot(x-o.entrance.x,y-o.entrance.y)<135))return false;if(Math.hypot(x-720,y-1280)<125||Math.hypot(x-650,y-650)<125)return false;if(Math.hypot(x-state.player.x,y-state.player.y)<r+70)return false;return !placed.some(other=>Math.hypot(x-other.x,y-other.y)<residentRadius(person)+residentRadius(other)+14)}
 function residentOutsideView(x,y){
  if(!closeView)return false;
  const view=customSceneProjection(W,H,cameraX,cameraY,640),margin=150;
  return x<view.x-margin||x>view.x+view.w+margin||y<view.y-margin||y>view.y+view.h+margin
 }
 function repositionResidents(onlyOffscreen=false){
  const placed=onlyOffscreen?[...people]:[];
  for(const person of people){
   if(onlyOffscreen&&(Math.hypot(person.x-state.player.x,person.y-state.player.y)<730||!residentOutsideView(person.x,person.y)||villageSpeech?.person===person))continue;
   const others=placed.filter(other=>other!==person),candidates=[];
   for(let y=120;y<H-100;y+=25)for(let x=80;x<W-70;x+=25){
    if(onlyOffscreen&&(Math.hypot(x-state.player.x,y-state.player.y)<730||!residentOutsideView(x,y)))continue;
    if(residentSpotSafe(person,x,y,others))candidates.push({x,y})
   }
   if(candidates.length){const far=candidates.filter(p=>Math.hypot(p.x-person.x,p.y-person.y)>100),pool=far.length?far:candidates;Object.assign(person,pool[Math.floor(Math.random()*pool.length)])}
   if(!placed.includes(person))placed.push(person)
  }
 }

 function talkResident(person){const lines=person.lines,at=person.talkIndex++,nightCopy={Grieta:'Me gusta el silencio de noche. Los demás ya están durmiendo adentro.',Portón:'De noche hago la guardia. Paseá tranquilo; el peligro empieza después de la salida norte.',Guiño:'Yo veo mejor a estas horas. Volvé a casa cuando te dé sueño.',Óxido:'Todos duermen y mis relojes siguen discutiendo la hora.',Migas:'La mejor basura aparece cuando nadie está mirando.'},text=polishedDialogue(night()&&at%2===0?nightCopy[person.name]||'Los demás ya se fueron a dormir. Yo me quedo un rato más.':lines[at%lines.length]);villageSpeech={person,text,time:14,id:++speechSerial};if(isLegacyMobileContent())notify(`${person.name}: «${text}»`);else state.toastTime=0;$('#radio-text').textContent=`${person.name}: «${text}»`;soundSfx('door')}
 function drawResidentSpeech(){if(!isLegacyMobileContent()||!villageSpeech)return;const {person,text}=villageSpeech,words=text.split(' '),lines=[];let line='';for(const word of words){if((line+' '+word).length>42){lines.push(line);line=word}else line+=(line?' ':'')+word}if(line)lines.push(line);const width=330,height=40+lines.length*17,x=clamp(person.x-width/2,25,W-width-25),y=Math.max(20,person.y-100-height);ctx.save();ctx.fillStyle='#101713f5';ctx.strokeStyle='#b39767';ctx.lineWidth=3;ctx.beginPath();ctx.roundRect(x,y,width,height,12);ctx.fill();ctx.stroke();ctx.fillStyle='#dfcf99';ctx.font='bold 12px monospace';ctx.textAlign='left';ctx.fillText(person.name.toUpperCase(),x+14,y+22);ctx.fillStyle='#eee5cd';ctx.font='12px monospace';lines.forEach((line,index)=>ctx.fillText(line,x+14,y+43+index*17));ctx.restore()}
