  artLine([[-12,13],[o.w+12,13]],trim,5);for(let i=1;i<5;i++){const x=o.w*i/5,y=x<ridge*o.w?13-(x+12)/(ridge*o.w+12)*36:13-(o.w+12-x)/(o.w+12-ridge*o.w)*36;artLine([[x,y+3],[x+9,10]],'#9aa08555',1.5)}
  for(const x of[9,o.w-9]){artLine([[x,17],[x,o.h-12]],trim,5);ellipse(ctx,x,22,1.8,1.8,'#302f26');ellipse(ctx,x,o.h-17,1.8,1.8,'#302f26')}
  const doorX=door-doorW/2,doorY=o.h-doorH;ctx.fillStyle=o.visitHome?'#a6a16b':'#222c24';ctx.fillRect(doorX,doorY,doorW,doorH);ctx.strokeStyle=trim;ctx.lineWidth=4;ctx.strokeRect(doorX,doorY,doorW,doorH);artLine([[doorX+8,doorY+4],[doorX+8,o.h-4]],'#3b493555',1.5);for(const y of[doorY+12,o.h-12])artLine([[doorX-1,y],[doorX+7,y]],'#777d65',3);ellipse(ctx,doorX+doorW-9,o.h-25,3,3,'#d0bb7d',ink);
  if(o.w>=120&&o.h>=100){const ww=Math.min(45,o.w*.23),wx=door<o.w/2?o.w-ww-18:18,wy=Math.max(29,o.h*.32);ctx.fillStyle='#1f3028';ctx.fillRect(wx,wy,ww,29);ctx.strokeStyle=trim;ctx.lineWidth=3;ctx.strokeRect(wx,wy,ww,29);artLine([[wx+ww*.55,wy],[wx+ww*.55,wy+29]],'#6f826c',2);artLine([[wx,wy+31],[wx+ww+3,wy+31]],'#a09d7a',3);artLine([[wx+4,wy+4],[wx+ww*.4,wy+4]],'#bdc8a044',2)}
  // One repair is bolted to a panel, away from the door and window.
  if(o.w>180){const px=door>o.w/2?o.w*.43:o.w*.64,py=Math.min(o.h-34,40);ctx.fillStyle='#788474';ctx.strokeStyle='#414b3e';ctx.lineWidth=2;ctx.fillRect(px,py,25,16);ctx.strokeRect(px,py,25,16);for(const dx of[3,22])ellipse(ctx,px+dx,py+3,1.3,1.3,'#c4b893')}
