 function instructorRobot(){const {x,y}=scrapy;if(window.SCRAPY_ACTOR?.draw){SCRAPY_ACTOR.draw(x,y,{label:true,wave:scrapyWave>0});return}const bob=Math.sin(state.elapsed*2.4)*2;ctx.save();ctx.translate(x,y+bob);ellipse(ctx,0,31,24,7,'#05060677');artLine([[-8,8],[-11,29],[-18,33]],'#6d5240',6);artLine([[8,8],[12,29],[19,33]],'#6d5240',6);polyLocal([[-22,-26],[21,-26],[18,12],[0,20],[-20,11]],'#5a6861','#272d29',3);polyLocal([[-18,-18],[-4,-24],[8,-15],[-2,-5]],'#9a704d','#3a2c22',2);originRect(-27,-57,54,33,'#826348','#29231f',4);ctx.fillStyle='#16211e';ctx.fillRect(-20,-50,40,18);for(const ex of[-10,10])ellipse(ctx,ex,-41,5.5,5.5,'#d5c774','#2c3028');ctx.strokeStyle='#c69265';ctx.lineWidth=3;ctx.beginPath();ctx.moveTo(-12,-18);ctx.lineTo(12,4);ctx.moveTo(12,-18);ctx.lineTo(-12,4);ctx.stroke();artLine([[20,-17],[34,-28],[38,-43]],'#6d5240',5);ellipse(ctx,38,-44,5,5,'#a77b52','#30251e');ctx.restore()}
 function streetScrap(){for(let i=0;i<28;i++){const x=ROAD_L+22+(i*71)%(ROAD_R-ROAD_L-44),y=70+(i*137)%(H-130),kind=i%4;ctx.save();ctx.translate(x,y);ctx.rotate((i%7-3)*.12);if(kind===0){ctx.fillStyle='#6a7068';ctx.fillRect(-8,-5,16,10);ctx.fillStyle='#9a663c';ctx.fillRect(-5,-3,5,6)}else if(kind===1){ctx.strokeStyle='#948d77';ctx.lineWidth=3;ctx.beginPath();ctx.moveTo(-9,6);ctx.lineTo(7,-7);ctx.lineTo(11,5);ctx.stroke()}else if(kind===2){ctx.fillStyle='#4a594f';ctx.beginPath();ctx.arc(0,0,7,0,Math.PI*2);ctx.fill()}else{ctx.fillStyle='#836d43';ctx.beginPath();ctx.ellipse(0,0,9,5,0,0,Math.PI*2);ctx.fill()}ctx.restore()}}
 function groundBag(x,y,w,h,color,lean=0){ctx.save();ctx.translate(x,y);ctx.rotate(lean);ctx.fillStyle='#020303aa';ctx.beginPath();ctx.ellipse(0,h*.38,w*.49,h*.18,0,0,Math.PI*2);ctx.fill();ctx.fillStyle=color;ctx.strokeStyle='#050706';ctx.lineWidth=3;ctx.beginPath();ctx.moveTo(-w*.08,-h*.47);ctx.bezierCurveTo(-w*.35,-h*.5,-w*.53,-h*.22,-w*.49,h*.13);ctx.bezierCurveTo(-w*.45,h*.45,-w*.18,h*.53,0,h*.47);ctx.bezierCurveTo(w*.25,h*.55,w*.5,h*.4,w*.49,h*.08);ctx.bezierCurveTo(w*.48,-h*.24,w*.28,-h*.48,w*.08,-h*.47);ctx.closePath();ctx.fill();ctx.stroke();polyLocal([[-w*.12,-h*.43],[0,-h*.6],[w*.13,-h*.43],[w*.05,-h*.34],[-w*.05,-h*.34]],color,'#050706',2);ctx.strokeStyle='#48504988';ctx.lineWidth=1.5;ctx.beginPath();ctx.moveTo(-w*.3,-h*.12);ctx.quadraticCurveTo(-w*.08,-h*.26,w*.08,-h*.15);ctx.moveTo(w*.3,.02);ctx.quadraticCurveTo(w*.12,h*.19,w*.2,h*.34);ctx.stroke();ctx.restore()}
 function villageFilth(x,y,kind,rot=0,scale=1){ctx.save();ctx.translate(x,y);ctx.rotate(rot);ctx.scale(scale,scale);if(kind==='food'){ctx.fillStyle='#57482c';ctx.beginPath();ctx.arc(-8,2,12,0,Math.PI*2);ctx.arc(5,0,15,0,Math.PI*2);ctx.fill();ellipse(ctx,2,-2,6,5,'#798044');ellipse(ctx,12,7,5,3,'#30351e');artLine([[-15,-6],[-23,-15]],'#7c6841',3)}else if(kind==='blood'){ctx.fillStyle='#68161bbb';ctx.beginPath();ctx.ellipse(0,0,29,15,0,0,Math.PI*2);ctx.ellipse(23,8,10,6,0,0,Math.PI*2);ctx.ellipse(-22,-8,8,5,0,0,Math.PI*2);ctx.fill()}else if(kind==='feces'){ellipse(ctx,-8,7,14,8,'#50371f');ellipse(ctx,4,1,13,8,'#604229');ellipse(ctx,-1,-7,9,7,'#6a492b','#271b12')}else if(kind==='bone'){artLine([[-22,2],[21,-2]],'#aaa798',8);ellipse(ctx,-23,2,7,7,'#aaa798');ellipse(ctx,22,-2,7,7,'#aaa798')}else if(kind==='limb'){ctx.fillStyle='#8f786a';ctx.strokeStyle='#3d3030';ctx.lineWidth=3;ctx.beginPath();ctx.roundRect(-25,-8,42,16,8);ctx.fill();ctx.stroke();for(const fy of[-8,-4,0,4,8])artLine([[15,fy*.45],[28,fy]],'#8f786a',5);ctx.fillStyle='#67171b';ctx.beginPath();ctx.ellipse(-24,0,7,9,0,0,Math.PI*2);ctx.fill()}else{originRect(-19,-11,33,22,'#59615e','#202522',3);ctx.fillStyle='#8b6740';ctx.fillRect(-12,-7,6,13);artLine([[12,-8],[26,-18],[30,-4]],'#747e77',5)}ctx.restore()}
 function drawGround(){
  ctx.fillStyle='#070908';ctx.fillRect(0,0,W,H);for(let row=-1;row<39;row++)for(let col=0;col<20;col++){const x=col*59+(row%2)*29,y=row*48+((col*17+row*11)%11),tone=(row+col)%5,w=61+((row*13+col*7)%14),h=46+((row*5+col*11)%13);groundBag(x,y,w,h,['#101310','#151915','#1b1e1a','#20231e','#0d100e'][tone],((col+row)%7-3)*.025)}
  ctx.fillStyle='#26261f88';ctx.fillRect(ROAD_L,0,ROAD_R-ROAD_L,H);ctx.strokeStyle='#55524788';ctx.lineWidth=4;for(const x of[ROAD_L,ROAD_R]){ctx.beginPath();ctx.moveTo(x,0);ctx.lineTo(x,H);ctx.stroke()}for(let i=0;i<56;i++){const x=48+(i*193)%1005,y=45+(i*317)%(H-100),kind=['food','feces','blood','bone','limb','scrap'][i%6];villageFilth(x,y,kind,(i%7-3)*.12,.55+(i%4)*.09)}
  streetScrap();ctx.fillStyle='#111815dd';ctx.fillRect(ENTRY_X-92,H-54,184,54);ctx.fillStyle='#b8b38b';ctx.font='bold 9px monospace';ctx.textAlign='center';ctx.fillText('VERTEDERO ↓',ENTRY_X,H-68);ctx.fillStyle='#b29452';ctx.strokeStyle='#2f291d';ctx.lineWidth=6;ctx.fillRect(ENTRY_X-205,7,410,58);ctx.strokeRect(ENTRY_X-205,7,410,58);ctx.fillStyle='#211f18';ctx.font='bold 20px monospace';ctx.fillText('SALIDA AL EXTERIOR ↑',ENTRY_X,35);ctx.font='bold 9px monospace';ctx.fillText('ZONA 1 · NIVEL 1 · VERTEDERO',ENTRY_X,53)
 }
 function villageActors(){return [...buildings.map((o,index)=>({id:o.id,y:o.y+o.h,draw:()=>house(o,index)})),{id:'fruit-stall',y:fruitStall.y+fruitStall.h,draw:()=>stall(720,1280)},{id:'scrapy',y:scrapy.collisionY,draw:instructorRobot},...awakePeople().map((person,index)=>({id:person.name,y:person.y+30*(person.type==='tall'?1.16:person.type==='small'?.76:1),draw:()=>resident(person,people.indexOf(person))})),{id:'player',y:state.player.y,draw:drawMoho}].sort((a,b)=>a.y-b.y)}
 function drawVillage(){drawGround();TRASH_BAG_SKILL?.drawZoneBags(false);villageActors().forEach(actor=>actor.draw());TRASH_BAG_SKILL?.drawZoneBags(true);if(night())EXTERIOR_NIGHT.draw(W,H,{lamps:[{x:480,y:280},{x:630,y:640},{x:475,y:1000},{x:630,y:1400},{x:480,y:1700}],windows:buildings.filter(b=>b.kind==='home').map((b,i)=>({x:b.x+22,y:b.y+35,w:23,h:18})),sleepers:buildings.filter(b=>b.kind==='home').filter((b,i)=>i%3===0).map(b=>({x:b.x+b.w*.65,y:b.y+5}))});drawResidentSpeech()}

 function minimap(){const w=95,h=Math.min(280,canvas.height*.32),x=canvas.width-w-18,y=18;ctx.save();ctx.setTransform(1,0,0,1,0,0);ctx.globalAlpha=.84;ctx.fillStyle='#111512dd';ctx.strokeStyle='#c3986f';ctx.beginPath();ctx.roundRect(x,y,w,h,10);ctx.fill();ctx.stroke();ctx.fillStyle='#d8c8a8';ctx.font='bold 7px monospace';ctx.textAlign='center';ctx.fillText('POBLADO',x+w/2,y+15);ctx.strokeStyle='#80664d';ctx.lineWidth=4;ctx.beginPath();ctx.moveTo(x+w/2,y+28);ctx.lineTo(x+w/2,y+h-18);ctx.stroke();ctx.fillStyle='#d7e7ad';ctx.beginPath();ctx.arc(x+w/2,y+28+clamp(state.player.y/H,0,1)*(h-46),7,0,Math.PI*2);ctx.fill();ctx.restore()}
 function drawVillageRoom(){if(state.map){drawVillageMap(ctx,canvas.width,canvas.height);updateBattleInterface();return}const viewH=640,viewW=viewH*canvas.width/canvas.height,targetX=clamp(state.player.x,viewW/2,W-viewW/2),targetY=clamp(state.player.y,viewH/2,H-viewH/2);cameraX+=(targetX-cameraX)*.16;cameraY+=(targetY-cameraY)*.16;drawCustomScene(drawVillage,W,H,cameraX,cameraY,viewH,'#080b0a');if(closeView)minimap();updateBattleInterface()}
