 let active=false,panel=null,step=0,cameraY=640,data={version:2,greeted:false,shopStock:defaultStock(),shopSold:[]};
 try{const saved=JSON.parse(PROGRESS_STORE.getItem(key)||'null');if(saved?.version===2)data={version:2,greeted:!!saved.greeted,shopStock:Array.isArray(saved.shopStock)?saved.shopStock:defaultStock(),shopSold:Array.isArray(saved.shopSold)?saved.shopSold:[]};else if(saved?.version===1)data.greeted=!!saved.greeted}catch{}
