 const baseDraw=draw;draw=function(){if(active&&CHARACTER_CONVERSATIONS?.speaker!=='remendador'){sizeGameSurface();if(state.map)drawRoomMap(ctx,canvas.width,canvas.height);else drawRoomFitted();updateBattleInterface();return}baseDraw()};
