// Golden compartments convert existing bag positions; their contents keep normal item history.
(function installMerchantGoldenSlots(){
 function moveTo(uid,slot=0){
  const p=state.player,count=PABELLON_SHOP.goldenSlotsFor(),index=p.bag.findIndex(item=>item.uid===uid);
  if(index<0||!Number.isInteger(slot)||slot<0||slot>=count||slot>=p.bag.length||index===slot)return false;
  [p.bag[slot],p.bag[index]]=[p.bag[index],p.bag[slot]];refresh();CHARACTER_ROSTER.save();soundSfx('activeReady');return true
 }
 function decorate(){
  const inventory=$('#inventory'),count=PABELLON_SHOP.goldenSlotsFor();if(!inventory||!count)return;
  const p=state.player,cards=[...inventory.children].filter(el=>el.classList.contains('bag-item')||el.classList.contains('empty-slot'));
  cards.forEach((card,index)=>{
   if(index<count){card.classList.add('golden-bag-slot');card.dataset.goldenSlot=String(index);const label=document.createElement('small');label.className='golden-slot-label';label.textContent=`▣ ESPACIO DORADO ${index+1}`;card.prepend(label);if(!p.bag[index]){const detail=document.createElement('small');detail.textContent='El objeto que guardes aquí sumará salas sin equiparlo.';card.append(detail)}}
   if(!p.bag[index])return;
   const targets=Array.from({length:Math.min(count,p.bag.length)},(_,n)=>n).filter(n=>n!==index);if(!targets.length)return;
   const actions=document.createElement('div');actions.className='golden-slot-actions';actions.style.gridTemplateColumns=`repeat(${targets.length},minmax(0,1fr))`;
   for(const slot of targets){const button=document.createElement('button');button.type='button';button.className='quiet';button.dataset.moveGolden=String(slot);button.textContent=`Mover a dorado ${slot+1}`;button.title=`Guardar ${p.bag[index].name} en el espacio dorado ${slot+1}`;button.onclick=()=>moveTo(p.bag[index].uid,slot);actions.append(button)}card.append(actions)
  });
  const help=$('#inventory-help');if(help)help.textContent+=` Tenés ${count} ${count===1?'espacio dorado':'espacios dorados'}: sus objetos suman salas de combate aunque no estén equipados.`
 }
 const baseRefresh=refresh;refresh=function(){const result=baseRefresh();decorate();return result};
 window.MERCHANT_GOLDEN_SLOTS=Object.freeze({moveTo,get count(){return PABELLON_SHOP.goldenSlotsFor()}});
})();

// First backpack arrangement prototype: touch-friendly selection and desktop drag/drop.
(function installInventoryReorder(){
 let selected=null;
 const cards=()=>[...$('#inventory').children].filter(el=>el.matches('.bag-item,.empty-slot'));
 function move(uid,index){
  const p=state.player,from=p.bag.findIndex(item=>item.uid===uid);
  if(!['play','bunker'].includes(state.mode)||from<0||!Number.isInteger(index)||index<0||index>=p.capacity)return false;
  const to=Math.min(index,p.bag.length-1);if(from!==to)[p.bag[from],p.bag[to]]=[p.bag[to],p.bag[from]];
  selected=null;refresh();CHARACTER_ROSTER.save();return true
 }
 function decorate(){
  const p=state.player;if(selected!==null&&!p.bag.some(item=>item.uid===selected))selected=null;
  cards().forEach((card,index)=>{
   const item=p.bag[index];card.dataset.bagPosition=String(index);card.classList.toggle('bag-move-source',!!item&&item.uid===selected);card.classList.toggle('bag-move-target',selected!==null&&item?.uid!==selected);
   const button=document.createElement('button');button.type='button';button.className='quiet bag-move-button';
   button.textContent=selected===null?'Mover':item?.uid===selected?'Cancelar movimiento':item?'Intercambiar aquí':'Mover al final';
   button.setAttribute('aria-label',selected===null?`Mover ${item?.name||'objeto'}`:button.textContent);
   button.onclick=event=>{event.stopPropagation();if(selected===null){selected=item.uid;refresh()}else if(item?.uid===selected){selected=null;refresh()}else move(selected,index)};
   if(item||selected!==null)card.append(button);
   if(item){card.draggable=true;card.ondragstart=event=>{selected=item.uid;event.dataTransfer.effectAllowed='move';event.dataTransfer.setData('text/plain',String(item.uid));card.classList.add('bag-move-source')};card.ondragend=()=>{selected=null;refresh()}}
   card.ondragover=event=>{if(selected!==null){event.preventDefault();event.dataTransfer.dropEffect='move'}};
   card.ondrop=event=>{if(selected===null)return;event.preventDefault();event.stopPropagation();move(selected,index)}
  });
  $('#inventory-help').textContent+=' Para ordenar: tocá Mover y elegí otro objeto para intercambiarlos. También podés arrastrarlos con el mouse.'
 }
 const baseRefresh=refresh;refresh=function(){const result=baseRefresh();decorate();return result};
 const baseOpen=openInventory;openInventory=function(){selected=null;return baseOpen()};
 window.INVENTORY_REORDER=Object.freeze({move,get selected(){return selected}});
})();

