  const travel=time*28,first=Math.floor((r.x-30-travel)/92),last=Math.ceil((r.x+r.w+30-travel)/92);
  for(let index=first;index<=last;index++){const x=index*92+travel,y=r.y+r.h*.52+Math.sin(time*1.4+index)*r.h*.17;ctx.save();ctx.translate(x,y);ctx.rotate(Math.sin(time+index)*.12);ellipse(ctx,0,0,18,10,'#0b100c');artLine([[-13,1],[0,-5],[14,0]],'#6a765966',1.6);ellipse(ctx,7,-3,4,2.5,'#819053');ctx.restore()}
  const drift=time*17,start=Math.floor((r.x-14-drift)/140),end=Math.ceil((r.x+r.w+14-drift)/140);
