 const building=()=>window.TRASH_VILLAGE?.buildings.find(o=>o.id==='training');
 const outsideDoor=()=>{const e=building()?.entrance,p=state.player;return !!(!active&&TRASH_VILLAGE?.active&&e&&Math.hypot(p.x-e.x,p.y-e.y)<84)};
 const nearExit=()=>active&&state.player.y>1320&&Math.abs(state.player.x-480)<95;
