 function pushRect(p,o,oldX,oldY){if((window.VOSS_GAMEPLAY?.airborne||window.CHARACTER_OUTFITS?.ghost))return;const l=o.x-p.r,r=o.x+o.w+p.r,t=o.y-p.r,b=o.y+o.h+p.r;if(p.x<l||p.x>r||p.y<t||p.y>b)return;if(oldX<=l)p.x=l;else if(oldX>=r)p.x=r;else if(oldY<=t)p.y=t;else p.y=b}
