 function move(dt){const p=state.player,st=stats(),ix=Number(keys.has('d'))-Number(keys.has('a'))+TOUCH.move.x,iy=Number(keys.has('s'))-Number(keys.has('w'))+TOUCH.move.y,l=Math.hypot(ix,iy)||1,dx=p.dash>0?(p.activeDashX??ix/l):ix/l,dy=p.dash>0?(p.activeDashY??iy/l):iy/l,moving=p.dash>0||ix||iy,heavy=p.dash>0?(TRASH_BAG_SKILL?.dashMovementFactor||1):(TRASH_BAG_SKILL?.movementFactor||1),travel=st.speed*(p.dash>0?3.2:1)*heavy*dt,steps=Math.max(1,Math.ceil(travel/8));if(ix||iy)p.lastMoveAngle=Math.atan2(iy,ix);for(let i=0;i<steps;i++){const oldX=p.x,oldY=p.y;if(moving){p.x+=dx*travel/steps;p.y+=dy*travel/steps}p.x=clamp(p.x,left+p.r,right-p.r);p.y=clamp(p.y,88,H-38);if(TRASH_BAG_SKILL?.tryDashPickup(oldX,oldY,p.x,p.y))break;const blocks=[...pitBlocks(pit1,[bridge1],data.stage>=1),...pitBlocks(pit2,bridges2,data.stage>=3)];if(data.stage<2)blocks.push(gate1);if(data.stage<4)blocks.push(gate2);for(const block of blocks)pushRect(p,block,oldX,oldY);pushDummy(p)}}
