 function updateDebris(dt){for(const d of debris){d.x+=d.vx*dt;d.y+=d.vy*dt;d.vx*=Math.pow(.07,dt);d.vy*=Math.pow(.07,dt);d.rotation+=d.spin*dt;d.life-=dt}debris=debris.filter(d=>d.life>0);}
