 const baseActive=useEquippedActive;useEquippedActive=function(dx=0,dy=0){const result=baseActive(dx,dy);if(result)collectBag();return result};
 const baseShoot=shootPlayer;shootPlayer=function(angle){if(data.unlocked&&zone()&&held&&Number.isFinite(angle)){throwHeld(angle);return}return baseShoot(angle)};
