 const baseRefresh=refresh;refresh=function(){const result=baseRefresh(),z=zone();if(!z&&held&&lastZone){held.held=false;held.spent=true;held=null;pickupDashLocked=false;lastZone=null}if(z){const use=isMobileGame()?'Usar / recoger':'E';if(nearScrapy())$('#hint').textContent=`${use} · Hablar con Scrapy`;else if(held)$('#hint').textContent='Apuntá y dispará · Lanzar bolsa';else if(nearestBag())$('#hint').textContent='ACTIVABLE DE DASH · Recoger bolsa'}return result};
