 window.TRASH_BAG_SKILL=Object.freeze({talk,startLesson,requestExit,unlock,resetCombatBags,resetBossBags,resetTitanBags,updateCustom(dt){return update(dt,true)},updateDebris,clearDebris,drawScrapy,drawZoneBags,drawHazardBag,tryDashPickup,consumeBag,consumeEnemyBag,normalizeMimicBags,explodeTrashAt,contactNumber:'07-727-279',get movementFactor(){return held?.held?.65:1},get dashMovementFactor(){return held?.held?(isMobileGame()?.28:.60):1},get unlocked(){return data.unlocked},get phoneRegistered(){return data.phone},get held(){return held?.id||null},get usableBags(){return currentBags().filter(b=>!b.spent).length},get bags(){return structuredClone(bags)},get debris(){return structuredClone(debris)},get nearScrapy(){return nearScrapy()}});
