// Low pressure plates and raised scrap hoppers have different silhouettes and symbols.
(function(){
 if(isMobileGame())return;
 const colors={red:'#d27663',yellow:'#d6bd63',green:'#96bc81',blue:'#83b7d0',left:'#d1b77c',right:'#9dbdae'},shapes={red:'▲',yellow:'◆',green:'≡',blue:'✚'};
 function path(x,y,w,h,r,fill,stroke,width=2){ctx.fillStyle=fill;ctx.strokeStyle=stroke;ctx.lineWidth=width;ctx.beginPath();ctx.roundRect(x,y,w,h,r);ctx.fill();ctx.stroke()}
 function symbol(color,x,y,size=14){ctx.fillStyle='#17241e';ctx.textAlign='center';ctx.font=`bold ${size}px monospace`;ctx.fillText(shapes[color]||'◆',x,y+size*.34)}
 function check(x,y){artLine([[x-7,y],[x-2,y+5],[x+8,y-7]],'#e0edbb',3)}
 function plate(x,y,{color='yellow',pressed=false,label='PISAR',active=false,musical=false,flash=false}={}){
  const tint=colors[color]||colors.yellow,pulse=.5+.5*Math.sin(state.elapsed*4),down=pressed?5:0;ctx.save();ctx.translate(x,y);ellipse(ctx,0,20,45,15,'#050a0788');
  if(active&&!pressed){ctx.strokeStyle='#eee3ac88';ctx.lineWidth=2;ctx.beginPath();ctx.ellipse(0,7,43+pulse*2,29+pulse,0,0,Math.PI*2);ctx.stroke()}
  path(-37,-24,74,54,9,'#202a25','#101a16',3);path(-33,-24+down,66,44,7,pressed?'#52704d':'#697366','#cad0aa',2);
  path(-26,-20+down,52,32,5,pressed||flash?'#c5dda3':tint,'#263d2c',2);artLine([[-23,-16+down],[22,-16+down]],'#f0ecc066',2);
  for(const side of[-1,1])for(const yy of[-16,19])ellipse(ctx,side*32,yy,2,2,'#b9b8a0');
  if(pressed)check(0,-4+down);else if(musical){ctx.fillStyle='#1d3527';ctx.font='bold 18px Georgia';ctx.textAlign='center';ctx.fillText(label,0,4+down)}else symbol(color,0,-3+down,17);
  ctx.fillStyle=pressed?'#e0edbb':'#ced6b8';ctx.font='bold 8px monospace';ctx.textAlign='center';ctx.fillText(pressed?'ACTIVO':musical?'RITMO':label,0,42);ctx.restore();
 }
 function receiver(x,y,{color='yellow',lit=false,label='BASURA'}={}){
  const tint=colors[color]||colors.yellow,pulse=.5+.5*Math.sin(state.elapsed*3.5);ctx.save();ctx.translate(x,y);ellipse(ctx,0,31,43,14,'#050907aa');
  path(-28,0,56,29,5,'#3c463b','#111c17',3);for(const side of[-1,1])artLine([[side*25,18],[side*34,28],[side*14,28]],'#7d8875',4);
  // An open chute rather than a second floor switch; its mouth matches the hit centre.
  path(-34,-31,68,53,9,'#677366','#15221b',3);path(-28,-26,56,40,8,'#17271e',lit?'#b9da9e':tint,4);
  ellipse(ctx,0,-5,20,14,'#090f0b','#3e5342');ctx.strokeStyle=lit?'#c8e6a5':tint;ctx.lineWidth=3;ctx.beginPath();ctx.ellipse(0,-5,23,17,0,0,Math.PI*2);ctx.stroke();
  for(const side of[-1,1])for(const yy of[-20,12])ellipse(ctx,side*29,yy,1.7,1.7,'#d5cfaf');
  if(lit)check(0,-4);else{ctx.save();ctx.translate(0,-5);ctx.rotate(-.12);path(-8,-6,16,12,5,'#617458','#a9bc8a',1.4);artLine([[-6,-6],[0,-10],[6,-6]],'#a9bc8a',1.4);ctx.restore();ctx.globalAlpha=.5+pulse*.4;artLine([[0,-51],[0,-37],[-5,-42],[0,-37],[5,-42]],tint,2.5);ctx.globalAlpha=1}
  path(-16,18,32,13,3,lit?'#7d9e64':tint,'#17251b',1.5);symbol(color,0,24,11);
  ctx.fillStyle=lit?'#e0edbb':'#e0d7b5';ctx.font='bold 8px monospace';ctx.textAlign='center';ctx.fillText(lit?'LISTO':label,0,45);ctx.restore();
 }
 window.DUMP_PUZZLE_ART=Object.freeze({plate,receiver,shapes,colors});
})();

