 function makeCollectorEnemy(kind,x,y,index=0){let enemy;if(kind==='goblin')enemy=makeGenericEnemy('trashGoblin',x,y,index);else if(kind==='hungry')enemy=makeGenericEnemy('hungry',x,y,index);else if(kind==='mimic')enemy=makeBagMimic(x,y,`collector-${Date.now()}-${Math.random()}`,index%3,false);else if(kind==='signal')enemy=makeGenericEnemy('stopKid',x,y,index);else{enemy=makeEnemy('brute',x,y,0);Object.assign(enemy,{type:'dumpBigKid',zoneOneSpecific:true,bigKid:true,sketchFace:true,lidHat:true,x,y,homeX:x,homeY:y,r:43*S,hp:64,max:64,t:99,bigShotTimer:.6,bigSweepCooldown:.65,bigCombo:0,bigComboIndex:0,bigSwing:0,bigSwingDuration:.46,bigStrike:false,bigHits:0,bigShield:0,bigShieldWindup:0,bigDamage:0,bigPose:'walk'})}enemy.collectorSummon=true;return enemy}
