 const monsterBase=renderMonster;renderMonster=function(enemy,time){if(visible()&&enemy.trashGoblin)return withScenePaint('raw',()=>{drawTrashGoblin(enemy);drawZoneEnemyStatus(enemy)});if(visible()&&enemy.hungry)return withScenePaint('raw',()=>{drawHungry(enemy);if(enemy.r>0)drawZoneEnemyStatus(enemy)});if(visible()&&enemy.bagMimic)return withScenePaint('raw',()=>{drawBagMimic(enemy);drawZoneEnemyStatus(enemy)});if(visible()&&enemy.bigKid)return withScenePaint('raw',()=>{drawBigKid(enemy);drawZoneEnemyStatus(enemy)});if(visible()&&enemy.lidShooter)return withScenePaint('raw',()=>{drawLidKid(enemy);drawZoneEnemyStatus(enemy)});if(visible()&&enemy.stopKid)return withScenePaint('raw',()=>{drawSmallStopKid(enemy);drawZoneEnemyStatus(enemy)});return monsterBase(enemy,time)};
