 const obstacleBase=drawThemedObstacle;drawThemedObstacle=function(o,level){if(!o.zoneOneProp){obstacleBase(o,level);return}return withScenePaint('raw',()=>{const w=o.w/S,h=o.h/S,room=state.rooms[state.room],mechanismBlocker=o.puzzleBlocker||o.trapBlocker,mechanismSolved=o.puzzleBlocker?room?.trashPuzzle?.solved:room?.trapData?.kind==='scales'?false:room?.trapData?.solved;ctx.save();ctx.translate(o.x,o.y);ctx.scale(S,S);ctx.lineJoin='round';ctx.lineCap='round';if(o.kind==='wreck')drawWreck(w,h);else if(o.kind==='scrap')drawScrapPile(w,h);else if(o.kind==='barrel')drawBarrels(w,h);else if(o.kind==='barricade')drawBarricade(w,h);else{ctx.fillStyle='#07090877';ctx.fillRect(5,h,w-1,8);ctx.fillStyle=mechanismBlocker?'#654932':'#75583d';ctx.strokeStyle='#20261f';ctx.lineWidth=4;ctx.fillRect(0,0,w,h);ctx.strokeRect(2,2,w-4,h-4);artLine([[8,8],[w-8,h-8]],'#33281f',6);artLine([[w-8,8],[8,h-8]],'#33281f',6);if(mechanismBlocker){originRect(w/2-13,h/2-9,26,18,'#252a24','#211d18',3);ellipse(ctx,w/2,h/2,mechanismSolved?5:4,mechanismSolved?5:4,mechanismSolved?'#9bc473':'#8b3838',true)}}ctx.restore()})};
 function explodeCannonBag(room,bag,damage=false){if(bag.dead)return;bag.dead=true;TRASH_BAG_SKILL?.explodeTrashAt(bag.x,bag.y,18);soundSfx('break');if(damage&&(isLegacyMobileContent()?Math.hypot(state.player.x-bag.x,state.player.y-bag.y)<70*S:playerBodyTouches(bag)))hurt(1,bag)}
 function solvedCannonFactor(trap){return trap.solved?.5:1}
 function spawnCannonBag(trap){const cannon=trap.cannons[trap.shot%trap.cannons.length],speed=trap.projectileSpeed*solvedCannonFactor(trap)*S;trap.shot++;trap.projectiles.push({x:cannon.x+cannon.dx*34*S,y:cannon.y+cannon.dy*34*S,vx:cannon.dx*speed,vy:cannon.dy*speed,r:20*S,life:trap.kind==='scales'?6:3.4,rotation:Math.atan2(cannon.dy,cannon.dx)+Math.PI/2,variant:trap.shot%3,bouncesLeft:trap.bounces||0,bouncesDone:0,dead:false});soundSfx('warning')}
