 const refreshBase=refresh;refresh=function(){const result=refreshBase();if(visible()){const room=state.rooms[state.room],last=ALL_TEMPLATES.length-1,next=room.links.findIndex(id=>id===room.zoneOneIndex+1),puzzlePending=room.trashPuzzle&&!room.trashPuzzle.solved,alive=room.enemies.some(e=>e.hp>0),mimicAlive=room.enemies.some(e=>e.bagMimic&&e.hp>0),bigAlive=room.enemies.some(e=>e.bigKid&&e.hp>0),stopAlive=room.enemies.filter(e=>e.stopKid&&e.hp>0).length,goblinAlive=room.enemies.some(e=>e.trashGoblin&&e.hp>0),hungry=room.enemies.find(e=>e.hungry&&e.hp>0),escaping=room.specificRoom&&room.specificEscapeStarted;$('#zone-name').textContent='Vertedero exterior';$('#zone-number').textContent='ZONA 1 · NIVEL 1';$('#zone-tag').textContent='EXTERIOR / RUTA PROCEDURAL';$('#room-label').textContent=room.name.toUpperCase();$('#feed-label').textContent='ZONA 1 / SEÑAL EN DIRECTO';$('#objective').textContent=room.clear?(room.zoneOneIndex<last?`SIGUIENTE SALA · ${directionName(next)}`:'RECORRIDO COMPLETADO · ACCESO AL CEMENTERIO · NORTE'):mimicAlive?'DERROTÁ A LA BOLSA MÍMICA':bigAlive?'DERROTÁ AL NIÑO GRANDE':escaping?'EL TIRADOR ESTÁ HUYENDO':room.bigKidVariant&&stopAlive?`NIÑOS CON SEÑAL EN FURIA · ${stopAlive}/2`:room.specificRoom&&stopAlive?`NIÑOS CON SEÑAL RESTANTES · ${stopAlive}/2`:goblinAlive||hungry?'ELIMINÁ AL DUENDE Y AL HAMBRIENTO':room.trapData?trapObjective(room.trapData):puzzlePending?(alive?'NEUTRALIZÁ LA SALA':'ACTIVÁ EL MECANISMO'):'ELIMINÁ LAS AMENAZAS';$('#hint').textContent=room.clear?(room.zoneOneIndex<last?`${directionName(next)} · Siguiente sala`:'Norte · Scrapy espera junto al puente'):mimicAlive?'Movete: saltará cuatro veces y arrojará basura al caer':bigAlive?'Esquivá el dardo lento · De cerca hará dos barridos y puede cubrirse':escaping?'Apartate de los últimos dardos · La sala se abrirá al escapar':room.bigKidVariant?'Los dos están heridos, furiosos y se mueven un poco más rápido':room.specificRoom?'Los tiradores de las tapas huirán cuando caigan los dos de las señales':hungry&&hungry.hungerPhase!=='armored'?'Seguí el rastro · El Hambriento queda expuesto después de saltar':goblinAlive?'Rompé la bolsa escudo · Si el duende escapa, buscará otra':room.trapData?trapHint(room.trapData):puzzlePending?'Las bolsas también reaccionan con algunos mecanismos':'Dispará y esquivá · Las bolsas repartidas también dañan';$('#touch-level').textContent=`Z1 · SALA ${room.zoneOneIndex+1}/${ALL_TEMPLATES.length} · ${difficultySettings().name.toUpperCase()}`;drawMapRooms(mc,210,158,false)}return result};
 const mimicRefreshBase=refresh;refresh=function(){const result=mimicRefreshBase();if(visible()){const room=state.rooms[state.room],data=room.mimicData,reward=room.rewardData,genericStopAlive=room.enemies.some(enemy=>enemy.genericStopKid&&enemy.hp>0);if(genericStopAlive&&!room.clear){$('#objective').textContent='ELIMINÁ A LA PATRULLA DEL VERTEDERO';$('#hint').textContent='Los niños con señal atacan de cerca y pueden cubrirse después de recibir daño'}if(room.zoneOneTemplate==='leachate'&&room.clear&&!room.trashPuzzle?.solved){$('#objective').textContent='SALIDAS ABIERTAS · RECEPTOR PENDIENTE';$('#hint').textContent='Podés buscar otra bolsa en una sala anterior y volver cuando estés listo'}if(reward&&!room.clear){if(reward.kind==='redLight'){$('#objective').textContent=`ACTIVÁ LOS TRES BOTONES · ${reward.progress}/3`;$('#hint').textContent=reward.phase==='red'?'Luz roja: quedate completamente quieto':'Luz verde: recorré el zigzag y seguí los números'}else{$('#objective').textContent=`ORQUESTA DE CHATARRA · RONDA ${reward.round}/3`;$('#hint').textContent=reward.phase==='input'?'Pisá los instrumentos en el orden que tocó el robot':'Escuchá y mirá la secuencia · un error termina el concierto'}}if(data&&!room.clear){$('#objective').textContent=data.solved?'TRAMPA DESACTIVADA · ESTABILIZANDO SALA':'ENCONTRÁ LA ÚNICA BOLSA REAL';$('#hint').textContent=data.solved?'Las mímicas volvieron a ser bolsas normales':'Impulso para probar una bolsa · Lanzá la verdadera contra el único botón'}}return result};
 const zoneRoomBase=goRoom;goRoom=function(index,dir){const result=zoneRoomBase(index,dir);if(state.room===index&&state.rooms[index]?.zoneOneCombat){configureTrashPuzzleEntry(state.rooms[index],dir);prepareSpecificEntry(state.rooms[index])}return result};
 const tickBase=tick;tick=function(dt){if(active())unlockLeachateExit(state.rooms[state.room]);const bombs=active()?state.bullets.filter(bullet=>bullet.goblinBomb):[];tickBase(dt);for(const bomb of bombs)if(!state.bullets.includes(bomb))explodeGoblinBomb(bomb);if(!active())return;const room=state.rooms[state.room];unlockLeachateExit(room);updateSpecificOutcome(room);updateTrapRoom(room,dt);updateRewardRoom(room,dt);if(room.zoneOneIndex===ALL_TEMPLATES.length-1&&room.clear&&!room.finishAnnounced){room.finishAnnounced=true;notify('ACCESO FINAL DISPONIBLE · Scrapy espera junto al puente del cementerio.');$('#radio-text').textContent='«Llegaste al acantilado. Scrapy dice que dos receptores deberían desplegar el puente al cementerio.»';refresh()}};
