 window.ZONE_ONE_COMBAT=Object.freeze({start,lidBody,lidShotTouches,testBagImpact,bagPoints,needsPuzzleBag,interceptBagPickup,isBagUsable,get active(){return active()},get visible(){return visible()},get runActive(){return runActive()},get generation(){return generation},get signature(){return signature},get selectedMiniboss(){return selectedMiniboss?{...selectedMiniboss}:null},get routePlan(){return{...ROUTE_PLAN}},get rooms(){return runActive()?state.rooms.map(r=>({name:r.name,template:r.zoneOneTemplate,trap:r.trapData?.kind||null,reward:r.rewardData?.kind||null,segment:r.routeSegment,ambientMimic:!!r.ambientMimicData,x:r.x,y:r.y,clear:r.clear,links:[...r.links]})):[]}});
