  if(shark.state==='breach'){shark.timer-=dt;const progress=clamp(1-shark.timer/.68,0,1);shark.air=Math.sin(progress*Math.PI)*.9;if(shark.timer<=0){shark.air=0;if(shark.breaches>=3)beginRest('charge',2.7);else beginRest('breach',1.9)}return}
