  if(shark.state==='charge'){const dir=shark.chargeSide<0?1:-1;shark.x+=dir*shark.chargeSpeed*dt*(window.ZONE_ONE_ITEM_EFFECTS?.factor(shark,true)??1);shark.angle=dir>0?0:Math.PI;addWake(dt);if(!shark.hitPlayer&&sharkBodyHit(state.player.x,state.player.y,state.player.r)){shark.hitPlayer=true;hurt(1,shark)}const arrived=dir>0?shark.x>bounds.right+145:shark.x<bounds.left-145;if(arrived){shark.charges++;if(shark.charges<(hardMode()?8:6))nextCharge();else{shark.x=dir>0?bounds.right-70:bounds.left+70;shark.breaches=0;beginRest('breach',2.45)}}return}
  if(shark.state==='carDrop')return;
  if(shark.state==='phase2Dive'){shark.timer-=dt;shark.sink=clamp(1-shark.timer/.72,0,1);if(shark.timer<=0){shark.state='phase2FinalHunt';shark.timer=1.35;shark.sink=1;shark.r=0;shark.hitPlayer=false}return}
  if(shark.state==='phase2FinalHunt'){moveToward(state.player.x,state.player.y,245,dt);addWake(dt);hurtFinContact();shark.timer-=dt;if(shark.timer<=0||Math.hypot(state.player.x-shark.x,state.player.y-shark.y)<92){shark.state='phase2FinalWarning';shark.timer=.72;shark.attackX=clamp(state.player.x,bounds.left+90,bounds.right-90);shark.attackY=clamp(state.player.y,bounds.top+90,bounds.bottom-90);shark.x=shark.attackX;shark.y=shark.attackY;wake=[];soundSfx('warning')}return}
  if(shark.state==='phase2FinalWarning'){shark.timer-=dt;if(shark.timer<=0){shark.state='phase2FinalBreach';shark.timer=.82;shark.air=0;radialTrash(shark.x,shark.y,20,245);hurtPlayerNear(98);syncSharkRadius();soundSfx('break')}return}
  if(shark.state==='phase2FinalBreach'){shark.timer-=dt;const progress=clamp(1-shark.timer/.82,0,1);shark.air=Math.sin(progress*Math.PI);if(shark.timer<=0){shark.air=0;shark.sink=0;shark.phaseTwoPending=false;shark.phaseTwo=true;shark.state='recover';shark.timer=2.85;syncSharkRadius();$('#radio-text').textContent='«¡Me quedé sin autos! Ya salió por completo y perdió gran parte de su armadura de basura: terminá el trabajo.»';notify('FASE 2 · EL TIBURÓN QUEDA EXPUESTO')}return}
