 function damageShark(amount){if(!shark||shark.dead||!vulnerable())return 0;const floor=shark.phaseTwo?0:shark.max*.5,dealt=Math.min(Math.max(0,shark.hp-floor),Math.max(0,amount));if(dealt<=0){soundSfx('shield');return 0}const previousTrash=shark.trashLost;shark.hp-=dealt;shark.trashLost=Math.max(shark.trashLost,Math.floor((1-shark.hp/shark.max)*14));shark.flash=.12;syncSharkRadius();if(shark.trashLost>previousTrash){TRASH_BAG_SKILL?.explodeTrashAt(shark.x,shark.y,12);burst(shark.x,shark.y,'#75614a',5)}soundSfx('enemyHit');if(shark.hp<=0){shark.hp=0;shark.r=0;shark.dead=true;window.BUNKER_COLLECTIONS?.recordDefeat('boss:bullShark');shark.state='escaping';shark.timer=2.2;shark.angle=shark.x<W/2?-.18:Math.PI+.18;shark.sink=0;danger=[];target=null;car=null;gainXP(120*XP_REWARD_SCALE);recoveryDrops.push({kind:'heal',x:W/2+55,y:H/2,value:3,guaranteedReward:true});burst(shark.x,shark.y,'#8f5643',45);notify('TIBURÓN TORO DERROTADO · SE FUE A RECUPERAR · VIDA EN EL SUELO');$('#radio-text').textContent='«Escapó entre la basura. El tiburón se fue a recuperar; seguramente volverá.»';soundSfx('bossDeath');refresh()}return dealt}
 function testBagImpact(b,oldX=b.x,oldY=b.y){if(!active)return false;if(target&&pointDistance(target.x,target.y,oldX,oldY,b.x,b.y)<=target.r+18){const impact={x:target.x,y:target.y,max:target.max};hitTarget(impact.max);TRASH_BAG_SKILL.consumeBag(b,{x:impact.x,y:impact.y,delay:1.5});TRASH_BAG_SKILL.explodeTrashAt(impact.x,impact.y,24);return true}if(shark&&!shark.dead&&vulnerable()&&sharkSegmentHit(oldX,oldY,b.x,b.y,34)){damageShark(32);TRASH_BAG_SKILL.consumeBag(b,{x:shark.x,y:shark.y,delay:1.7});TRASH_BAG_SKILL.explodeTrashAt(shark.x,shark.y,22);return true}return false}
 function updatePlayerShots(dt){for(const shot of [...state.shots]){shot.previousX=shot.x;shot.previousY=shot.y;shot.x+=shot.vx*dt;shot.y+=shot.vy*dt;shot.life-=dt;if(shot.life<=0)continue;if(window.ZONE_ONE_ITEM_EFFECTS?.customEnvironment(shot))continue;if(target&&(window.ZONE_ONE_ITEM_EFFECTS?.canHit(shot,target)??true)&&pointDistance(target.x,target.y,shot.previousX,shot.previousY,shot.x,shot.y)<=target.r+(shot.r||4)){const receptor=target;hitTarget(shot.damage??stats().damage);ZONE_ONE_ITEM_EFFECTS.finishHit(shot,receptor);continue}if(shark&&!shark.dead&&vulnerable()&&(window.ZONE_ONE_ITEM_EFFECTS?.canHit(shot,shark)??true)&&sharkSegmentHit(shot.previousX,shot.previousY,shot.x,shot.y,shot.r||4)){ZONE_ONE_ITEM_EFFECTS.hitCustom(shot,shark,damageShark,true);ZONE_ONE_ITEM_EFFECTS.finishHit(shot,shark);}}state.shots=state.shots.filter(shot=>shot.life>0&&shot.x>30&&shot.x<W-30&&shot.y>30&&shot.y<H-30)}
