 function finish(direction='forward'){if(!active||!shark?.dead)return false;const next=context?.returnIndex,dir=context?.returnDir,procedural=context?.procedural;active=false;hideBossHud();TRASH_BAG_SKILL?.resetBossBags?.();if(procedural&&Number.isInteger(next)){const gateRoom=state.rooms[6];if(gateRoom){gateRoom.minibossDefeated=true;gateRoom.drops.push(...recoveryDrops.map(drop=>({...drop})));recoveryDrops=[]}if(direction==='back'){const s=roomScale(),p=state.player;p.x=(dir===2?75:dir===3?885:480)*s;p.y=(dir===0?555:dir===1?85:320)*s;p.inv=1;state.shots=[];state.bullets=[];refresh();notify('VOLVISTE A LA SALA ANTERIOR · EL CAMINO SIGUE ABIERTO');return true}routeGoRoom(next,dir);notify('SEGUNDO TRAMO · 5 SALAS HASTA EL JEFE FINAL');return true}returnBunker();return true}
