 function drawEntranceFloor(){ctx.fillStyle='#070908';ctx.fillRect(0,0,W,H);if(isLegacyMobileContent()){ for(let row=-1;row<19;row++)for(let col=-1;col<22;col++)arenaBag(col*64+(row%2)*31,row*48+((col*17+row*11)%9),68,49,(row+col+2)%4);ctx.fillStyle='#2b2c2577';ctx.beginPath();ctx.roundRect(52,52,W-104,H-104,28);ctx.fill();}else{ctx.save();ctx.scale(FIELD_ROOM_SCALE,FIELD_ROOM_SCALE);DUMP_SCENERY.drawGround(W/FIELD_ROOM_SCALE,H/FIELD_ROOM_SCALE,0,{x:52/FIELD_ROOM_SCALE,y:52/FIELD_ROOM_SCALE,w:(W-104)/FIELD_ROOM_SCALE,h:(H-104)/FIELD_ROOM_SCALE});ctx.restore()}ctx.strokeStyle='#6f6852';ctx.lineWidth=12;ctx.strokeRect(48,48,W-96,H-96);drawArenaDoor(12,'PUERTA NORTE',stage!=='cleared');drawArenaDoor(H-80,'PUERTA DE ENTRADA',stage!=='cleared')}
 function startGrab(){if(stage!=='entrance')return;stage='grab';transition=0;Object.assign(state.player,{x:W/2,y:H/2,dash:0,activeDashX:0,activeDashY:0,inv:2});notify('ALGO TE AGARRÓ · LA MESA SE ABRE DEBAJO');$('#radio-text').textContent='«¡Una mano! Te está arrastrando hacia otra sala.»';soundSfx('warning');refresh()}
