 function impactAt(x,y,r,playerDamage=1,enemyDamage=12){TRASH_BAG_SKILL?.explodeTrashAt(x,y,24);burst(x,y,'#c18a5f',22);if(Math.hypot(state.player.x-x,state.player.y-y)<r+state.player.r)hurt(playerDamage,boss);for(const enemy of summons)if(enemy.hp>0&&Math.hypot(enemy.x-x,enemy.y-y)<r+enemy.r)damageSummon(enemy,enemyDamage);soundSfx('break')}
 function spawnFallingMimics(){const count=2+(Math.random()<.5?0:1);for(let i=0;i<count;i++)falling.push({x:random(tableBounds.left+100,tableBounds.right-100),y:205,targetY:random(340,tableBounds.bottom-35),delay:i*.17,rotation:random(-.5,.5),landed:false,life:1,variant:i%3})}
 function summonStats(kind){return{goblin:{hp:14,r:22,speed:58},hungry:{hp:34,r:25,speed:88},mimic:{hp:32,r:34,speed:76},signal:{hp:18,r:20,speed:62},big:{hp:44,r:34,speed:48}}[kind]}
 function makeSummon(kind,x,y,extra={}){const stats=summonStats(kind),enemy={kind,x,y,r:stats.r,hp:stats.hp,max:stats.hp,speed:stats.speed,flash:0,dead:false,cool:.35,phase:random(0,Math.PI*2),hop:0,contact:0,...extra};if(kind==='mimic')Object.assign(enemy,{bagMimic:true,mimicVariant:Math.floor(random(0,3)),mimicGroundX:x,mimicGroundY:y,mimicAir:0,mimicPhase:'laugh',mimicTimer:.62,mimicJump:0,mimicTurn:0,mimicAngle:random(0,Math.PI*2)});return enemy}
 function realEnemy(kind,x,y,index=0){const enemy=ZONE_ONE_ENEMY_RUNTIME.create(kind,x,y,index);enemy.kind=kind;enemy.realZoneEnemy=true;return enemy}
 function weakenJarEnemy(enemy){const healthFactor=enemy.bigKid?.5:.65;enemy.collectorJarEnemy=true;enemy.originalMax=enemy.max;enemy.max*=healthFactor;enemy.hp=Math.min(enemy.hp*healthFactor,enemy.max);if(Number.isFinite(enemy.goblinBagMax)){enemy.originalShieldMax=enemy.goblinBagMax;enemy.goblinBagMax*=.65;enemy.goblinBagHp=Math.min(enemy.goblinBagHp*.65,enemy.goblinBagMax)}return enemy}
 function spawnJarEnemies(jar){const inward=jar.x<W/2?1:-1;for(let i=0;i<3;i++)summons.push(weakenJarEnemy(realEnemy(jar.kind,jar.x+inward*(105+(i%2)*42),clamp(jar.y+(i-1)*58,tableBounds.top+55,tableBounds.bottom-55),i)))}
 function spawnCeilingMimic(bag){const enemy=realEnemy('mimic',bag.x,bag.y,bag.variant);enemy.ceilingMimic=true;summons.push(enemy)}
 function spawnWeakStopKid(enemy){const child=realEnemy('signal',enemy.x,enemy.mimicGroundY??enemy.y,0);child.collectorJarEnemy=true;child.collectorBigChild=true;child.originalMax=child.max;child.max=Math.max(1,child.max*.2);child.hp=child.max;child.spawnTime=.3;summons.push(child);burst(child.x,child.y,'#b64b3e',16)}
 function rollSpecimenDrop(enemy){const roll=Math.random(),x=clamp(enemy.x,tableBounds.left+24,tableBounds.right-24),y=clamp(enemy.mimicGroundY??enemy.y,tableBounds.top+24,tableBounds.bottom-24);if(roll<HEAL_DROP_CHANCE)specimenDrops.push({kind:'heal',x,y});else if(roll<HEAL_DROP_CHANCE+XP_DROP_CHANCE)specimenDrops.push({kind:'xp',x,y,value:5*XP_REWARD_SCALE})}
 function reapSummonDeaths(){const dead=summons.filter(enemy=>enemy.hp<=0&&!enemy.collectorDeathHandled);for(const enemy of dead){enemy.collectorDeathHandled=true;if(!isMobileGame())window.ENEMY_SKINS?.drop(enemy,specimenDrops);if(enemy.bigKid)spawnWeakStopKid(enemy);rollSpecimenDrop(enemy)}summons=summons.filter(enemy=>enemy.hp>0)}
 function updateSpecimenDrops(dt){if(state.mode!=='play'||state.player.hp<=0)return;const player=state.player;for(const drop of [...specimenDrops]){let distanceToPlayer=Math.hypot(drop.x-player.x,drop.y-player.y);if(drop.kind==='xp'&&distanceToPlayer<180){drop.x+=(player.x-drop.x)*dt*7;drop.y+=(player.y-drop.y)*dt*7;distanceToPlayer=Math.hypot(drop.x-player.x,drop.y-player.y)}if(drop.kind==='xp'&&distanceToPlayer<24){specimenDrops.splice(specimenDrops.indexOf(drop),1);gainXP(drop.value);refresh()}else if(drop.kind==='heal'&&distanceToPlayer<26&&player.hp<player.maxHp){specimenDrops.splice(specimenDrops.indexOf(drop),1);player.hp=Math.min(player.maxHp,player.hp+2);refresh()}}}
 function updateBossRewards(dt){if(state.mode!=='play'||state.player.hp<=0)return;const player=state.player;for(const drop of [...bossRewards]){let distanceToPlayer=Math.hypot(drop.x-player.x,drop.y-player.y);if(drop.kind==='xp'&&distanceToPlayer<180){drop.x+=(player.x-drop.x)*dt*7;drop.y+=(player.y-drop.y)*dt*7;distanceToPlayer=Math.hypot(drop.x-player.x,drop.y-player.y)}if(drop.kind==='xp'&&distanceToPlayer<24){bossRewards.splice(bossRewards.indexOf(drop),1);gainXP(drop.value);soundSfx('activeReady');refresh()}else if(drop.kind==='heal'&&distanceToPlayer<26&&player.hp<player.maxHp){bossRewards.splice(bossRewards.indexOf(drop),1);player.hp=Math.min(player.maxHp,player.hp+2);soundSfx('activeReady');refresh()}}}
 function leaveMimicTrash(enemy){trashDrops.push({x:enemy.x,y:enemy.y+12,r:16+random(0,6),rotation:random(-.5,.5),life:14});if(trashDrops.length>30)trashDrops.shift()}
 function beginCollectorMimicJump(enemy){const angle=random(0,Math.PI*2),distance=236;enemy.mimicPhase='jump';enemy.mimicTimer=.72;enemy.mimicFromX=enemy.x;enemy.mimicFromY=enemy.mimicGroundY??enemy.y;enemy.mimicToX=clamp(enemy.mimicFromX+Math.cos(angle)*distance,tableBounds.left+40,tableBounds.right-40);enemy.mimicToY=clamp(enemy.mimicFromY+Math.sin(angle)*distance,tableBounds.top+45,tableBounds.bottom-35);enemy.mimicGroundX=enemy.mimicFromX;enemy.mimicGroundY=enemy.mimicFromY;soundSfx('warning')}
 function collectorMimicBurst(enemy){const x=enemy.x,y=enemy.mimicGroundY??enemy.y,offset=random(0,Math.PI*2);TRASH_BAG_SKILL?.explodeTrashAt(x,y,42);leaveMimicTrash(enemy);for(let i=0;i<12;i++)addHazard(x,y,offset+i*Math.PI/6,186+(i%3)*36,10+i%2*2,2.1);soundSfx('break')}
 function updateCollectorMimic(enemy,dt){enemy.mimicTimer-=dt;if(enemy.mimicPhase==='laugh'){enemy.mimicAir=Math.abs(Math.sin(state.elapsed*18))*5;if(enemy.mimicTimer<=0)beginCollectorMimicJump(enemy);return}if(enemy.mimicPhase==='jump'){const progress=clamp(1-enemy.mimicTimer/.72,0,1),ease=progress*progress*(3-2*progress);enemy.mimicGroundX=enemy.mimicFromX+(enemy.mimicToX-enemy.mimicFromX)*ease;enemy.mimicGroundY=enemy.mimicFromY+(enemy.mimicToY-enemy.mimicFromY)*ease;enemy.mimicAir=Math.sin(progress*Math.PI)*111;enemy.x=enemy.mimicGroundX;enemy.y=enemy.mimicGroundY-enemy.mimicAir;if(enemy.mimicTimer<=0){enemy.x=enemy.mimicToX;enemy.y=enemy.mimicToY;enemy.mimicGroundX=enemy.x;enemy.mimicGroundY=enemy.y;enemy.mimicAir=0;enemy.mimicJump++;collectorMimicBurst(enemy);if(enemy.mimicJump>=4){enemy.dead=true;enemy.hp=0}else{enemy.mimicPhase='scuttle';enemy.mimicTimer=.42;enemy.mimicTurn=0}}return}enemy.mimicTurn-=dt;if(enemy.mimicTurn<=0){enemy.mimicTurn=.08+Math.random()*.1;enemy.mimicAngle+=random(-1.8,1.8)}enemy.x=clamp(enemy.x+Math.cos(enemy.mimicAngle)*250*dt,tableBounds.left+enemy.r,tableBounds.right-enemy.r);enemy.y=clamp(enemy.y+Math.sin(enemy.mimicAngle)*250*dt,tableBounds.top+enemy.r,tableBounds.bottom-enemy.r);enemy.mimicGroundX=enemy.x;enemy.mimicGroundY=enemy.y;enemy.mimicAir=0;if(enemy.mimicTimer<=0)beginCollectorMimicJump(enemy)}
 function defeatBoss(){if(boss.dead)return;boss.dead=true;window.BUNKER_COLLECTIONS?.recordDefeat('boss:collector');TRASH_BAG_SKILL?.clearDebris?.();boss.state='defeated';boss.hp=0;hazards=[];falling=[];summons=[];trashDrops=[];const preservedSkins=specimenDrops.filter(d=>d.skinSample);specimenDrops=[];bossRewards=[...preservedSkins.map((d,i)=>({...d,x:W/2-100+i%4*55,y:H/2+70+Math.floor(i/4)*45})),{kind:'heal',x:W/2-48,y:H/2+18},{kind:'xp',x:W/2+48,y:H/2+18,value:150*XP_REWARD_SCALE}];screenShake=0;shakePower=0;state.bullets=[];Object.assign(state.player,{x:W/2,y:575,inv:3,dash:0});stage='release';transition=0;burst(boss.x,boss.y,'#b99569',40);notify('RECOLECTOR DERROTADO · DEJÓ RECOMPENSAS EN LA FOSA');$('#radio-text').textContent='«Te está devolviendo a la fosa. La vida y la XP quedaron afuera para que puedas recogerlas.»';soundSfx('bossDeath');refresh()}
 function damageBoss(amount){if(!bossAlive())return 0;const dealt=Math.min(boss.hp,Math.max(0,amount));boss.hp-=dealt;boss.flash=.15;soundSfx('enemyHit');if(boss.hp<=0)defeatBoss();return dealt}
 function resolveFist(){const x=boss.targetX,y=boss.targetY;boss.handRest={side:1,x,y,strong:true};impactAt(x,y,112,1,24);const jar=jars.find(item=>!item.broken&&Math.hypot(item.x-x,item.y-y)<item.r+62);if(jar){jar.broken=true;jar.flash=.5;damageBoss(boss.max*.25);if(!boss.dead){spawnJarEnemies(jar);boss.state='stunned';boss.timer=8;boss.stunLong=true;notify(`FRASCO DE ${jar.name} ROTO · 3 ESPECÍMENES · 8 s DE ATURDIMIENTO`)}}else{holes.push({x:clamp(x,tableBounds.left+65,tableBounds.right-65),y:clamp(y,tableBounds.top+65,tableBounds.bottom-65),r:62,seed:holes.length});damageBoss(boss.max*.15);if(!boss.dead){boss.state='stunned';boss.timer=1.8;boss.stunLong=false;notify('PUÑO CONTRA LA MESA · AGUJERO PERMANENTE · −15% DE VIDA')}}refresh()}
 function updateBoss(dt){if(window.CHARACTER_OUTFITS?.confused(boss))return;dt*=window.TRAINING_COLISEUM?.enemyTempo||1;if(!boss||boss.dead)return;boss.flash=Math.max(0,boss.flash-dt);for(const jar of jars)jar.flash=Math.max(0,jar.flash-dt);if(boss.state==='intro'){boss.timer-=dt;if(boss.timer<=0)beginRest(3);return}if(boss.state==='rest'){boss.timer-=dt;if(boss.timer<=0)choosePattern();return}if(boss.state==='altWarning'){if(boss.warningPhase==='tracking'){boss.targetX=state.player.x;boss.targetY=state.player.y}boss.timer-=dt;if(boss.timer<=0){if(boss.warningPhase==='tracking'){boss.warningPhase='locked';boss.timer=HAND_LOCK;soundSfx('warning')}else{impactAt(boss.targetX,boss.targetY,84,1,15);boss.handRest={side:boss.altSide,x:boss.targetX,y:boss.targetY};boss.altCount++;boss.state='altHold';boss.timer=HAND_REST}}return}if(boss.state==='altHold'){boss.timer-=dt;if(boss.timer<=0){if(boss.altCount>=4)beginRest(3.5);else{boss.altSide*=-1;beginTrackedWarning('altWarning')}}return}if(boss.state==='ceilingWindup'){boss.timer-=dt;if(boss.timer<=0){shakeRoom();spawnFallingMimics();boss.state='ceilingAssault';boss.assaultPhase='tracking';boss.assaultCount=0;boss.handTimer=.9;boss.targetX=state.player.x;boss.targetY=state.player.y;soundSfx('break')}return}if(boss.state==='ceilingAssault'){boss.handTimer-=dt;if(boss.assaultPhase==='tracking'){boss.targetX=state.player.x;boss.targetY=state.player.y;if(boss.handTimer<=0){boss.assaultPhase='locked';boss.handTimer=HAND_LOCK;soundSfx('warning')}}else if(boss.assaultPhase==='locked'&&boss.handTimer<=0){impactAt(boss.targetX,boss.targetY,78,1,13);boss.handRest={side:-boss.ceilingSide,x:boss.targetX,y:boss.targetY};boss.assaultPhase='hold';boss.handTimer=MIMIC_HAND_REST;boss.assaultCount++}else if(boss.assaultPhase==='hold'&&boss.handTimer<=0){if(boss.assaultCount>=3)beginRest(3.5);else{boss.handRest=null;boss.assaultPhase='tracking';boss.handTimer=.9;boss.targetX=state.player.x;boss.targetY=state.player.y}}return}if(boss.state==='fistWarning'){if(boss.warningPhase==='tracking'){boss.targetX=state.player.x;boss.targetY=state.player.y}boss.timer-=dt;if(boss.timer<=0){if(boss.warningPhase==='tracking'){boss.warningPhase='locked';boss.timer=HAND_LOCK;soundSfx('warning')}else{boss.state='fistImpact';boss.timer=FIST_DESCENT;soundSfx('warning')}}return}if(boss.state==='fistImpact'){boss.timer-=dt;if(boss.timer<=0)resolveFist();return}if(boss.state==='stunned'){boss.timer-=dt;if(boss.timer<=0)beginRest(3.5);return}}
 function updateFalling(dt){dt*=window.TRAINING_COLISEUM?.enemyTempo||1;for(const bag of falling){if(bag.landed){bag.life-=dt;continue}bag.delay-=dt;if(bag.delay>0)continue;bag.y+=610*dt;bag.rotation+=dt*8;if(bag.y>=bag.targetY){bag.y=bag.targetY;bag.landed=true;bag.life=.65;impactAt(bag.x,bag.y,58,1,10);spawnCeilingMimic(bag)}}falling=falling.filter(item=>!item.landed||item.life>0)}
 function addHazard(x,y,angle,speed=220,r=9,life=3){hazards.push({x,y,vx:Math.cos(angle)*speed,vy:Math.sin(angle)*speed,r,life,rotation:angle})}
 function updateRealEnemy(enemy,dt){const room=state.rooms?.[state.room],bulletStart=state.bullets.length;if(!room)ZONE_ONE_ENEMY_RUNTIME.update(enemy,dt);else{const saved={obstacles:room.obstacles,liquidRects:room.liquidRects,lidData:room.lidData,trapData:room.trapData};room.obstacles=[];room.liquidRects=[];room.lidData=null;room.trapData=null;try{ZONE_ONE_ENEMY_RUNTIME.update(enemy,dt)}finally{Object.assign(room,saved)}}for(const bullet of state.bullets.slice(bulletStart)){bullet.collectorZoneOne=true;if(enemy.bagMimic&&bullet.mimicTrash){if(!bullet.collectorMimicTrash)mimicGarbageBursts++;bullet.collectorMimicTrash=true;bullet.trashDanger=false;bullet.trashVariant%=4}}}
 function updateEnemyBullets(dt){dt*=window.TRAINING_COLISEUM?.enemyTempo||1;const current=[...state.bullets],detonate=[];for(const bullet of current){bullet.x+=bullet.vx*dt;bullet.y+=bullet.vy*dt;bullet.life-=dt;bullet.rotation=(bullet.rotation||0)+dt*6;if(bullet.life>0&&Math.hypot(bullet.x-state.player.x,bullet.y-state.player.y)<(bullet.r||7)+state.player.r){hurt(1,bullet);bullet.life=0}if(bullet.goblinBomb&&bullet.life<=0)detonate.push(bullet)}state.bullets=state.bullets.filter(bullet=>bullet.life>0&&bullet.x>25&&bullet.x<W-25&&bullet.y>220&&bullet.y<H-25);for(const bomb of detonate)ZONE_ONE_ENEMY_RUNTIME.explodeBomb(bomb)}
 function updateSummons(dt){dt*=window.TRAINING_COLISEUM?.enemyTempo||1;for(const enemy of summons){if(enemy.hp<=0||window.CHARACTER_OUTFITS?.confused(enemy))continue;enemy.flash=Math.max(0,(enemy.flash||0)-dt);if(enemy.paralyzeTime>0)continue;if(enemy.realZoneEnemy){updateRealEnemy(enemy,dt);continue}enemy.cool-=dt;enemy.contact=Math.max(0,enemy.contact-dt);const dx=state.player.x-enemy.x,dy=state.player.y-enemy.y,d=Math.hypot(dx,dy)||1,angle=Math.atan2(dy,dx);if(enemy.kind==='mimic'){updateCollectorMimic(enemy,dt);if(Math.hypot(state.player.x-enemy.x,state.player.y-enemy.y)<enemy.r+state.player.r+4&&enemy.contact<=0){hurt(1,enemy);enemy.contact=1}continue}let mx=0,my=0;if(['goblin','signal'].includes(enemy.kind)){if(d>300){mx=Math.cos(angle);my=Math.sin(angle)}else if(d<165){mx=-Math.cos(angle);my=-Math.sin(angle)}else{mx=Math.cos(angle+Math.PI/2);my=Math.sin(angle+Math.PI/2)}if(enemy.cool<=0){addHazard(enemy.x,enemy.y-10,angle,enemy.kind==='signal'?265:215,enemy.kind==='signal'?9:11,3);enemy.cool=enemy.kind==='signal'?1.05:1.25}}else{mx=Math.cos(angle);my=Math.sin(angle)}const speed=enemy.speed;enemy.x=clamp(enemy.x+mx*speed*dt,tableBounds.left+enemy.r,tableBounds.right-enemy.r);enemy.y=clamp(enemy.y+my*speed*dt,tableBounds.top+enemy.r,tableBounds.bottom-enemy.r);if(d<enemy.r+state.player.r+4&&enemy.contact<=0){hurt(1,enemy);enemy.contact=1}}reapSummonDeaths();for(const pile of trashDrops)pile.life-=dt;trashDrops=trashDrops.filter(pile=>pile.life>0)}
 function updateHazards(dt){dt*=window.TRAINING_COLISEUM?.enemyTempo||1;for(const item of hazards){item.x+=item.vx*dt;item.y+=item.vy*dt;item.life-=dt;item.rotation+=dt*6;if(item.life>0&&Math.hypot(item.x-state.player.x,item.y-state.player.y)<item.r+state.player.r){hurt(1,item);item.life=0}}hazards=hazards.filter(item=>item.life>0&&item.x>40&&item.x<W-40&&item.y>220&&item.y<H-35)}
 function shotDistance(x,y,shot){return segmentDistance({x,y},{x:shot.previousX,y:shot.previousY},shot)}
 function collectorBodyHit(x,y,padding=0){if(!bossAlive()||y>244+padding)return false;const dx=(x-boss.x)/(100+padding),dy=(y-boss.y+30)/(144+padding);return dx*dx+dy*dy<=1}
 function collectorSegmentHit(shot){const length=Math.hypot(shot.x-shot.previousX,shot.y-shot.previousY),steps=Math.max(1,Math.ceil(length/12));for(let i=0;i<=steps;i++){const t=i/steps;if(collectorBodyHit(shot.previousX+(shot.x-shot.previousX)*t,shot.previousY+(shot.y-shot.previousY)*t,shot.r||4))return true}return false}
 function updateShots(dt){for(const shot of [...state.shots]){shot.previousX=shot.x;shot.previousY=shot.y;shot.x+=shot.vx*dt;shot.y+=shot.vy*dt;shot.life-=dt;if(shot.life<=0)continue;if(window.ZONE_ONE_ITEM_EFFECTS?.customEnvironment(shot))continue;if(bossAlive()&&boss.handRest&&(window.ZONE_ONE_ITEM_EFFECTS?.canHit(shot,boss.handRest)??true)&&shotDistance(boss.handRest.x,boss.handRest.y,shot)<62+(shot.r||4)){const hand=boss.handRest;ZONE_ONE_ITEM_EFFECTS.hitCustom(shot,boss,damageBoss,true);ZONE_ONE_ITEM_EFFECTS.finishHit(shot,hand);continue}const enemy=summons.find(item=>item.hp>0&&(window.ZONE_ONE_ITEM_EFFECTS?.canHit(shot,item)??true)&&shotDistance(item.x,item.y,shot)<item.r+(shot.r||4));if(enemy){ZONE_ONE_ITEM_EFFECTS.hitCustom(shot,enemy,amount=>damageSummon(enemy,amount));ZONE_ONE_ITEM_EFFECTS.finishHit(shot,enemy);continue}if((window.ZONE_ONE_ITEM_EFFECTS?.canHit(shot,boss)??true)&&collectorSegmentHit(shot)){ZONE_ONE_ITEM_EFFECTS.hitCustom(shot,boss,damageBoss,true);ZONE_ONE_ITEM_EFFECTS.finishHit(shot,boss);}}state.shots=state.shots.filter(shot=>shot.life>0&&shot.x>25&&shot.x<W-25&&shot.y>25&&shot.y<H-25)}
 function updatePlayerVisualTimers(p,dt){p.shieldBreakTime=Math.max(0,(p.shieldBreakTime||0)-dt);p.hurtPoseTime=Math.max(0,(p.hurtPoseTime||0)-dt);p.shotPulse=Math.max(0,(p.shotPulse||0)-dt*7);const hadPanic=p.panicTime>0;p.panicTime=Math.max(0,(p.panicTime||0)-dt);p.activeReadyFlash=Math.max(0,(p.activeReadyFlash||0)-dt);if(hadPanic&&p.panicTime===0)refresh()}
 function updatePlayer(dt){const p=state.player;updatePlayerVisualTimers(p,dt);p.inv=Math.max(0,(p.inv||0)-dt);p.fire=Math.max(0,(p.fire||0)-dt);const previousCooldown=p.cool;p.cool=Math.max(0,(p.cool||0)-dt);if(previousCooldown>0&&p.cool===0){p.activeReadyFlash=1.2;soundSfx('activeReady')}p.dash=Math.max(0,(p.dash||0)-dt);const ix=Number(keys.has('d'))-Number(keys.has('a'))+TOUCH.move.x,iy=Number(keys.has('s'))-Number(keys.has('w'))+TOUCH.move.y,length=Math.hypot(ix,iy)||1;if((keys.has(' ')||TOUCH.activeQueued)&&p.cool<=0)useEquippedActive(ix,iy);TOUCH.activeQueued=false;const dx=p.dash>0?(p.activeDashX??ix/length):ix/length,dy=p.dash>0?(p.activeDashY??iy/length):iy/length,moving=p.dash>0||ix||iy,travel=stats().speed*(p.dash>0?3.2:1)*dt,oldX=p.x,oldY=p.y;if(moving){p.x+=dx*travel;p.y+=dy*travel}const bounds=stage==='room'?tableBounds:{left:74,right:W-74,top:76,bottom:H-74};p.x=clamp(p.x,bounds.left+p.r,bounds.right-p.r);p.y=clamp(p.y,bounds.top+p.r,bounds.bottom-p.r);if(stage==='room'){const tx=p.x,ty=p.y,steps=Math.max(1,Math.ceil(Math.hypot(tx-oldX,ty-oldY)/5));p.x=oldX;p.y=oldY;for(let i=1;i<=steps;i++){const nx=oldX+(tx-oldX)*i/steps,ny=oldY+(ty-oldY)*i/steps,obstacles=(window.VOSS_GAMEPLAY?.airborne||window.CHARACTER_OUTFITS?.ghost)?[]:[...holes,...jars.filter(jar=>!jar.broken).map(jar=>({...jar,r:jar.r-5}))],canMove=(x,y)=>obstacles.every(o=>{const before=Math.hypot(p.x-o.x,p.y-o.y),after=Math.hypot(x-o.x,y-o.y);return after>=o.r+p.r||before<o.r+p.r&&after>before+.0001});if(canMove(nx,ny)){p.x=nx;p.y=ny}else if(canMove(nx,p.y))p.x=nx;else if(canMove(p.x,ny))p.y=ny}}if(!isLegacyMobileContent())p.stillTime=ix||iy?0:(p.stillTime||0)+dt;if(ix||iy)p.lastMoveAngle=Math.atan2(iy,ix);let ax=Number(keys.has('arrowright'))-Number(keys.has('arrowleft'))+TOUCH.aim.x,ay=Number(keys.has('arrowdown'))-Number(keys.has('arrowup'))+TOUCH.aim.y;if(mouse.down&&!ax&&!ay){const origin=playerAimOrigin();ax=mouse.x-origin.x;ay=mouse.y-origin.y}if(Math.hypot(ax,ay)>.1&&p.fire<=0){p.facing=Math.atan2(ay,ax);shootPlayer(p.facing);p.fire=stats().rate;soundSfx('shot')}updateShots(dt)}
 function arenaDoorChoice(range=120){if(Math.abs(state.player.x-W/2)>105)return null;if(state.player.y<76+range)return'forward';if(state.player.y>H-76-range)return'back';return null}
 function updateFight(dt){if(!active||state.mode!=='play'||state.paused||state.map)return;if(state.player.hp<=0){hideBossHud();endPlayerLife();return;}window.DODGE_ADDONS?.update(dt);if(state.mode!=='play')return;TRASH_BAG_SKILL?.updateDebris?.(dt);state.elapsed+=dt;state.toastTime=Math.max(0,state.toastTime-dt);screenShake=Math.max(0,screenShake-dt);if(screenShake<=0)shakePower=0;if(stage==='grab'){transition+=dt;const pull=clamp((transition-.65)/1.25,0,1);state.player.y=H/2+pull*520;if(transition>=1.9)enterRoom();return}if(stage==='release'){transition+=dt;state.player.x=W/2;state.player.y=transition<.9?575-carryEase((transition-.18)/.72)*780:H/2-(1-carryEase((transition-.9)/.65))*510;if(transition>=1.7){stage='cleared';Object.assign(state.player,{x:W/2,y:H/2,inv:1.5});notify('DE VUELTA EN LA FOSA · RECOGÉ LA VIDA Y LA XP');$('#radio-text').textContent='«Ya estás afuera. Las recompensas son reales y quedaron en el suelo.»';refresh()}return}updatePlayer(dt);if(state.mode!=='play'){hideBossHud();return}if(stage==='entrance'){if(Math.hypot(state.player.x-W/2,state.player.y-H/2)<185)startGrab();return}if(stage==='cleared'){updateBossRewards(dt);const door=arenaDoorChoice(58);if(door)finish(door);return}updateBoss(dt);if(bossAlive()&&boss.handRest){const h=boss.handRest;if(playerBodyTouches({x:h.x,y:h.y+5,r:40*(h.strong?1.35:1.05)}))hurt(1,h)}updateFalling(dt);updateSummons(dt);updateSpecimenDrops(dt);updateEnemyBullets(dt);updateHazards(dt);if(state.player.hp<=0){hideBossHud();endPlayerLife()}}
 function drawHand(x,y,side=1,closed=false,scale=1){ctx.save();ctx.translate(x,y);ctx.scale(side*scale,scale);ctx.fillStyle=boss?.flash>0?'#e6d5b5':'#bba17d';ctx.strokeStyle='#2a211d';ctx.lineWidth=6;ctx.beginPath();ctx.roundRect(-29,-19,58,51,18);ctx.fill();ctx.stroke();if(closed){for(let i=0;i<4;i++)ellipse(ctx,-18+i*12,-17,9,17,'#bba17d','#2a211d')}else for(let i=0;i<4;i++){ctx.beginPath();ctx.roundRect(-27+i*16,-57-(i%2)*8,12,47+(i%2)*8,7);ctx.fill();ctx.stroke()}ctx.restore()}
