 function drawHandShadow(x,y,r,weight=.2){const pulse=1+Math.sin(state.elapsed*7)*.012;ctx.save();ctx.translate(x,y+8);ctx.scale(pulse,pulse*.78);const gradient=ctx.createRadialGradient(0,0,r*.12,0,0,r);gradient.addColorStop(0,`rgba(10,7,5,${weight})`);gradient.addColorStop(.58,`rgba(12,8,6,${weight*.84})`);gradient.addColorStop(.88,`rgba(12,8,6,${weight*.28})`);gradient.addColorStop(1,'rgba(12,8,6,0)');ctx.fillStyle=gradient;ctx.beginPath();ctx.arc(0,0,r,0,Math.PI*2);ctx.fill();ctx.restore()}
