 function drawJarSpecimen(kind){const art=window.ZONE_ONE_ENEMY_ART;if(!art)return;const common={x:0,y:0,flash:0,phase:0,hp:20,max:20};let draw,enemy,scale=.34,offsetY=5;if(kind==='goblin'){draw=art.drawTrashGoblin;scale=.32;offsetY=6;enemy={...common,bagged:true,goblinFacing:0,goblinAttackFlash:0,goblinBagCrack:0,goblinBagHp:18,goblinBagMax:18}}else if(kind==='hungry'){draw=art.drawHungry;scale=.31;offsetY=4;enemy={...common,hungerPhase:'exposed',hungerAction:'walk',hungerTimer:0,hungerFacing:0,hungerTrail:[],hungerAir:0}}else if(kind==='mimic'){draw=art.drawBagMimic;scale=.31;offsetY=-1;enemy={...common,mimicGroundY:0,mimicPhase:'laugh',mimicVariant:1,mimicAngle:0,mimicJump:1}}else if(kind==='signal'){draw=art.drawSmallStopKid;scale=.31;offsetY=8;enemy={...common,stopFury:false,stopShield:0,stopShieldWindup:0,stopCombo:0,stopFatigue:0,stopFacing:0,stopPose:'walk',stopIndex:0,stopSwing:0,stopSwingDuration:1}}else{draw=art.drawBigKid;scale=.24;offsetY=11;enemy={...common,bigShield:0,bigShieldWindup:0,bigCombo:0,bigFacing:0,bigSwing:0,bigSwingDuration:1,bigShotFlash:0}}ctx.save();ctx.translate(0,offsetY);ctx.scale(scale,scale);draw(enemy);ctx.restore()}
