 function drawSummon(enemy){if(enemy.realZoneEnemy){ZONE_ONE_ENEMY_RUNTIME.draw(enemy);return}if(enemy.kind==='mimic'){ZONE_ONE_ENEMY_ART?.drawBagMimic(enemy);return}ctx.save();ctx.translate(enemy.x,enemy.y);const flash=enemy.flash>0?'#eee0bd':null;if(enemy.kind==='goblin'){ellipse(ctx,0,8,20,25,flash||'#718467','#263126');ctx.fillStyle='#718467';ctx.strokeStyle='#263126';ctx.lineWidth=4;ctx.beginPath();ctx.moveTo(9,-12);ctx.lineTo(34,-4);ctx.lineTo(10,2);ctx.closePath();ctx.fill();ctx.stroke();ellipse(ctx,-5,-7,4,5,'#e6d69a','#24251e')}else if(enemy.kind==='hungry'){ctx.strokeStyle=flash||'#9b8b70';ctx.lineWidth=7;ctx.beginPath();ctx.moveTo(0,-16);ctx.lineTo(0,22);ctx.moveTo(0,-8);ctx.lineTo(-20,9);ctx.moveTo(0,-8);ctx.lineTo(20,9);ctx.moveTo(0,20);ctx.lineTo(-14,38);ctx.moveTo(0,20);ctx.lineTo(14,38);ctx.stroke();ellipse(ctx,0,-27,19,18,'#1a1d18','#080908');ctx.strokeStyle='#a65f4d';ctx.lineWidth=3;ctx.beginPath();ctx.moveTo(-14,-21);ctx.lineTo(14,-21);ctx.stroke()}else if(enemy.kind==='signal'){ellipse(ctx,0,6,18,25,flash||'#7d7565','#28231f');ellipse(ctx,0,-22,18,18,'#1a1d18','#080908');ctx.fillStyle='#9d3f36';ctx.strokeStyle='#e4d4a4';ctx.lineWidth=3;ctx.beginPath();ctx.arc(23,4,15,0,Math.PI*2);ctx.fill();ctx.stroke()}else{ellipse(ctx,0,8,34,40,flash||'#786b5d','#251f1b');ellipse(ctx,0,-38,31,28,'#1a1d18','#080908');ctx.fillStyle='#9d3f36';ctx.fillRect(-19,-4,38,10)}ctx.restore()}
 function drawFalling(){for(const bag of falling){ctx.save();ctx.globalAlpha=bag.landed?clamp(bag.life/.65,0,1):1;ZONE_ONE_ENEMY_ART?.drawBagMimic({x:bag.x,y:bag.y,mimicGroundY:bag.targetY,mimicPhase:'jump',mimicVariant:bag.variant,mimicAngle:bag.rotation,mimicJump:0});ctx.restore()}}
 function drawTrashDrops(){for(const pile of trashDrops){ctx.save();ctx.translate(pile.x,pile.y);ctx.rotate(pile.rotation);ctx.globalAlpha=clamp(pile.life,0,1);ellipse(ctx,0,4,pile.r,pile.r*.48,'#302b23','#17130f');ctx.fillStyle='#73543b';ctx.fillRect(-pile.r*.55,-4,9,8);ctx.fillStyle='#6f7a6d';ctx.beginPath();ctx.arc(4,-4,6,0,Math.PI*2);ctx.fill();ctx.strokeStyle='#ab8c5e';ctx.lineWidth=3;ctx.beginPath();ctx.moveTo(8,2);ctx.lineTo(pile.r*.65,-7);ctx.stroke();ctx.restore()}}
 function drawHazards(){for(const item of hazards){ctx.save();ctx.translate(item.x,item.y);ctx.rotate(item.rotation);ctx.shadowColor='#f09b55';ctx.shadowBlur=9;ellipse(ctx,0,0,item.r,item.r,'#8b6844','#f0a05c');ctx.restore()}}
 function drawHands(){if(!boss||boss.dead)return;const left={x:380,y:247,side:-1},right={x:W-380,y:247,side:1};if(boss.state==='stunned'){if(boss.handRest)drawHand(boss.handRest.x,boss.handRest.y,boss.handRest.side,true,boss.handRest.strong?1.35:1.05);else{drawHand(left.x,260,-1,false,.9);drawHand(right.x,260,1,false,.9)}return}if(boss.state==='ceilingWindup'||boss.state==='ceilingAssault'){const raised=boss.ceilingSide<0?left:right,other=boss.ceilingSide<0?right:left;drawHand(raised.x,85,raised.side,true,1.1);if(boss.handRest)drawHand(boss.handRest.x,boss.handRest.y,boss.handRest.side,true,1.05);else if(['tracking','locked'].includes(boss.assaultPhase)){const drop=boss.assaultPhase==='locked'?clamp(1-boss.handTimer/HAND_LOCK,0,1):0;drawHand(boss.targetX,boss.targetY-105+drop*30,other.side,true,1.05)}else drawHand(other.x,other.y,other.side,false);return}if(boss.state==='fistWarning'||boss.state==='fistImpact'){const progress=boss.state==='fistImpact'?clamp(1-boss.timer/FIST_DESCENT,0,1):0;drawHand(left.x,left.y,-1,false);drawHand(boss.targetX,boss.targetY-190+progress*150,1,true,1.35);return}if(boss.handRest)drawHand(boss.handRest.x,boss.handRest.y,boss.handRest.side,true,1.05);if(boss.state==='altWarning'){const drop=boss.warningPhase==='locked'?clamp(1-boss.timer/HAND_LOCK,0,1):0;drawHand(boss.targetX,boss.targetY-105+drop*30,boss.altSide,true,1.05)}else if(!boss.handRest){drawHand(left.x,left.y,-1,false);drawHand(right.x,right.y,1,false)}}
 function drawWarnings(){drawAttackShadow()}
 function drawRoom(showPlayer=true){ctx.fillStyle='#100e0c';ctx.fillRect(0,0,W,H);drawBagWall();drawCollector();drawOldTable();drawWarnings();for(const hole of holes)drawHole(hole);drawTrashDrops();for(const jar of jars)drawJar(jar);drawHands();drawFalling();for(const enemy of summons)drawSummon(enemy);drawHazards();for(const bullet of state.bullets)drawHostileBullet(bullet);for(const drop of specimenDrops)drawRecoveryPickup(drop,state.elapsed,state.player);for(const shot of state.shots)drawPlayerProjectile(shot);if(showPlayer)drawMoho();drawActiveReadyCue();if(boss?.dead){ctx.fillStyle='#d6e9ad';ctx.font='bold 15px monospace';ctx.textAlign='center';ctx.fillText('RECOLECTOR DERROTADO · TE DEVUELVE A LA FOSA',W/2,H-38)}}
 function carryEase(value){const t=clamp(value,0,1);return t*t*(3-2*t)}
 // The transport hand keeps the Collector's flat cartoon palette and jointed fingers.
 function drawCarryHand(x,y,grip,tilt=0,foreground=false){
  ctx.save();ctx.translate(x,y);ctx.rotate(tilt);ctx.lineCap='round';ctx.lineJoin='round';ctx.fillStyle='#bba17d';ctx.strokeStyle='#2a211d';ctx.lineWidth=6;
  if(!foreground){
   ctx.beginPath();ctx.moveTo(-29,105);ctx.quadraticCurveTo(-24,71,-43,51);ctx.bezierCurveTo(-68,32,-70,-14,-57,-49);ctx.quadraticCurveTo(-40,-70,-13,-65);ctx.quadraticCurveTo(20,-75,48,-57);ctx.bezierCurveTo(68,-32,69,26,40,53);ctx.quadraticCurveTo(24,74,28,105);ctx.closePath();ctx.fill();ctx.stroke();
   for(let i=0;i<4;i++){const stagger=carryEase((grip-i*.065)/.8),length=[65,85,79,56][i];ctx.save();ctx.translate(-45+i*29,-49);ctx.rotate((i-1.5)*(.13-stagger*.07));ctx.beginPath();ctx.moveTo(-12,8);ctx.quadraticCurveTo(-16,-length*.45,-11,-length*(1-stagger*.9));ctx.quadraticCurveTo(1,-length*(1-stagger*.9)-19,13,-length*(1-stagger*.9));ctx.quadraticCurveTo(18,-length*.35,13,9);ctx.closePath();ctx.fill();ctx.stroke();ctx.restore()}
   ctx.strokeStyle='#927654';ctx.lineWidth=3;ctx.beginPath();ctx.moveTo(-34,38);ctx.quadraticCurveTo(-2,49,29,37);ctx.stroke()
  }else{
   if(grip>.25){const fold=carryEase((grip-.25)/.75);for(const side of[-1,1]){ctx.save();ctx.translate(side*(60-fold*17),-28+fold*9);ctx.rotate(-side*fold*.55);for(let i=0;i<2;i++){ctx.beginPath();ctx.roundRect(-13+i*3,-14+i*20,27,31,13);ctx.fill();ctx.stroke()}ctx.restore()}}
   ctx.beginPath();ctx.moveTo(-57,-16);ctx.bezierCurveTo(-82,-9,-75,18,-57,22);ctx.quadraticCurveTo(-41,28,-24+grip*17,8);ctx.quadraticCurveTo(-11+grip*15,-3,-24,-10);ctx.quadraticCurveTo(-39,-19,-57,-16);ctx.closePath();ctx.fill();ctx.stroke()
  }
  ctx.restore()
 }
 function drawGrab(){
  drawEntranceFloor();const approach=carryEase(transition/.65),pull=clamp((transition-.65)/1.25,0,1),x=W/2,y=pull>0?state.player.y+3:-130+approach*565,grip=carryEase((transition-.4)/.38),tilt=.08-Math.sin(approach*Math.PI)*.1;
  drawCarryHand(x,y,grip,tilt);drawMoho();drawCarryHand(x,y,grip,tilt,true);drawActiveReadyCue()
 }
