 const baseAction=interactAction;interactAction=function(){if(active){if(stage==='cleared'){const door=arenaDoorChoice();if(door){finish(door);return}notify('Acercate a la puerta norte para seguir o a la puerta sur para volver.');return}notify(boss?.dead?'El Recolector te está devolviendo a la fosa.':'El Recolector sigue observando.');return}return baseAction()};
 const basePause=showPauseMenu;showPauseMenu=function(){basePause();const controls=document.querySelector('.boss-test-controls');if(controls&&!document.querySelector('#pause-test-collector')){const button=document.createElement('button');button.id='pause-test-collector';button.textContent='Probar Recolector →';button.onclick=()=>{state.paused=false;start({direct:true})};controls.appendChild(button)}};
 const baseRestart=restartCurrentLevel;restartCurrentLevel=function(){if(active){active=false;hideBossHud();start(context||{direct:true});return}return baseRestart()};
