 const baseReset=reset;reset=function(){active=false;hideBossHud();return baseReset()};
 const routeGoRoom=goRoom;
 window.COLLECTOR_MINIBOSS=Object.freeze({start,finish,get bounds(){return stage==='room'?{...tableBounds}:{left:74,right:W-74,top:76,bottom:H-74}},get recoveryPickups(){return stage==='room'?specimenDrops:bossRewards},drawBestiary(x,y){const old=boss;ctx.save();try{boss={...freshBoss(),x:0,y:0};ctx.translate(x,y);ctx.scale(.34,.34);drawCollector()}finally{boss=old;ctx.restore()}},visitOutfitTargets(visit){if(boss&&!boss.dead)visit(boss);for(const e of summons)if(e.hp>0&&!e.dead)visit(e);},visitDamageTargets(visit){for(const enemy of summons)if(enemy.hp>0)visit(enemy,amount=>damageSummon(enemy,amount),false);if(bossAlive())visit(boss,damageBoss,true)},hitArea(x,y,r,amount){for(const enemy of summons)if(enemy.hp>0&&Math.hypot(enemy.x-x,enemy.y-y)<=r+enemy.r)damageSummon(enemy,amount);if(bossAlive()&&(collectorBodyHit(x,y,r)||boss.handRest&&Math.hypot(boss.handRest.x-x,boss.handRest.y-y)<=r+62))damageBoss(amount)},advance(seconds=.5){for(let left=Math.max(0,seconds);left>0;left-=Math.min(left,1/60))updateFight(Math.min(left,1/60));return this.snapshot},damage(amount){return damageBoss(amount)},get active(){return active},get floorKind(){return stage==='entrance'||stage==='cleared'?'trash':stage==='room'?'table':'transition'},get snapshot(){return{stage,boss:boss?{...boss}:null,jars:jars.map(jar=>({...jar})),holes:holes.map(hole=>({...hole})),summons:summons.map(enemy=>({...enemy})),falling:falling.length,mimicGarbageBursts,trashDrops:trashDrops.map(pile=>({...pile})),specimenDrops:specimenDrops.map(drop=>({...drop})),bossRewards:bossRewards.map(drop=>({...drop})),dropChances:{heal:HEAL_DROP_CHANCE,xp:XP_DROP_CHANCE},screenShake,shakePower,arena:{width:W,height:H}}}});
