 function updateDanger(dt){for(const item of danger){item.x+=item.vx*dt;item.y+=item.vy*dt;item.life-=dt;item.arming=Math.max(0,(item.arming||0)-dt);item.rotation+=dt*7;if(item.arming>0)continue;const enemy=minions.find(enemy=>!enemy.dead&&Math.hypot(item.x-enemy.x,item.y-enemy.y)<item.r+enemy.r);if(enemy){damageMinion(enemy,24);item.life=0}else if(item.life>0&&Math.hypot(item.x-state.player.x,item.y-state.player.y)<item.r+state.player.r){hurt(1,item);item.life=0}}danger=danger.filter(item=>item.life>0&&item.x>25&&item.x<W-25&&item.y>25&&item.y<H-25)}
 function organFire(organ){const angle=Math.atan2(state.player.y-organ.y,state.player.x-organ.x),spreads=organ.type==='bone'?[-.16,0,.16]:[0],speed=(organ.type==='bone'?265:195)*PROJECTILE_SPEED;for(const spread of spreads)interior.projectiles.push({x:organ.x,y:organ.y,vx:Math.cos(angle+spread)*speed,vy:Math.sin(angle+spread)*speed,r:organ.type==='bone'?9:12,type:organ.type,source:'organ',rotation:angle+spread,life:4})}
 function nextHeartAttack(heart){if(!heart.attackDeck.length){heart.attackDeck=['volley','volley','slam'];for(let i=heart.attackDeck.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[heart.attackDeck[i],heart.attackDeck[j]]=[heart.attackDeck[j],heart.attackDeck[i]]}}return heart.attackDeck.shift()}
 function fireHeartVolley(room,heart){const pattern=heart.volleyPattern++%2;if(!pattern){const count=7,start=.24,step=(Math.PI-.48)/(count-1);for(let i=0;i<count;i++){const angle=start+i*step;room.projectiles.push({x:heart.x,y:heart.y+55,vx:Math.cos(angle)*205*PROJECTILE_SPEED,vy:Math.sin(angle)*205*PROJECTILE_SPEED,r:12,type:'blood',source:'heart',rotation:angle,life:4})}}else{const aimed=Math.atan2(state.player.y-(heart.y+45),state.player.x-heart.x);for(const spread of[-.84,-.42,0,.42,.84]){const angle=aimed+spread;room.projectiles.push({x:heart.x,y:heart.y+55,vx:Math.cos(angle)*230*PROJECTILE_SPEED,vy:Math.sin(angle)*230*PROJECTILE_SPEED,r:11,type:'blood',source:'heart',rotation:angle,life:4})}}heart.pulse=.24;soundSfx('warning')}
 function spawnBodyPart(room){const types=['bone','organ','flesh','blood'],type=types[Math.floor(Math.random()*types.length)],sizes={bone:13,organ:22,flesh:18,blood:14},x=125+Math.random()*710;room.bodyParts.push({x,y:35-Math.random()*80,vx:(Math.random()-.5)*45,vy:245+Math.random()*110,r:sizes[type],type,rotation:Math.random()*Math.PI*2,spin:(Math.random()-.5)*8,life:4})}
 function fireWallOrgan(room,organ){const angle=Math.atan2(state.player.y-organ.y,state.player.x-organ.x),spreads=organ.type==='bone'?[-.16,0,.16]:[0],speed=(organ.type==='bone'?265:195)*PROJECTILE_SPEED;for(const spread of spreads)room.projectiles.push({x:organ.x,y:organ.y,vx:Math.cos(angle+spread)*speed,vy:Math.sin(angle+spread)*speed,r:organ.type==='bone'?9:12,type:organ.type,source:'wallOrgan',rotation:angle+spread,life:4});soundSfx('shot')}
 function updateWallOrgan(room,dt,heartRoom){dt*=window.TRAINING_COLISEUM?.enemyTempo||1;if(!heartRoom){room.wallOrgan=null;room.wallOrganCool=2.2;return}const organ=room.wallOrgan;if(!organ){room.wallOrganCool-=dt;if(room.wallOrganCool<=0){const left=Math.random()<.5;room.wallOrgan={x:left?93:IW-93,y:235+Math.random()*125,type:room.wallOrganType,state:'appear',timer:.55,alpha:0,phase:Math.random()*6,shots:0};room.wallOrganType=room.wallOrganType==='bone'?'blood':'bone';room.wallOrganCool=4+Math.random()*2}return}organ.timer-=dt;organ.firedFlash=Math.max(0,(organ.firedFlash||0)-dt);if(organ.state==='appear'){organ.alpha=clamp(1-organ.timer/.55,0,1);if(organ.timer<=0){organ.state='aim';organ.timer=organ.type==='bone'?1.65:1.0;organ.windup=organ.timer}}else if(organ.state==='aim'){organ.alpha=1;if(organ.timer<=0){fireWallOrgan(room,organ);organ.firedFlash=.22;organ.shots=1;if(organ.type==='blood'){organ.state='burst';organ.timer=.5}else{organ.state='vanish';organ.timer=.55}}}else if(organ.state==='burst'){organ.alpha=1;if(organ.timer<=0){fireWallOrgan(room,organ);organ.firedFlash=.22;organ.shots++;if(organ.shots>=3){organ.state='vanish';organ.timer=.55}else organ.timer=.5}}else{organ.alpha=clamp(organ.timer/.55,0,1);if(organ.timer<=0)room.wallOrgan=null}}
 function updateHeartAttacks(room,dt,heartRoom){if(window.CHARACTER_OUTFITS?.confused(room.heart))return;dt*=window.TRAINING_COLISEUM?.enemyTempo||1;const heart=room.heart;heart.pulse=Math.max(0,heart.pulse-dt);heart.slamOffset=Math.max(0,heart.slamOffset-dt*270);if(!heartRoom){heart.state='idle';heart.timer=0;return}if(heart.state==='slamWindup'){heart.timer-=dt;heart.slamOffset=110*clamp(1-heart.timer/.8,0,1);if(heart.timer<=0){heart.state='bodyRain';heart.timer=3.4;heart.rainCool=0;heart.slamOffset=110;screenShake=.75;shakePower=16;soundSfx('break');notify('EL CORAZÓN GOLPEA · CAEN RESTOS DEL CUERPO')}return}if(heart.state==='bodyRain'){heart.timer-=dt;heart.rainCool-=dt;while(heart.rainCool<=0){spawnBodyPart(room);heart.rainCool+=.2+Math.random()*.12}if(heart.timer<=0){heart.state='idle';heart.cool=2.8}return}heart.cool-=dt;if(heart.cool>0)return;const attack=nextHeartAttack(heart);if(attack==='slam'){heart.state='slamWindup';heart.timer=.8;heart.pulse=.35;soundSfx('warning')}else{fireHeartVolley(room,heart);heart.cool=2.8}}
 function damageInteriorOrgan(organ,amount){if(organ.dead)return 0;const dealt=Math.min(organ.hp,Math.max(0,amount));organ.hp-=dealt;if(organ.hp<=0){organ.dead=true;if(!isMobileGame())window.ENEMY_SKINS?.drop({...organ,type:organ.type==='blood'?'dumpBloodOrgan':'dumpBoneOrgan'},interior.materialDrops||=[]);window.BUNKER_COLLECTIONS?.recordDefeat(organ.type==='blood'?'dumpBloodOrgan':'dumpBoneOrgan');burst(organ.x,organ.y,'#8f3340',20);soundSfx('break')}return dealt}
