 function updateInterior(dt){const room=interior,p=state.player,radius=interiorPlayerRadius();updateVisualTimers(p,dt);p.inv=Math.max(0,(p.inv||0)-dt);p.fire=Math.max(0,(p.fire||0)-dt);const move=clamp(Number(keys.has('d'))-Number(keys.has('a'))+TOUCH.move.x,-1,1),jump=keys.has('w')||TOUCH.move.y<-.55;p.x=clamp(p.x+move*285*dt,72+radius,IW-72-radius);if(window.CHARACTER_OUTFITS?.ghost){const vertical=clamp(Number(keys.has('s'))-Number(keys.has('w'))+TOUCH.move.y,-1,1);p.y=clamp(p.y+vertical*285*dt,20+radius,IH-60-radius);room.vy=0;room.onGround=false;room.jumpLock=false;if(p.y+radius<=room.platforms.at(-1).y+8)room.heartReached=true}else{if(jump&&!room.jumpLock&&room.onGround){room.vy=-610;room.onGround=false;soundSfx('dash')}room.jumpLock=jump;const oldY=p.y;room.vy=Math.min(720,room.vy+1280*dt);p.y+=room.vy*dt;room.onGround=false;if(room.vy>=0)for(const platform of room.platforms)if(oldY+radius<=platform.y+5&&p.y+radius>=platform.y&&p.x+radius>platform.x&&p.x-radius<platform.x+platform.w){p.y=platform.y-radius;room.vy=0;room.onGround=true;if(platform===room.platforms.at(-1))room.heartReached=true;break}if(p.y>IH-45){p.y=1815;room.vy=0;hurt(1,p)}}if(!isLegacyMobileContent())p.stillTime=move?0:(p.stillTime||0)+dt;p.anim=p.anim||{move:0,phase:0,lean:0};p.anim.move=Math.abs(move);p.anim.phase+=Math.abs(move)*dt*8;p.anim.lean=move;let ax=Number(keys.has('arrowright'))-Number(keys.has('arrowleft'))+TOUCH.aim.x,ay=Number(keys.has('arrowdown'))-Number(keys.has('arrowup'))+TOUCH.aim.y;if(mouse.down&&!ax&&!ay){const origin=playerAimOrigin();ax=mouse.x-origin.x;ay=mouse.y-origin.y}if(Math.hypot(ax,ay)>.1&&p.fire<=0){p.facing=Math.atan2(ay,ax);shootPlayer(p.facing);p.fire=stats().rate;soundSfx('shot')}for(const shot of [...state.shots]){shot.previousX=shot.x;shot.previousY=shot.y;shot.x+=shot.vx*dt;shot.y+=shot.vy*dt;shot.life-=dt;if(shot.life<=0)continue;if(window.ZONE_ONE_ITEM_EFFECTS?.customEnvironment(shot))continue;const organ=room.organs.find(organ=>!organ.dead&&(window.ZONE_ONE_ITEM_EFFECTS?.canHit(shot,organ)??true)&&Math.hypot(shot.x-organ.x,shot.y-organ.y)<organ.r+(shot.r||5));if(organ){ZONE_ONE_ITEM_EFFECTS.hitCustom(shot,organ,amount=>damageInteriorOrgan(organ,amount));ZONE_ONE_ITEM_EFFECTS.finishHit(shot,organ);continue}const heart=room.heart,dx=(shot.x-heart.x)/heart.rx,dy=(shot.y-heart.y-heart.slamOffset)/heart.ry;if((window.ZONE_ONE_ITEM_EFFECTS?.canHit(shot,heart)??true)&&dx*dx+dy*dy<1){ZONE_ONE_ITEM_EFFECTS.hitCustom(shot,heart,damageHeart,true);ZONE_ONE_ITEM_EFFECTS.finishHit(shot,heart);}}state.shots=state.shots.filter(shot=>shot.life>0&&shot.x>45&&shot.x<IW-45&&shot.y>20&&shot.y<IH);if(stage!=='interior')return;const heartRoom=isLegacyMobileContent()?p.y<650:room.heartReached;if(isLegacyMobileContent()&&heartRoom)room.projectiles=room.projectiles.filter(shot=>shot.source!=='organ');for(const organ of room.organs){if(organ.dead||window.CHARACTER_OUTFITS?.confused(organ))continue;organ.cool-=dt;if(!heartRoom&&organ.cool<=0&&Math.abs(organ.y-p.y)<460){organFire(organ);organ.cool=organ.type==='bone'?2.25:1.7}}updateHeartAttacks(room,dt,heartRoom);updateWallOrgan(room,dt,heartRoom);for(const shot of room.projectiles){shot.x+=shot.vx*dt;shot.y+=shot.vy*dt;shot.rotation+=dt*5;shot.life-=dt;if(shot.life>0&&Math.hypot(shot.x-p.x,shot.y-p.y)<shot.r+radius){hurt(1,shot);shot.life=0}}room.projectiles=room.projectiles.filter(shot=>shot.life>0&&shot.x>35&&shot.x<IW-35&&shot.y>20&&shot.y<IH);for(const part of room.bodyParts){part.x+=part.vx*dt;part.y+=part.vy*dt;part.vy+=145*dt;part.rotation+=part.spin*dt;part.life-=dt;if(part.life>0&&Math.hypot(part.x-p.x,part.y-p.y)<part.r+radius){hurt(1,part);part.life=0}else if(part.y>445)part.life=0}room.bodyParts=room.bodyParts.filter(part=>part.life>0);room.cameraY+=(clamp(p.y,330,IH-330)-room.cameraY)*.13}
 function updateFight(dt){if(!active||state.mode!=='play'||state.paused||state.map)return;if(state.player.hp<=0){hideBossHud();endPlayerLife();return;}window.DODGE_ADDONS?.update(dt);if(state.mode!=='play')return;state.elapsed+=dt;state.toastTime=Math.max(0,state.toastTime-dt);screenShake=Math.max(0,screenShake-dt);if(screenShake<=0)shakePower=0;if(stage==='interior'){updateInterior(dt);if(state.player.hp<=0){hideBossHud();endPlayerLife()}return}updatePlayer(dt);if(state.mode!=='play'){hideBossHud();return}if(stage==='betrayal'){cinema+=dt;if(cinema>=3)beginBattle()}else if(stage==='battle'){if(boss.state==='heartEntry'&&Math.hypot(state.player.x-boss.x,state.player.y-385)<92){enterInterior();return}updateBoss(dt);if(state.mode!=='play'){hideBossHud();return}updateMinions(dt);if(state.mode!=='play'){hideBossHud();return}updateDanger(dt)}else if(stage==='defeated'){scrapyReturn+=dt;if(!isMobileGame()&&boss.state==='lastMarch'){const u=clamp(scrapyReturn/2.1,0,1),ease=u*u*(3-2*u);boss.x=boss.deathFrom.x+(W/2-boss.deathFrom.x)*ease;boss.y=boss.deathFrom.y+(425-boss.deathFrom.y)*ease;if(u>=1){boss.state='falling';boss.deathFallAge=0;soundSfx('break')}}if(!isMobileGame()&&boss.state==='falling'){boss.deathFallAge+=dt;if(boss.deathFallAge>=1.25){boss.state='collapsed';screenShake=.6;shakePower=12;soundSfx('break')}}scrapySpeech=Math.max(0,scrapySpeech-dt);if(scrapyReturn>(isMobileGame()?(isLegacyMobileContent()?.85:1.15):3.8)&&!scrapyEncouraged){scrapyEncouraged=true;speakReturnedScrapy()}if(state.player.y<90&&Math.abs(state.player.x-W/2)<92){finish();return}}updateRecoveryDrops();for(const button of buttons)button.flash=Math.max(0,button.flash-dt);if(state.player.hp<=0){hideBossHud();endPlayerLife()}}
 function floorBag(x,y,w=72,h=50,tone=0){ctx.save();ctx.translate(x,y);ctx.fillStyle=['#0c100d','#151914','#20221c','#101411'][tone%4];ctx.strokeStyle='#040605';ctx.lineWidth=3;ctx.beginPath();ctx.moveTo(-w*.45,h*.1);ctx.quadraticCurveTo(-w*.42,-h*.42,-w*.08,-h*.45);ctx.quadraticCurveTo(w*.38,-h*.5,w*.47,h*.08);ctx.quadraticCurveTo(w*.32,h*.48,-w*.28,h*.43);ctx.closePath();ctx.fill();ctx.stroke();ctx.strokeStyle='#56605677';ctx.lineWidth=1.5;ctx.beginPath();ctx.moveTo(-w*.27,-h*.05);ctx.quadraticCurveTo(0,-h*.24,w*.24,-h*.04);ctx.stroke();ctx.restore()}
 function drawCemeteryApproach(){ctx.fillStyle='#263b46';ctx.fillRect(0,0,W,92);ctx.fillStyle='#334d55';for(let i=0;i<18;i++){ctx.fillRect(i*103,16+(i%3)*9,54,10);ctx.fillStyle=i%2?'#415a60':'#334d55'}ctx.fillStyle='#8a9690';for(let i=0;i<9;i++){const x=260+i*155;ctx.fillRect(x,37,18,42);ctx.beginPath();ctx.arc(x+9,37,9,Math.PI,0);ctx.fill()}ctx.fillStyle='#c0d3d0';ctx.font='bold 11px monospace';ctx.textAlign='center';ctx.fillText('CAMINO AL CEMENTERIO',W/2,31)}
 function drawCliffs(){ctx.fillStyle='#020708';ctx.fillRect(0,92,W,142);const gradient=ctx.createLinearGradient(0,92,0,234);gradient.addColorStop(0,'#152a31');gradient.addColorStop(1,'#030708');ctx.fillStyle=gradient;ctx.fillRect(0,92,W,142);ctx.strokeStyle='#758077';ctx.lineWidth=9;ctx.beginPath();ctx.moveTo(0,226);for(let x=0;x<=W;x+=70)ctx.lineTo(x,219+(x/70%2)*12);ctx.stroke();ctx.fillStyle='#061012';ctx.fillRect(0,234,bounds.left-16,H-234);ctx.fillRect(bounds.right+16,234,W-bounds.right-16,H-234);ctx.strokeStyle='#66736c';ctx.lineWidth=8;ctx.beginPath();ctx.moveTo(bounds.left,228);ctx.lineTo(bounds.left,H);ctx.moveTo(bounds.right,228);ctx.lineTo(bounds.right,H);ctx.stroke()}
 function drawBridge(){const count=buttons.filter(button=>button.active).length,full=stage==='defeated',failed=stage==='betrayal'||stage==='battle';ctx.save();if(full||count&&!failed){const bottom=232,top=full?76:166;ctx.fillStyle='#655445';ctx.strokeStyle='#24221e';ctx.lineWidth=6;ctx.fillRect(W/2-74,top,148,bottom-top);ctx.strokeRect(W/2-74,top,148,bottom-top);ctx.strokeStyle='#a38b62';ctx.lineWidth=4;for(let y=top+14;y<bottom;y+=22){ctx.beginPath();ctx.moveTo(W/2-67,y);ctx.lineTo(W/2+67,y);ctx.stroke()}}if(failed){ctx.strokeStyle='#91654b';ctx.lineWidth=8;ctx.beginPath();ctx.moveTo(W/2-70,226);ctx.lineTo(W/2-25,189+Math.sin(cinema*12)*6);ctx.moveTo(W/2+70,226);ctx.lineTo(W/2+31,195-Math.sin(cinema*11)*5);ctx.stroke()}ctx.restore()}
 function drawButton(button,index){if(!isMobileGame()){ctx.save();ctx.translate(button.x,button.y);ctx.scale(1.25,1.25);DUMP_PUZZLE_ART.receiver(0,0,{color:index?'green':'yellow',lit:button.active,label:'BASURA'});ctx.restore();return}const pulse=.5+.5*Math.sin(state.elapsed*7+index);ctx.save();ctx.translate(button.x,button.y);ellipse(ctx,0,18,55,15,'#02030399');ctx.fillStyle=button.active?'#75965d':'#61463b';ctx.strokeStyle=button.flash>0?'#fff0a4':'#b59b68';ctx.lineWidth=6;ctx.beginPath();ctx.roundRect(-47,-35,94,70,16);ctx.fill();ctx.stroke();ellipse(ctx,0,-3,button.r*.55,button.r*.55,button.active?'#b7de7e':'#8d3f36','#251d19');ctx.fillStyle='#efe3b5';ctx.font='bold 10px monospace';ctx.textAlign='center';ctx.fillText(`RECEPTOR ${index+1}${button.active?' · ACTIVO':''}`,0,56+pulse*2);ctx.restore()}
