 function drawThirdArm(x,y){ctx.lineCap='round';ctx.strokeStyle='#171310';ctx.lineWidth=80;ctx.beginPath();ctx.moveTo(boss.x,290);ctx.lineTo(x,y);ctx.stroke();ctx.strokeStyle='#76523f';ctx.lineWidth=55;ctx.stroke();for(let i=1;i<4;i++)ellipse(ctx,boss.x+(x-boss.x)*i/4,290+(y-290)*i/4,15,12,i%2?'#8a6548':'#4e5b48','#211b16');ellipse(ctx,x,y,64,54,'#79513e','#18130f');ctx.strokeStyle='#a77c58';ctx.lineWidth=12;for(const angle of[-1.05,-.52,0,.52,1.05]){ctx.beginPath();ctx.moveTo(x+Math.cos(angle)*48,y+Math.sin(angle)*42);ctx.lineTo(x+Math.cos(angle)*92,y+Math.sin(angle)*78);ctx.stroke()}}function drawBallPunch(){if(!trashBall)return;const ball=trashBall;if(ball.sweep>0){drawThirdArm(ball.x,ball.y);return}if(!ball.returning)return;const d=Math.hypot(ball.x-boss.x,ball.y-310);if(d>330)return;drawThirdArm(ball.x+(boss.x-ball.x)*.18,ball.y+(310-ball.y)*.18)}
 function drawTrashBall(){if(!trashBall)return;const ball=trashBall,v=ball.variant||0;ctx.save();ctx.translate(ball.x,ball.y);ctx.rotate(ball.rotation);ellipse(ctx,2,ball.r*.82,ball.r+15,16,'#02030388');if(!isMobileGame()){ctx.shadowColor='#fff3ac';ctx.shadowBlur=15}ctx.fillStyle=['#20241c','#2d2920','#1b2825','#29231f'][v];ctx.strokeStyle=isMobileGame()?'#090c09':'#f3e9ae';ctx.lineWidth=isMobileGame()?8:4;ctx.beginPath();for(let i=0;i<20;i++){const angle=i*Math.PI/10,r=ball.r*(.82+.13*Math.sin(i*2.7+v*1.9)+.07*((i+v)%3));const x=Math.cos(angle)*r,y=Math.sin(angle)*r;(i?ctx.lineTo(x,y):ctx.moveTo(x,y))}ctx.closePath();ctx.fill();ctx.stroke();const palettes=[['#755239','#576258','#343126'],['#8a593e','#485d5b','#3c3328'],['#624634','#6f7363','#2d382f'],['#876343','#4f5f55','#4a332d']],items=[[[-42,-22,18,12],[15,-44,21,12],[39,11,16,18],[-18,34,25,10]],[[ -35,-35,24,14],[28,-31,17,21],[43,25,22,11],[-32,27,15,23]],[[0,-48,28,10],[-44,5,18,24],[36,-3,25,14],[5,39,20,18]],[[-39,-25,19,19],[18,-38,28,12],[45,12,14,26],[-12,39,28,13]]][v];for(let i=0;i<items.length;i++){const [x,y,w,h]=items[i];ctx.save();ctx.translate(x,y);ctx.rotate((i-v)*.28);ctx.fillStyle=palettes[v][i%3];ctx.strokeStyle='#121612';ctx.lineWidth=4;ctx.fillRect(-w/2,-h/2,w,h);ctx.strokeRect(-w/2,-h/2,w,h);ctx.restore()}for(let i=0;i<12;i++){const angle=i*.91+v,r=24+(i%4)*11;ellipse(ctx,Math.cos(angle)*r,Math.sin(angle)*r,7+i%3,5+i%2,palettes[v][i%3],'#111410')}if(v===1){ctx.save();ctx.translate(-4,5);ctx.rotate(-ball.rotation*.35);ctx.fillStyle='#5f4938';ctx.strokeStyle='#151714';ctx.lineWidth=4;ctx.beginPath();ctx.roundRect(-20,-18,40,34,7);ctx.fill();ctx.stroke();for(const x of[-8,8])ellipse(ctx,x,-6,5,6,'#d5c884','#171b18');ctx.fillStyle='#c29a55';ctx.fillRect(-11,7,22,5);ctx.restore()}else if(v===3){ctx.save();ctx.translate(4,8);ctx.rotate(-ball.rotation*.3);ctx.fillStyle='#161b17';ctx.strokeStyle='#77553d';ctx.lineWidth=5;ctx.beginPath();ctx.moveTo(-26,-20);ctx.quadraticCurveTo(0,-36,27,-18);ctx.lineTo(23,24);ctx.lineTo(-24,22);ctx.closePath();ctx.fill();ctx.stroke();for(const x of[-9,9])ellipse(ctx,x,-7,5,7,'#d3bf75','#1a1813');ctx.strokeStyle='#c6b08a';ctx.lineWidth=3;ctx.beginPath();ctx.moveTo(-13,10);ctx.lineTo(-6,16);ctx.lineTo(0,9);ctx.lineTo(7,16);ctx.lineTo(14,9);ctx.stroke();ctx.restore()}ctx.restore()}
 function drawWave(){if(!wave)return;const visible=[];for(const part of wave.parts)if(part.active){const last=visible[visible.length-1];if(last&&Math.abs(last.x-part.x)<1&&Math.abs(last.y1-part.y0)<2)last.y1=part.y1;else visible.push({...part})}for(const part of visible){ctx.save();ctx.translate(part.x,0);ctx.globalAlpha=.92;ctx.fillStyle='#151a16dd';ctx.strokeStyle='#99805a';ctx.lineWidth=6;ctx.beginPath();for(let y=part.y0;y<=part.y1;y+=26){const x=(Math.floor(y/26)%2)*24-wave.width/2;y===part.y0?ctx.moveTo(x,y):ctx.lineTo(x,y)}ctx.lineTo(-wave.width/2,part.y1);for(let y=part.y1;y>=part.y0;y-=26)ctx.lineTo(wave.width/2+(Math.floor(y/26)%2)*20,y);ctx.closePath();ctx.fill();ctx.stroke();const debris=Math.max(2,Math.floor((part.y1-part.y0)/38));for(let i=0;i<debris;i++){ctx.fillStyle=['#77583c','#687169','#34352e'][i%3];ctx.save();ctx.translate((i%4-1.5)*35,part.y0+12+(i*31)%Math.max(15,part.y1-part.y0-18));ctx.rotate(state.elapsed*(i%2?5:-5));ctx.fillRect(-12,-8,24,16);ctx.restore()}ctx.restore()}}
 function drawTitanCliffRim(){if(!bossVisible())return;ctx.save();if(!isMobileGame())ctx.translate(0,boss.y-150);ctx.fillStyle='#070b09';ctx.strokeStyle='#46524c';ctx.lineWidth=5;ctx.beginPath();ctx.moveTo(boss.x-370,314);for(let x=boss.x-370,i=0;x<=boss.x+370;x+=46,i++)ctx.lineTo(x,306+(i%3)*11);ctx.lineTo(boss.x+370,370);ctx.lineTo(boss.x-370,370);ctx.closePath();ctx.fill();ctx.stroke();for(let i=0;i<11;i++)ellipse(ctx,boss.x-325+i*65,340+(i%2)*8,42,24,i%3?'#111510':'#1c201a','#050705');ctx.restore()}
 function drawHeartEntrance(){if(boss?.state!=='heartEntry')return;const x=boss.x,y=boss.y+88;ctx.save();ctx.strokeStyle='#47151c';ctx.lineWidth=17;ctx.beginPath();ctx.moveTo(x-54,y+28);ctx.bezierCurveTo(x-70,y+70,x-52,y+101,x-27,y+127);ctx.moveTo(x+54,y+28);ctx.bezierCurveTo(x+70,y+70,x+52,y+101,x+27,y+127);ctx.stroke();ellipse(ctx,x,y,68,55,'#21080e','#6f2631');ellipse(ctx,x,y+5,48,36,'#090506','#351017');ctx.fillStyle='#d1b58e';for(let i=0;i<6;i++){const tx=x-43+i*17;ctx.beginPath();ctx.moveTo(tx,y-35);ctx.lineTo(tx+8,y-13);ctx.lineTo(tx+15,y-37);ctx.fill();ctx.beginPath();ctx.moveTo(tx,y+38);ctx.lineTo(tx+8,y+17);ctx.lineTo(tx+15,y+39);ctx.fill()}ctx.strokeStyle='#b83c4d';ctx.lineWidth=7;ctx.beginPath();ctx.moveTo(x,y+42);ctx.lineTo(x,y+122);ctx.stroke();ctx.fillStyle='#ead6b0';ctx.font='bold 12px monospace';ctx.textAlign='center';ctx.fillText('PECHO ABIERTO · ACERCATE',x,y+142);ctx.restore()}
 function drawInteriorPlatform(platform,index){ctx.save();ctx.fillStyle=index%2?'#5d292f':'#71323a';ctx.strokeStyle='#241014';ctx.lineWidth=7;ctx.beginPath();ctx.moveTo(platform.x,platform.y+7);for(let x=platform.x;x<=platform.x+platform.w;x+=26)ctx.lineTo(x,platform.y+Math.sin(x*.13+index)*7);ctx.lineTo(platform.x+platform.w,platform.y+platform.h);ctx.lineTo(platform.x,platform.y+platform.h);ctx.closePath();ctx.fill();ctx.stroke();for(let x=platform.x+16,i=0;x<platform.x+platform.w-8;x+=34,i++){ellipse(ctx,x,platform.y+3+(i%2)*3,18,12,i%3?'#8b4449':'#9b5550','#30161a');if((i+index)%3===0){ctx.strokeStyle='#c4ad8c';ctx.lineWidth=5;ctx.beginPath();ctx.moveTo(x,platform.y+13);ctx.lineTo(x+(i%2?8:-8),platform.y+30);ctx.stroke()}}ctx.restore()}
 function drawInteriorOrgan(organ){if(organ.dead)return;ctx.save();ctx.translate(organ.x,organ.y);const telegraph=organ.state==='aim'||organ.state==='burst',anticipation=telegraph?clamp(1-organ.timer/(organ.windup||.5),0,1):0,beat=1+Math.sin(state.elapsed*4+organ.phase)*.06+(telegraph?Math.sin(state.elapsed*9)*.009:0);ctx.scale(beat*(telegraph?1-anticipation*.012:1),beat);if(organ.type==='blood'){ctx.strokeStyle='#42131c';ctx.lineWidth=8;ctx.beginPath();ctx.moveTo(-4,-22);ctx.bezierCurveTo(-22,-54,10,-67,23,-88);ctx.stroke();ellipse(ctx,-19,1,33,43,'#67202d','#260d13');ellipse(ctx,20,5,37,47,'#8d2c3b','#260d13');ctx.strokeStyle='#ad4250';ctx.lineWidth=4;for(const x of[-29,-12,10,28]){ctx.beginPath();ctx.moveTo(x,-18);ctx.bezierCurveTo(x-12,3,x+10,25,x,42);ctx.stroke()}ellipse(ctx,0,18,7+anticipation*1.5,10+anticipation*2,organ.firedFlash>0?'#88413e':telegraph?'#4e2026':'#3a1118','#19080c');}else{ellipse(ctx,0,7,41,37,'#77504b','#251116');ctx.fillStyle='#c1ad8b';ctx.strokeStyle='#392a25';ctx.lineWidth=5;ctx.beginPath();ctx.moveTo(-34,6);ctx.quadraticCurveTo(-28,-34,0,-39);ctx.quadraticCurveTo(30,-35,35,6);ctx.lineTo(26,28);ctx.lineTo(11,36);ctx.lineTo(0,27);ctx.lineTo(-12,36);ctx.lineTo(-27,27);ctx.closePath();ctx.fill();ctx.stroke();for(const x of[-13,13]){ellipse(ctx,x,1,8,10,'#29151a','#5b4035');if(telegraph)ellipse(ctx,x+Math.sign(state.player.x-organ.x),2,1.5,2.4,organ.firedFlash>0?'#ae8a6c':'#8b715e')}ctx.fillStyle='#6f252e';ctx.beginPath();ctx.moveTo(-9,18);ctx.lineTo(0,10);ctx.lineTo(9,18);ctx.closePath();ctx.fill();ctx.strokeStyle='#d6c19d';ctx.lineWidth=8;for(const side of[-1,1]){ctx.beginPath();ctx.moveTo(side*31,24);ctx.lineTo(side*55,43);ctx.stroke();ellipse(ctx,side*58,45,8,8,'#d6c19d','#392a25')}}ctx.restore()}
 function drawWallOrgan(){const organ=interior.wallOrgan;if(!organ)return;ctx.save();ctx.globalAlpha=organ.alpha;drawInteriorOrgan({...organ,r:organ.type==='bone'?31:38,hp:1,max:1,dead:false});ctx.restore()}
 function drawBodyPart(part){ctx.save();ctx.translate(part.x,part.y);ctx.rotate(part.rotation);if(part.type==='bone'){ctx.fillStyle='#d1c19e';ctx.fillRect(-17,-5,34,10);ellipse(ctx,-17,0,8,8,'#d1c19e','#45362d');ellipse(ctx,17,0,8,8,'#d1c19e','#45362d')}else if(part.type==='organ'){ellipse(ctx,-8,0,15,22,'#762735','#260e14');ellipse(ctx,10,3,17,24,'#953343','#260e14');ctx.strokeStyle='#bc4e59';ctx.lineWidth=4;ctx.beginPath();ctx.moveTo(0,-18);ctx.lineTo(8,-32);ctx.stroke()}else if(part.type==='flesh'){ctx.fillStyle='#9a554f';ctx.strokeStyle='#35181a';ctx.lineWidth=5;ctx.beginPath();ctx.moveTo(-20,-13);ctx.lineTo(15,-18);ctx.lineTo(23,8);ctx.lineTo(-7,22);ctx.lineTo(-24,5);ctx.closePath();ctx.fill();ctx.stroke();ellipse(ctx,2,0,5,4,'#c57b6e')}else{ellipse(ctx,0,0,part.r,part.r,'#aa263e','#48121e');ellipse(ctx,-5,-5,4,3,'#d35a66')}ctx.restore()}
 function drawInteriorHeart(){const heart=interior.heart,pulse=1+Math.sin(state.elapsed*5)*.06+heart.pulse*.25;ctx.save();ctx.translate(heart.x,heart.y+heart.slamOffset);ctx.scale(pulse,pulse);ctx.strokeStyle='#3b1019';ctx.lineCap='round';for(const [x,w,c] of[[-62,22,'#7f2536'],[-25,18,'#a63a45'],[18,23,'#6e2132'],[59,17,'#96313f']]){ctx.lineWidth=w;ctx.beginPath();ctx.moveTo(x,-31);ctx.bezierCurveTo(x+(x<0?-35:35),-82,x*1.25,-118,x*1.45,-153);ctx.strokeStyle='#3b1019';ctx.stroke();ctx.lineWidth=w-7;ctx.strokeStyle=c;ctx.stroke()}ellipse(ctx,-41,-2,61,72,'#8d2035','#300d17');ellipse(ctx,41,1,62,73,'#aa2e42','#300d17');ctx.fillStyle='#98283c';ctx.strokeStyle='#300d17';ctx.lineWidth=8;ctx.beginPath();ctx.moveTo(-94,11);ctx.quadraticCurveTo(-52,89,0,129);ctx.quadraticCurveTo(59,83,95,10);ctx.closePath();ctx.fill();ctx.stroke();ctx.strokeStyle='#d05a62';ctx.lineWidth=5;for(let i=0;i<5;i++){ctx.beginPath();ctx.moveTo(-55+i*25,-31);ctx.bezierCurveTo(-76+i*28,15,-30+i*18,49,-22+i*12,76);ctx.stroke()}ellipse(ctx,-25,1,9,6,'#4b101b');ellipse(ctx,28,19,7,5,'#4b101b');ctx.restore()}
 function drawInteriorArena(){ctx.fillStyle='#13070b';ctx.fillRect(0,0,IW,IH);ctx.fillStyle='#3b151e';ctx.fillRect(70,0,IW-140,IH);for(let y=0;y<IH;y+=82){ellipse(ctx,35,y+35,70,58,y%164?'#4d292f':'#613039','#241317');ellipse(ctx,IW-35,y+60,70,62,y%164?'#613039':'#4d292f','#241317')}for(let i=0;i<28;i++){const x=105+(i*173)%750,y=42+(i*227)%1810,r=18+(i%4)*9;ellipse(ctx,x,y,r,r*.65,i%3?'#4a1c25':'#57222b','#2b1017');if(i%5===0)ellipse(ctx,x+7,y-2,5,4,'#967265','#32171c')}ctx.strokeStyle='#8b3444';ctx.lineWidth=9;for(let i=0;i<8;i++){ctx.beginPath();ctx.moveTo(i%2?65:IW-65,IH-i*245);ctx.bezierCurveTo(240,IH-i*270,720,IH-i*205,i%2?IW-70:70,IH-i*236);ctx.stroke()}ctx.strokeStyle='#b6a080';ctx.lineWidth=15;for(let y=120,i=0;y<IH-80;y+=190,i++){ctx.beginPath();ctx.moveTo(72,y);ctx.quadraticCurveTo(145,y-42+(i%2)*18,218,y+9);ctx.moveTo(IW-72,y+62);ctx.quadraticCurveTo(IW-145,y+18-(i%2)*17,IW-218,y+70);ctx.stroke()}for(const [index,platform] of interior.platforms.entries())drawInteriorPlatform(platform,index);ctx.fillStyle='#5c6d29';ctx.fillRect(70,1870,IW-140,30);for(let x=95;x<IW-80;x+=54)ellipse(ctx,x,1871+(x%3)*4,25,13,x%2?'#77843c':'#48551f','#20270e');for(const organ of interior.organs)drawInteriorOrgan(organ);drawWallOrgan();drawInteriorHeart();for(const d of interior.materialDrops||[])drawRecoveryPickup(d,state.elapsed,state.player);for(const part of interior.bodyParts)drawBodyPart(part);for(const shot of interior.projectiles){if(shot.type==='blood')ellipse(ctx,shot.x,shot.y,shot.r,shot.r,'#a3223b','#40121c');else{ctx.save();ctx.translate(shot.x,shot.y);ctx.rotate(shot.rotation);ctx.fillStyle='#d1c29e';ctx.fillRect(-14,-5,28,10);ellipse(ctx,-14,0,7,7,'#d1c29e');ellipse(ctx,14,0,7,7,'#d1c29e');ctx.restore()}}for(const shot of state.shots)drawPlayerProjectile(shot);ctx.save();const p=state.player,scale=interiorPlayerScale();ctx.translate(p.x,p.y+interiorPlayerOffset());ctx.scale(scale,scale);ctx.translate(-p.x,-p.y);drawMoho();drawActiveReadyCue();ctx.restore()}
 function drawInteriorScene(){const strength=screenShake>0?shakePower*clamp(screenShake/.5,0,1):0;drawCustomScene(drawInteriorArena,IW,IH,IW/2,interior.cameraY,650,'#10070a',Math.sin(state.elapsed*91)*strength,Math.cos(state.elapsed*73)*strength*.7)}
 function drawInteriorMap(c,w,h){c.save();c.setTransform(1,0,0,1,0,0);c.fillStyle='#160a0e';c.fillRect(0,0,w,h);c.fillStyle='#6b343d';c.fillRect(w*.38,18,w*.24,h-36);c.fillStyle='#bd3148';c.beginPath();c.arc(w/2,30,13,0,Math.PI*2);c.fill();c.fillStyle='#d7e1b2';c.beginPath();c.arc(w/2,h-18-(h-55)*((IH-state.player.y)/IH),7,0,Math.PI*2);c.fill();c.fillStyle='#ead4ba';c.font='bold 11px monospace';c.textAlign='center';c.fillText('ESTÓMAGO → CORAZÓN',w/2,h-4);c.restore()}
 function drawDanger(){for(const item of danger){ctx.save();ctx.translate(item.x,item.y);ctx.rotate(item.rotation);if(!isMobileGame()){ctx.shadowColor='#fff3ad';ctx.shadowBlur=9}ellipse(ctx,0,0,item.r,item.r,['#80603f','#69736a','#403c31','#a36a45','#c8bf9e'][item.variant],isMobileGame()?'#261f19':'#fff1b0');ctx.restore()}}
 function speakReturnedScrapy(){scrapySpeech=12;const lines=encouragement[scrapyTalkIndex++%encouragement.length];notify(`SCRAPY: «${lines.join(' ')}»`);$('#radio-text').textContent=`Scrapy: «${lines.join(' ')}»`;soundSfx('door')}
 function scrapyPose(){
  if(stage==='betrayal'){const u=clamp(cinema/1.7,0,1);return{x:W/2+650*u,y:265-Math.sin(u*Math.PI)*255-u*100,angle:u*5.8,visible:u<1,progress:u,phase:'airborne'}}
  if(stage==='defeated'){const u=clamp(scrapyReturn/1.1,0,1),ease=u*u*(3-2*u);return{...returnedScrapy,offsetY:(1-ease)*145,progress:u,phase:u<1?'emerging':'greeting',visible:scrapyReturn>0}}
  return{x:W/2,y:265,progress:1,phase:'waiting',visible:stage==='approach'};
 }
 function drawFlyingScrapy(){if(isLegacyMobileContent()||stage!=='betrayal')return;const p=scrapyPose();if(!p.visible)return;ctx.save();ctx.translate(p.x,p.y);ctx.rotate(p.angle);ctx.globalAlpha=clamp((1-p.progress)*5,0,1);SCRAPY_ACTOR?.draw(0,0,{label:false,wave:true});ctx.restore()}
 function drawReturnedScrapy(){
  if(stage!=='defeated')return;const friend=returnedScrapy;ctx.save();ctx.globalAlpha=clamp(scrapyReturn/.45,0,1);if(isLegacyMobileContent())SCRAPY_ACTOR?.draw(friend.x,friend.y,{label:true,wave:scrapySpeech>0});else{const p=scrapyPose();if(p.progress<1){ellipse(ctx,friend.x,friend.y+12,35,9,'#111a18aa');for(let i=0;i<6;i++){const a=i*Math.PI/3,d=20+p.progress*32;ellipse(ctx,friend.x+Math.cos(a)*d,friend.y+10-Math.sin(p.progress*Math.PI)*(8+i%2*7),3,2,'#8d8262')}}ctx.save();ctx.beginPath();ctx.rect(friend.x-110,friend.y-190,220,208);ctx.clip();ctx.translate(0,p.offsetY);SCRAPY_ACTOR?.draw(friend.x,friend.y,{label:p.progress===1,wave:true});ctx.restore()}
  if(scrapySpeech>0){const lines=encouragement[(scrapyTalkIndex+encouragement.length-1)%encouragement.length],x=friend.x-157,y=friend.y-185;ctx.fillStyle='#111a16f2';ctx.strokeStyle='#a99162';ctx.lineWidth=2.5;ctx.beginPath();ctx.roundRect(x,y,314,66,10);ctx.fill();ctx.stroke();ctx.fillStyle='#d6c792';ctx.font='bold 10px monospace';ctx.textAlign='left';ctx.fillText('SCRAPY',x+11,y+16);ctx.fillStyle='#eee2c3';ctx.font='10px monospace';lines.forEach((line,index)=>ctx.fillText(line,x+11,y+33+index*15))}ctx.restore()
 }
 function drawArena(){drawCemeteryApproach();drawCliffs();ctx.save();ctx.beginPath();ctx.rect(bounds.left,234,bounds.right-bounds.left,H-234);ctx.clip();ctx.scale(FIELD_ROOM_SCALE,FIELD_ROOM_SCALE);if(isLegacyMobileContent()){ DUMP_SCENERY.drawFloor(W/FIELD_ROOM_SCALE,H/FIELD_ROOM_SCALE);ctx.fillStyle='#2b2c2577';ctx.fillRect(bounds.left/FIELD_ROOM_SCALE,234/FIELD_ROOM_SCALE,(bounds.right-bounds.left)/FIELD_ROOM_SCALE,(H-234)/FIELD_ROOM_SCALE);}else DUMP_SCENERY.drawGround(W/FIELD_ROOM_SCALE,H/FIELD_ROOM_SCALE,0,{x:bounds.left/FIELD_ROOM_SCALE,y:234/FIELD_ROOM_SCALE,w:(bounds.right-bounds.left)/FIELD_ROOM_SCALE,h:(H-234)/FIELD_ROOM_SCALE});ctx.restore();drawBridge();if(stage==='approach')buttons.forEach(drawButton);if(stage==='approach'&&window.SCRAPY_ACTOR?.draw)SCRAPY_ACTOR.draw(W/2,265,{label:true,wave:true});if(!isMobileGame()&&stage==='defeated')drawTitanCliffRim();drawTitan();if(!isMobileGame()&&stage==='defeated'&&['falling','collapsed'].includes(boss.state)){const u=boss.state==='collapsed'?1:clamp(boss.deathFallAge/1.25,0,1);ctx.save();ctx.globalAlpha=u;for(let i=0;i<7;i++)floorBag(boss.x-225+i*75,boss.y+215+Math.sin(i*2)*8,80,34,i%3);ctx.restore()}drawFlyingScrapy();if(isMobileGame()||stage!=='defeated')drawTitanCliffRim();drawHeartEntrance();drawWave();drawPillars();drawDanger();for(const enemy of minions)drawClockwork(enemy);drawBallPunch();drawTrashBall();drawAttackFist();drawReturnedScrapy();for(const drop of recoveryDrops)drawRecoveryPickup(drop,state.elapsed,state.player);TRASH_BAG_SKILL?.drawZoneBags(false);for(const shot of state.shots)drawPlayerProjectile(shot);drawMoho();drawActiveReadyCue();TRASH_BAG_SKILL?.drawZoneBags(true);if(stage==='betrayal'&&window.FIRST_MEETINGS?.current?.id!=='colossus'){ctx.fillStyle='#e2d4aa';ctx.font='bold 18px monospace';ctx.textAlign='center';ctx.fillText(cinema<1?'EL PUENTE FALLÓ':'ALGO SUBE DEL ACANTILADO',W/2,430)}if(stage==='defeated'&&!isMobileGame()){ctx.save();ctx.strokeStyle='#d5e7ab';ctx.lineWidth=3;for(const side of[-1,1])for(let y=330;y<=750;y+=95){const x=W/2+side*365;artLine([[x-12,y+10],[x,y-8],[x+12,y+10]],'#d5e7ab99',3)}ctx.restore()}if(stage==='defeated'){ctx.fillStyle='#d6e9ad';ctx.font='bold 14px monospace';ctx.textAlign='center';ctx.fillText('PUENTE DESPLEGADO · AVANZÁ AL NORTE HACIA EL CEMENTERIO',W/2,252)}}
