  if(item.pulse){area(p.x,p.y,item.pulseRadius||140,stats().damage*(item.pulseDamage||2));state.activePulse={x:p.x,y:p.y,life:.4,radius:item.pulseRadius||140};soundSfx('break')}
  if(item.shopSedative){for(const enemy of state.rooms[state.room]?.enemies||[])if(enemy.hp>0&&distance(p,enemy)<=190+enemy.r){if(enemy.boss)enemy.shopSedated=2;else enemy.charmTime=4}state.activePulse={x:p.x,y:p.y,life:.4,radius:190}}
