 function placeFly(e,dt){const host=room().enemies.find(h=>h.uid===e.hostId);if(!host)return;e.orbit+=(1.25*enemyMovementFactor(e))*dt;const radius=host.flyOrbitRadius||host.r+22*S;e.x=host.x+Math.cos(e.orbit)*radius;e.y=host.y-(host.flyOrbitHeight||12*S)+Math.sin(e.orbit)*radius*.78}
