 const baseDamage=damageItemEnemy;damageItemEnemy=function(e,amount){if(!e.cemeteryEnemy||isLegacyMobileContent())return baseDamage(e,amount);if(e.cemArrival&&e.cemArrival!=='ready')return 0;if(e.poisonDamageActive)amount*=e.cemeteryKind==='giant'?.95:['zombie','skeleton'].includes(e.cemeteryKind)?.9:1;const before=e.hp,result=baseDamage(e,amount);if(e.cemeteryKind==='skeleton'&&before>0&&e.hp<=0)collapse(e);else if(e.cemeteryKind==='zombie'&&!e.armless&&e.hp>0&&e.hp<=e.max/2){e.armless=true;e.attack=null;e.cool=.25;e.fury=true;e.furyFlash=1;room().stains.push({x:e.x,y:e.y,r:22*S,cemArms:true});addFlies(e,e.necroFlyCount??3);burst(e.x,e.y-10*S,'#93966e',14);soundSfx('break')}return result};
 function ghostMoan(e){e.moanPulse=.7;if(!SOUND.ctx||!SOUND.enabled||!SOUND.sfxEnabled||SOUND.ctx.state!=='running')return;const now=SOUND.ctx.currentTime;if(now-(SOUND.throttle.get('cemMoan')??-99)<.65)return;SOUND.throttle.set('cemMoan',now);audioTone(195,.65,.055,'sine',SOUND.sfx,now,110);audioTone(292,.5,.021,'triangle',SOUND.sfx,now+.1,165)}
