 function destroyCorpse(p,r){if(p.destroyed||!r.bonePiles.includes(p))return;p.destroyed=true;r.bonePiles=r.bonePiles.filter(o=>o!==p);r.obstacles=r.obstacles.filter(o=>o.corpseId!==p.corpseId);for(const e of r.enemies)if(e.corpse?.corpseId===p.corpseId){e.corpse=null;e.rebuilding=false;e.returning=false;e.bodyDestroyed=true}const x=p.x+p.w/2,y=p.y+p.h/2;const claimed=r.cemeteryBoneLootIds||(r.cemeteryBoneLootIds=[]);if(!claimed.includes(p.corpseId)){claimed.push(p.corpseId);const roll=Math.random()/clamp(stats().luck||1,1,1.5);if(roll<.18)r.drops.push({kind:'xp',x,y,value:5*XP_REWARD_SCALE});else if(roll<.33)r.drops.push({kind:'heal',x,y,value:1});else if(roll<.35)r.drops.push({kind:'shield',x,y})}r.stains.push({x,y,r:20*S,cemeteryRemains:'skeleton',seed:Math.floor(Math.random()*0xffffffff)});(r.boneShots||(r.boneShots=[]));for(let i=0;i<10;i++){const a=i*Math.PI/5;r.boneShots.push({x,y,vx:Math.cos(a)*161*S,vy:Math.sin(a)*161*S,r:5*S,life:1.15,fragment:false,noBounce:true,impacts:0,spin:i})}burst(x,y,'#ddd1ae',24);soundSfx('break')}
 function hitCorpseShot(b,r){if(b.spectralShot)return false;if(window.CEMETERY_SPECIAL_ROOMS?.active)return CEMETERY_SPECIAL_ROOMS.hitPlayerProp(b,r);if(!active()||!r.bonePiles?.length)return false;const from={x:b.previousX??b.x,y:b.previousY??b.y},hit=r.obstacles.find(o=>o.bonePileId&&segmentIntersectsRect(from,b,o,b.r||0));if(!hit)return false;const p=r.bonePiles.find(p=>p.corpseId===hit.bonePileId);if(!p)return false;p.hp=(p.hp??9)-(b.damage||stats().damage||1);p.flash=.18;if(p.hp<=0){destroyCorpse(p,r);if(!b.dumpRicochetShot){splitPlayerShot(b);b.life=0;return true}}return false}

 // Pickups must remain reachable when a ghost dies inside scenery or a reward lands behind a grave.
 function settleDrops(r){
  const bounds=roomBounds(r),radius=(state.player.r||18)+4*S;
  const point=(x,y)=>({x:clamp(x,bounds.left+radius,bounds.right-radius),y:clamp(y,bounds.top+radius,bounds.bottom-radius)});
  for(const d of r.drops){
   if(d.cemDropPlaced||!['heal','shield','xp','item','cemKey'].includes(d.kind))continue;
   const origin=point(d.x,d.y);let destination=null;
   for(const range of[0,24,48,80,120,180,260,360,520]){
    for(let i=0;i<(range?16:1);i++){const a=i*Math.PI/8,q=point(origin.x+Math.cos(a)*range*S,origin.y+Math.sin(a)*range*S);if(ROOM_NAVIGATION.sightClear(r,q,q,radius)){destination=q;break}}
    if(destination)break;
   }
   if(destination){d.x=destination.x;d.y=destination.y;d.cemDropPlaced=true}
  }
 }

