  e.boneFlash=Math.max(0,(e.boneFlash||0)-dt);e.boneCool=(e.boneCool??(1.7/1.15))-dt;e.boneWarning=sight&&e.boneCool<=.55;
  if(!sight){e.boneCool=Math.max(e.boneCool,.6);moveBody(e,Math.cos(e.angle+.65)*58*S,Math.sin(e.angle+.65)*58*S,dt)}else if(!e.boneWarning){const speed=d>405*S?62*S:d<220*S?-52*S:0;moveBody(e,Math.cos(e.angle)*speed,Math.sin(e.angle)*speed,dt)}
