 function boneContact(shot,dt){
  const dx=shot.vx*dt,dy=shot.vy*dt,hits=[],bounds=roomBounds();
  for(const [axis,value,sign]of[['x',bounds.left+shot.r,-1],['x',bounds.right-shot.r,1],['y',bounds.top+shot.r,-1],['y',bounds.bottom-shot.r,1]]){const delta=axis==='x'?dx:dy;if(delta*sign<=0)continue;const t=(value-shot[axis])/delta;if(t>=-1e-8&&t<=1)hits.push({t:Math.max(0,t),nx:axis==='x'?-sign:0,ny:axis==='y'?-sign:0})}
  for(const o of shot.cemIgnoresProps?[]:room().obstacles){
   if(shot.cemPiercingDebris&&(o.bonePileId||o.cemeteryProp==='grave'&&!o.coreUid))continue;
   if(shot.cemPiercingWave&&(o.bonePileId||o.cemeteryProp==='grave'))continue;
   if(o.w&&o.h){let enter=0,leave=1,nx=0,ny=0,valid=true;for(const [axis,origin,delta,min,max]of[['x',shot.x,dx,o.x-shot.r,o.x+o.w+shot.r],['y',shot.y,dy,o.y-shot.r,o.y+o.h+shot.r]]){if(Math.abs(delta)<1e-9){if(origin<min||origin>max){valid=false;break}}else{let near=(min-origin)/delta,far=(max-origin)/delta,normal=-Math.sign(delta);if(near>far)[near,far]=[far,near];if(near>=enter){enter=near;nx=axis==='x'?normal:0;ny=axis==='y'?normal:0}leave=Math.min(leave,far);if(enter>leave){valid=false;break}}}if(valid&&enter<=1&&(nx||ny)&&dx*nx+dy*ny<0)hits.push({t:enter,nx,ny,obstacle:o})}
   else if(o.r>0){const ox=shot.x-o.x,oy=shot.y-o.y,r=o.r+shot.r,a=dx*dx+dy*dy,b=ox*dx+oy*dy,c=ox*ox+oy*oy-r*r,disc=b*b-a*c;if(a&&disc>=0){const t=(-b-Math.sqrt(disc))/a;if(t>=0&&t<=1){const x=shot.x+dx*t-o.x,y=shot.y+dy*t-o.y,l=Math.hypot(x,y)||1;hits.push({t,nx:x/l,ny:y/l,obstacle:o})}}}
  }
  return hits.sort((a,b)=>a.t-b.t)[0]||null;
 }
 function shatterBone(shot){shot.life=0;const list=room().boneShots;for(let i=0;i<8;i++){const angle=i*Math.PI/4+shot.spin*.1,speed=(140+i%2*20)*.92*S;list.push({x:shot.x,y:shot.y,vx:Math.cos(angle)*speed,vy:Math.sin(angle)*speed,r:4.25*S,life:.48,fragment:true,spin:i})}burst(shot.x,shot.y,'#d9d0b8',10);soundSfx('break')}
