   if(hit.obstacle)window.CEMETERY_SPECIAL_ROOMS?.damageProp(hit.obstacle,shot.fragment?1:shot.cemSkeletonBone?8:4,r);if(shot.fragment||shot.noBounce){shot.life=0;break}shot.impacts++;if(shot.impacts>=2){shatterBone(shot);break}const dot=shot.vx*hit.nx+shot.vy*hit.ny;shot.vx-=2*dot*hit.nx;shot.vy-=2*dot*hit.ny;shot.x+=hit.nx*.25;shot.y+=hit.ny*.25;left*=1-fraction;soundSfx('shield');
