 const motionEnemy=updateFieldEnemy;updateFieldEnemy=function(e,dt){const x=e.x,y=e.y,result=motionEnemy(e,dt);if(e.cemeteryEnemy){const moved=Math.hypot(e.x-x,e.y-y)/S;if(e.cemeteryKind==='maggot'&&moved>.1){e.trailDistance=(e.trailDistance||0)+moved;if(e.trailDistance>9){e.trailDistance=0;(room().maggotTrails||(room().maggotTrails=[])).push({x:e.x,y:e.y,angle:e.angle,created:state.elapsed})}}e.motionStep=(e.motionStep||e.phase||0)+moved*.14;e.walkWeight=clamp((e.walkWeight||0)+(moved>.1?dt*8:-dt*6),0,1)}return result};
 const baseDeath=fieldDeath;fieldDeath=function(e,r){if(e.cemeteryEnemy)releaseFlies(e,r);if(e.cemeteryKind==='mass')massDeath(e,r);if(e.cemeteryKind==='zombie'&&!e.maggotsReleased){e.maggotsReleased=true;spawnMaggots(e,r,e.necroWormMax===undefined?2+Math.floor(Math.random()*3):Math.floor(Math.random()*(e.necroWormMax+1)))}if(e.cemeteryKind==='spirit'&&e.skeletonMax){if(e.rebuilding&&e.corpse){e.corpse.fallPose=e.corpse.rebuildProgress;e.corpse.fallStarted=state.elapsed;e.corpse.rebuildProgress=0}BUNKER_COLLECTIONS.recordDefeat('cemSkeleton')}return baseDeath(e,r)};
