  if(open>.1){for(let i=0;i<5;i++){const y=-111+i*9;bone(-28-open*7,y,-12-open*11,y+4,3.4);bone(29+open*7,y,13+open*10,y+5,3.4)}oval(0,-84,15,20,C.wound,null);for(let i=0;i<4;i++){const x=Math.sin(t*3+i)*12;line([[x,-83+i*3],[x+7,-78+i*3],[x-1,-70+i*3]],'#b19877',4)}}else{for(let i=0;i<4;i++){const y=-112+i*10;for(const side of[-1,1]){const rib=[[0,y-2],[side*12,y-2],[side*(25-i),y+4],[side*23,y+7]];line(rib,C.ink,6);line(rib,C.bone,3.3)}}line([[0,-116],[0,-78]],'#a79983',3);path(()=>{ctx.moveTo(-19,-78);ctx.quadraticCurveTo(2,-66,23,-78);ctx.lineTo(18,-60);ctx.quadraticCurveTo(-4,-55,-19,-67);ctx.closePath()},C.wound,null)}
