  const eat=state==='eat',mouthLift=eat?clamp(age/.5,0,1):0;path(()=>{ctx.moveTo(45,-126);ctx.quadraticCurveTo(64,-122,62,-98);ctx.lineTo(59,-67-mouthLift*62);ctx.lineTo(47,-65-mouthLift*62);ctx.lineTo(47,-93);ctx.lineTo(36,-114);ctx.closePath()},C.skin);if(state!=='sweep'){hand(53,-64-mouthLift*62,1.2,1.4);path(()=>{ctx.moveTo(50,-113);ctx.lineTo(59,-106);ctx.lineTo(55,-89);ctx.lineTo(49,-94);ctx.closePath()},C.wound,null);bone(54,-105,53,-92,3.6)}
