 function actors(r){if(!r.cemeteryMiniboss)return[];return(r.miniMeat||[]).filter(m=>!m.spent).map(m=>({y:m.held?state.player.y+1:m.y,draw:()=>{if(!m.held&&!m.flying){const pulse=.7+Math.sin(state.elapsed*4)*.14;ctx.save();ctx.globalAlpha=pulse;oval(m.x,m.y+4*S,39*S,21*S,'#bd9b7333','#cdb48e',1.5*S);ctx.restore()}meat(m)}}))}
