 const baseEnemy=updateFieldEnemy;updateFieldEnemy=function(e,dt){if(!active()||!handles(e))return baseEnemy(e,dt);const from={x:e.x,y:e.y};let result;if(e.cemeteryKind==='pursuer')result=pursuer(e,dt);else if(e.cemeteryKind==='dinosaur')result=dinosaur(e,dt);else result=ghost(e,dt);const moved=Math.min(10,Math.hypot(e.x-from.x,e.y-from.y)/S);e.motionStep=(e.motionStep||e.phase||0)+moved*.14;e.walkWeight=clamp((e.walkWeight||0)+(moved>.05?dt*7:-dt*6),0,1);e.motionLean=(e.motionLean||0)+(clamp((e.x-from.x)/(Math.max(dt,1e-6)*150*S),-1,1)-(e.motionLean||0))*Math.min(1,dt*6);return result};

