 const baseTick=tick;tick=function(dt){const r=room(),running=active()&&r?.cemeteryGhostArena&&!state.paused&&!state.map&&!(r.entryDelay>1e-8);const result=baseTick(dt);if(!running||!active()||room()!==r||state.player.hp<=0)return result;const e=r.enemies.find(boss),dark=!!e&&['fade','eyes','shadowRush','shadowGap'].includes(e.ghostState);r.ghostDarkness=clamp((r.ghostDarkness||0)+(dark?dt*2.2:-dt*1.8),0,1);for(const mark of r.ghostImpacts||[]){mark.age+=dt;mark.life-=dt}r.ghostImpacts=(r.ghostImpacts||[]).filter(m=>m.life>0);if(r.ghostDefeatPending){r.ghostDefeatPending.age+=dt;if(r.ghostDefeatPending.age>=.65)finish(r)}return result};
