 function drawFloor(r){if(!r.cemeteryGhostArena)return;ctx.save();if(r.dinoCorpse&&(r.dinoCorpse.revealed||r.dinoCorpse.broken)&&!r.enemies.some(e=>e.cemeteryKind==='dinosaur'&&e.ghostState!=='dinoBreak')){const c=r.dinoCorpse;oval(c.x,c.y+10*S,145*S,30*S,'#273c4545');dinosaur({x:c.x,y:c.y,miniAir:0,ghostState:'corpse',phase:0,dinoFacing:1},state.elapsed,c.progress||0);if(c.progress>0&&c.progress<1){const pulse=.5+Math.sin(state.elapsed*16)*.2;oval(c.x,c.y-20*S,44*S,22*S,`rgba(163,181,153,${pulse*.2})`)}}
  for(const h of r.ghostImpacts||[]){ctx.globalAlpha=clamp(h.life/.5,0,1);oval(h.x,h.y,h.r,h.r,'#a99f8a18','#c1b19666',2*S);for(let i=0;i<9;i++){const a=i*Math.PI*2/9;line([[h.x+Math.cos(a)*h.r*.25,h.y+Math.sin(a)*h.r*.25],[h.x+Math.cos(a+.06)*h.r*.65,h.y+Math.sin(a+.06)*h.r*.65],[h.x+Math.cos(a)*h.r*.95,h.y+Math.sin(a)*h.r*.95]],'#314650',2*S)}}ctx.globalAlpha=1;
  for(const e of r.enemies){if(!e.cemeteryBoss||!CEMETERY_GHOST_MINIBOSS.handles(e))continue;const state=e.ghostState;if(!['eyes','shadowGap','possess'].includes(state))oval(e.x,e.y+9*S,(e.cemeteryKind==='dinosaur'?79:48)*S,15*S,'#2637414a');if(state==='possess'||state==='dinoRise'){const u=state==='possess'?clamp(e.ghostAge/1.5,0,1):1,rumble=Math.sin(e.ghostAge*33)*u;oval(e.x,e.y+17*S,(65+u*45)*S,(14+u*7)*S,'#20313c99');for(let i=0;i<8;i++){const x=e.x+Math.cos(i*2.4)*(35+i%3*20)*S,y=e.y+(12+Math.sin(i*2.4)*15)*S;line([[x-8*S,y],[x+rumble*2*S,y-4*S],[x+11*S,y+2*S]],'#57686a',2*S);oval(x,y-Math.abs(Math.sin(e.ghostAge*12+i))*u*8*S,4*S,2.5*S,'#7b8174')}}if(state==='sink'){const q=clamp(e.ghostAge/.9,0,1);oval(e.x,e.y,48*S*(1+q*.2),16*S*(1-q*.8),'#6c618a55','#b7a6be',1.5*S)}if(state==='explode'){const u=clamp(e.ghostAge/CEM_KAMIKAZE_FUSE,0,1);oval(e.x,e.y-8*S,180*S,180*S,'#51445d22',u>.6?'#d7bbaa':'#b6a4c0',2*S)}}ctx.restore()}
 function drawVeil(r){if(!r.cemeteryGhostArena||!r.ghostDarkness)return;const e=r.enemies.find(e=>e.cemeteryKind==='fatGhost'),d=r.ghostDarkness,p=state.player;ctx.save();const shade=ctx.createRadialGradient(p.x,p.y-23*S,25*S,p.x,p.y-23*S,175*S);shade.addColorStop(0,`rgba(9,9,20,${d*.1})`);shade.addColorStop(.35,`rgba(9,9,20,${d*.6})`);shade.addColorStop(1,`rgba(5,5,14,${d*.96})`);ctx.fillStyle=shade;ctx.fillRect(0,0,960*S,640*S);if(e&&['eyes','shadowRush'].includes(e.ghostState)){const x=e.x,y=e.y-55*S,flash=.8+Math.sin(state.elapsed*16)*.15;for(const side of[-1,1]){oval(x+side*15*S,y,12*S,8*S,`rgba(203,202,170,${flash*.13})`);oval(x+side*15*S,y,6*S,4*S,e.ghostFinal?'#e8c4a8':'#ece2bd');line([[x+side*22*S,y-8*S],[x+side*9*S,y-4*S]],'#ac94b2',2.3*S)}}ctx.restore()}
