  for(const floor of[0,1]){const eligible=rooms.filter((r,i)=>r.houseFloor===floor&&i!==0&&!r.houseEntrance&&!r.houseExterior&&!r.houseStairs.length&&!r.houseTrapSlot),themes=eligible.map(r=>({name:r.name,kind:r.houseKind}));for(let i=themes.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[themes[i],themes[j]]=[themes[j],themes[i]]}eligible.forEach((r,i)=>{r.name=themes[i].name;r.houseKind=themes[i].kind;r.obstacles=furnishings(r.houseKind,r.houseVariant)})}
