 function start(options={}){if(window.EXPLORATION_CONFIDENCE&&!EXPLORATION_CONFIDENCE.requireRoute('cult'))return false;if(options.fromCemetery){origin={rooms:state.rooms,room:state.room,level:state.levelIndex}}else origin=null;clearItemEffects();generation++;state.rooms=makeRooms();state.rooms[0].houseRun.storyEligible=!!options.fromCemetery;state.room=options.fromCemetery||options.entry?state.rooms.findIndex(r=>r.houseExterior):0;state.rooms[state.room].seen=true;state.levelIndex=0;state.mode='play';state.tutorial=false;state.guidedTutorial=false;state.map=false;state.paused=false;state.dialog=false;state.bossIntro=null;state.shots=[];state.bullets=[];state.particles=[];state.friendlyHazards=[];Object.assign(state.player,{x:480*S,y:510*S,fire:0,dash:0,cool:0,inv:1});keys.clear();resetTouchInput();mouse.down=false;$('#overlay').hidden=true;window.CULT_REVISITS?.prepareGreeting();captureLevelCheckpoint();refresh();notify('ZONA 1 · LA CASA DEL CULTO');if(options.fromCemetery&&current().houseEntrance&&!state.rooms[0]?.houseRun?.returnVisit){const entrance=state.rooms[state.room];if(!window.FIRST_MEETINGS?.begin('cultEntrance',{valid:()=>active()&&current()===entrance})){if(window.FIRST_MEETINGS?.hasSeen('cultEntrance')){entrance.housePriestExited=true;entrance.obstacles=entrance.obstacles.filter(o=>!o.priestNpcBody);captureLevelCheckpoint()}}}return true}
