 function beginAttack(e,kind=chooseAttack(e)){e.lastAttack=kind;setPose(e,kind);e.attackAim=aim(e);e.castClock=0;e.squidClock=2.4;e.bellShots=0;e.bellPulse=-10;e.meleeStage='windup';e.meleeAge=0;e.meleeIndex=0;e.attackHit=false;if(kind==='tentacles')tentacles(e);if(kind==='bell'){e.bellPattern=patterns[e.bellIndex++%3].id;e.bellGap=aim(e);e.bellOrigin={x:e.x+40*S,y:e.y-57*S};voice('bell');if(e.priestPhase===2)summon('squid',2,e)}if(kind==='duel'){voice('cast');lockMelee(e)}}
