 function transform(e){setPose(e,'transform');e.priestTransformStarted=true;room().priestEncounter.tentacles=[];state.bullets=state.bullets.filter(b=>!b.priestBullet);voice('prayer');notify('EL SACERDOTE SE AFLIGE · EMPIEZA A REZAR')}
 let allyImpact=false;
 const baseDamage=damageItemEnemy;damageItemEnemy=function(e,amount){if(!handles(e)||!active())return baseDamage(e,amount);if(e.priestRole==='priest'){if(e.pose==='intro'||e.pose==='transform')return 0;amount/=1+devoteeCount()*.08;if(e.priestPhase===1&&!e.priestTransformStarted){const threshold=e.max*.6,before=e.hp,result=baseDamage(e,Math.min(amount,Math.max(0,before-threshold)));if(e.hp<=threshold+1e-7){e.hp=threshold;transform(e)}return result}}const dealt=baseDamage(e,amount);if(e.priestRole==='devotee'&&dealt>0&&!e.poisonDamageActive&&!allyImpact){const boss=host(room());if(boss){const fresh=!angry(boss);boss.priestRageUntil=state.elapsed+3.5;boss.priestRageAt=state.elapsed;if(fresh)voice('rage')}}return dealt};
 const baseHit=hitByPlayerShot;hitByPlayerShot=function(e,b){const before=allyImpact;allyImpact=!!b.fromAlly;try{return baseHit(e,b)}finally{allyImpact=before}};
