 const baseDeath=fieldDeath;fieldDeath=function(e,r){if(handles(e)){if(e.priestRole==='priest'&&live(r)){r.priestEncounter.status='dying';r.priestEncounter.deathAge=0;r.priestEncounter.deathPose={...e,flash:0};r.priestEncounter.tentacles=[];r.enemies=r.enemies.filter(o=>!handles(o));state.bullets=state.bullets.filter(b=>!b.priestBullet);voice('transform')}return}return baseDeath(e,r)};
