 const baseTick=tick;tick=function(dt){const r=room(),running=active()&&!state.paused&&!state.map&&state.player.hp>0,time=state.elapsed,result=baseTick(dt);if(!running||!active()||room()!==r||state.player.hp<=0||state.elapsed===time||!r.priestEncounter)return result;const d=r.priestEncounter,step=state.elapsed-time;if(d.status==='defeated'){collectKey(r);return result}d.age+=step;updateTentacles(r,step);if(d.status==='dying'){d.deathAge+=step;if(d.deathAge>=2.4){d.status='defeated';CULT_RITUALS.guardianVictory(r);releaseKey(r);CULT_HOUSE.settleDrops(r)}return result}const e=host(r);if(e&&!['intro','transform'].includes(e.pose)){d.devoteeClock-=step;if(d.devoteeClock<=0){summon('devotee',1,e);d.devoteeClock=13}}return result};
 function releaseKey(r){const meta=state.rooms[0].houseRun;if(meta.sanctuaryKey||r.drops.some(d=>d.kind==='cultSanctuaryKey'))return;const p=r.priestEncounter?.deathPose||r.cultFinal?.giant,x=clamp(p.x,270*S,800*S),y=clamp(p.y,160*S,510*S),body={x:x-160*S,y:y-45*S,w:220*S,h:100*S},options=[{x:x+110*S,y:y+70*S},{x:x-100*S,y:y+100*S},{x:x+110*S,y:y-70*S}];for(let yy=135;yy<=515;yy+=65)for(let xx=135;xx<=825;xx+=75)options.push({x:xx*S,y:yy*S});const at=options.find(q=>!segmentIntersectsRect(q,q,body,22*S)&&r.drops.every(d=>distance(d,q)>55*S)&&ROOM_NAVIGATION.clear(r,q,q,26*S)&&ROOM_NAVIGATION.route(r,state.player,q,26*S).length)||{x:480*S,y:510*S};r.drops.push({kind:'cultSanctuaryKey',...at,uid:'cult-sanctuary-key'});soundSfx('activeReady')}

 function collectKey(r,interact=false){const d=r?.drops.find(d=>d.kind==='cultSanctuaryKey');if(!d||(r.priestEncounter?.status!=='defeated'&&!r.cultMiniDefeated)||distance(d,state.player)>(interact?80:30)*S||!ROOM_NAVIGATION.clear(r,state.player,d,5*S))return false;state.rooms[0].houseRun.sanctuaryKey=true;r.drops=r.drops.filter(o=>o!==d);soundSfx('door');notify('LLAVE DEL SÓTANO · YA PODÉS BAJAR');refresh();return true}
