 function prepare(rooms){const themes={18:['Bajada de los cautivos','landing'],19:['Las celdas de los imperfectos','cells'],20:['Depósito de los descartados','corpses'],21:['Enfermería de las promesas','medical'],22:['Atrio de la falsa perfección','ritual'],23:['Galería de las jaulas','cells'],24:['Sala de los injertos','medical']};for(const [id,[name,theme]]of Object.entries(themes)){const r=rooms[id];r.name=name;r.basementTheme=theme;r.houseKind=theme;r.obstacles=[];r.imperfectPools=[];r.imperfectBlasts=[];
  const layouts={landing:[['basementCage',140,155,150,75],['bodyRack',700,180,100,65]],cells:[['basementCage',135,160,170,80],['basementCage',655,160,170,80],['basementCage',135,440,150,75],['corpsePile',710,460,105,50]],corpses:[['bodyRack',140,155,140,80],['corpsePile',665,175,150,70],['corpsePile',145,455,140,55],['specimenVat',740,440,65,70]],medical:[['gurney',140,180,180,90],['gurney',655,395,165,90],['surgeryDesk',650,160,170,60],['specimenVat',155,440,70,70]],ritual:[['basementCage',140,165,130,75],['bodyRack',720,430,100,60]]};for(const p of layouts[theme])r.obstacles.push(prop(...p));if(r.houseStairs.length)r.obstacles=r.obstacles.filter(o=>!r.houseStairs.some(st=>segmentIntersectsRect(st,st,o,110*S)))}
  for(const [id,list]of[[19,['imperfectHulk','imperfectHulk']],[20,['imperfectSlug','imperfectSlug','imperfectSlug']],[21,['imperfectHulk','imperfectSlug','imperfectSlug']],[23,['imperfectHulk','imperfectSlug','imperfectHulk']],[24,['imperfectSlug','imperfectHulk','imperfectSlug']]]){const r=rooms[id];r.houseEncounter='imperfects';r.type='fight';r.clear=false;for(const [i,kind]of list.entries())spawn(r,kind,{x:(350+i*145)*S,y:(i%2?430:320)*S})}
  window.CULT_FINAL_SETUP?.prepare(rooms[25]);
 }
 function pose(e,name){e.pose=name;e.poseAge=0;e.once=false}
