// Independent desktop channel controls, downstream of music fades and choir ducking.
(function installDesktopAudioMix(){
 if(isLegacyMobileContent())return;
 const key='moho.desktop-audio-mix.v1',effectsBoost=1.4,musicHeadroom=.82;
 const unit=(value,fallback)=>typeof value==='number'&&Number.isFinite(value)?clamp(value,0,1):fallback;
 let saved={};try{saved=JSON.parse(PROGRESS_STORE.getItem(key)||'{}')||{}}catch{}
 SOUND.musicVolume=unit(saved.music,1);SOUND.sfxVolume=unit(saved.effects,1);SOUND.volume=unit(saved.master,SOUND.volume);
 let context=null,music=null,effects=null,limiter=null;
 function routing(){
  if(!SOUND.ctx||context===SOUND.ctx)return;
  context=SOUND.ctx;const safety=context.createDynamicsCompressor();safety.threshold.value=-1;safety.knee.value=0;safety.ratio.value=20;safety.attack.value=.002;safety.release.value=.12;SOUND.master.disconnect(SOUND.analyser);SOUND.master.connect(safety);safety.connect(SOUND.analyser);music=context.createGain();effects=context.createGain();
  // Existing music/SFX buses retain their own mute, victory and scene envelopes.
  SOUND.music.disconnect(SOUND.master);SOUND.sfx.disconnect(SOUND.master);
  SOUND.music.connect(music);music.connect(SOUND.master);SOUND.sfx.connect(effects);
  if(context.createDynamicsCompressor){limiter=context.createDynamicsCompressor();limiter.threshold.value=-4;limiter.knee.value=5;limiter.ratio.value=6;limiter.attack.value=.004;limiter.release.value=.12;effects.connect(limiter);limiter.connect(SOUND.master)}else effects.connect(SOUND.master);
  music.gain.value=SOUND.musicVolume*musicHeadroom;effects.gain.value=SOUND.sfxVolume*effectsBoost;
 }
 function levels(){routing();if(!context)return;const at=context.currentTime;music.gain.setTargetAtTime(SOUND.musicVolume*musicHeadroom,at,.04);effects.gain.setTargetAtTime(SOUND.sfxVolume*effectsBoost,at,.04)}
 function save(){PROGRESS_STORE.setItem(key,JSON.stringify({master:SOUND.volume,music:SOUND.musicVolume,effects:SOUND.sfxVolume}))}
 const baseLevels=applyAudioLevels;applyAudioLevels=function(){routing();const result=baseLevels();levels();return result};
 const basePause=showPauseMenu;showPauseMenu=function(){
  const result=basePause(),panel=$('#overlay .audio-controls');if(!panel)return result;
  panel.classList.add('desktop-audio-mix');panel.parentElement.querySelector('.pause-actions')?.before(panel);
  const musicToggle=panel.querySelector('#pause-music'),effectsToggle=panel.querySelector('#pause-sfx'),master=panel.querySelector('#pause-volume');
  if(!master||!musicToggle||!effectsToggle)return result;
  const title=document.createElement('b');title.className='audio-mix-title';title.textContent='AUDIO';
  const toggles=document.createElement('div');toggles.className='audio-mix-toggles';toggles.append(musicToggle,effectsToggle);
  panel.replaceChildren(title,toggles);
  function row(label,input,value){const line=document.createElement('div');line.className='audio-mix-row';const caption=document.createElement('label');caption.htmlFor=input.id;caption.textContent=label;const output=document.createElement('output');output.setAttribute('for',input.id);output.textContent=Math.round(value*100)+'%';line.append(caption,input,output);panel.append(line);return output}
  const masterOutput=row('General',master,SOUND.volume),oldMaster=master.oninput;
  master.oninput=function(event){oldMaster?.call(this,event);masterOutput.textContent=this.value+'%';save()};
  for(const [id,label,property]of[['pause-music-volume','Música','musicVolume'],['pause-sfx-volume','Efectos','sfxVolume']]){
   const input=document.createElement('input');Object.assign(input,{id,type:'range',min:'0',max:'100',step:'1',value:String(Math.round(SOUND[property]*100))});input.setAttribute('aria-label','Volumen de '+label.toLowerCase());
   const output=row(label,input,SOUND[property]);input.oninput=()=>{unlockAudio();SOUND[property]=Number(input.value)/100;output.textContent=input.value+'%';applyAudioLevels();save()};
  }
  return result;
 };
 const style=document.createElement('style');style.textContent='#overlay:has(.desktop-audio-mix){overflow-y:auto;justify-content:flex-start}#overlay:has(.desktop-audio-mix)>*{flex-shrink:0}.desktop-audio-mix{display:grid!important;grid-template-columns:1fr;gap:10px!important;width:min(410px,100%);box-sizing:border-box;padding:14px;border:1px solid var(--line);border-radius:12px;background:var(--panel)}.desktop-audio-mix .audio-mix-title{font:700 11px monospace;letter-spacing:1px}.desktop-audio-mix .audio-mix-toggles{display:flex;gap:8px}.desktop-audio-mix .audio-mix-toggles button{flex:1;margin:0!important;min-height:32px}.desktop-audio-mix .audio-mix-row{display:grid;grid-template-columns:65px minmax(90px,1fr) 42px;gap:10px;align-items:center}.desktop-audio-mix .audio-mix-row label{font:12px monospace}.desktop-audio-mix .audio-mix-row input{width:100%;margin:0;min-width:0;height:22px}.desktop-audio-mix output{text-align:right;font:11px monospace;color:var(--text)}';document.head.append(style);
 window.DESKTOP_AUDIO_MIX=Object.freeze({get levels(){return{master:SOUND.volume,music:SOUND.musicVolume,effects:SOUND.sfxVolume}},get gains(){return{music:music?.gain.value,effects:effects?.gain.value}},get effectsBoost(){return effectsBoost},musicHeadroom});
})();

// The music workspace keeps local proposals separate from approved game tracks.
(function installCultMusicWorkspace(){
 if(isLegacyMobileContent())return;
 const page="<!doctype html>\n<html lang=\"es\"><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\"><title>M.O.H.O. · Música de la casa del culto</title>\n<style>*{box-sizing:border-box}body{margin:0;background:#241f2b;color:#eee2cf;font:16px/1.55 system-ui;padding:26px}main{max-width:1080px;margin:auto}header{max-width:790px;margin-bottom:24px}small,.meta{color:#d1ae88}h1{font:38px Georgia;margin:10px 0}h2{font:26px Georgia;margin:12px 0}p{color:#c9bdc8}section{display:grid;grid-template-columns:repeat(auto-fit,minmax(min(100%,350px),1fr));gap:18px}article{background:linear-gradient(140deg,#43313d,#2c2835);border:1px solid #816776;border-radius:14px;padding:22px}article p{min-height:70px;font-size:14px}button,.file{display:inline-block;background:#dfc297;color:#302632;border:1px solid #bba38a;border-radius:7px;padding:9px 13px;min-height:42px;font-weight:bold;cursor:pointer;font-size:13px}button:focus-visible,input:focus-visible,.file:focus-within{outline:3px solid #d8b4d4;outline-offset:3px}.file input{display:block;width:100%;margin-top:6px;color:#302632}audio{display:block;width:100%;margin:14px 0}.times{display:flex;gap:10px;align-items:center;flex-wrap:wrap;font-size:12px}input[type=number]{width:85px;padding:6px;background:#221f2c;color:#eee2cf;border:1px solid #a28b99;border-radius:4px}textarea{width:100%;min-height:170px;background:#211d29;color:#ddd2c4;padding:12px;border:1px solid #806575;resize:vertical;font:13px/1.5 system-ui}details{margin-top:16px}summary{cursor:pointer}output{display:block;font-size:12px;min-height:38px;margin:8px 0;color:#d8c8a7}.tools{display:flex;gap:8px;flex-wrap:wrap}.notes{padding:16px 20px;border-left:3px solid #b58e73;background:#362a36}a{color:#edc38e}footer{margin:24px 0;font-size:13px;color:#b9aeb9}</style>\n<main><header><small>M.O.H.O. / ZONA 1 · APARTADO MUSICAL</small><h1>La casa del culto</h1><p>Un espacio propio para preparar y comparar la música de este nivel, como hicimos con los temas del tutorial. Exploración, combate y Gran Imperfecto ya tienen canciones elegidas. El tema propio del Sacerdote queda pendiente.</p><p>Podés cargar una propuesta de audio en cada apartado, escucharla y probar dónde se repetiría. Esto no reemplaza la música del juego. Los archivos quedan disponibles mientras este taller siga abierto; no se suben a ningún servidor ni se guardan en la partida.</p></header><section id=\"tracks\"></section>\n<div class=\"notes\"><b>Herramientas para componer</b><p><a target=\"_blank\" rel=\"noopener noreferrer\" href=\"https://suno.com/\">Suno</a>: una primera opción para canciones con voces o instrumentales a partir de una descripción. <a target=\"_blank\" rel=\"noopener noreferrer\" href=\"https://www.aiva.ai/\">AIVA</a>: especialmente útil para buscar una base instrumental y orquestal. <a target=\"_blank\" rel=\"noopener noreferrer\" href=\"https://stableaudio.com/\">Stable Audio</a>: otra opción para explorar piezas, ambientes y texturas. Descargas, edición y permisos de uso dependen del servicio y del plan.</p><p>Dirección inicial propuesta: órgano, campanas y coros oscuros. Podés comparar otras versiones aquí sin cambiar las canciones elegidas.</p></div><footer>Para una buena repetición, el final debe volver al inicio sin un cierre definitivo ni un fundido a silencio. Después de elegir una propuesta podemos ajustar duración, mezcla, volumen y unión del bucle antes de integrarla.</footer></main>\n<script>\nconst tracks=[\n {role:'EXPLORACIÓN',title:'La casa que escucha',text:'Calma inquietante entre pasillos y habitaciones. Órgano suave, cuerdas graves, campanas lejanas y espacio para oír trampas y enemigos.',prompt:'Instrumental dark fantasy game exploration music for a mysterious cult mansion. Restrained pipe organ, low strings, sparse distant bells, a memorable quiet motif, uneasy but curious mood. Around 70 BPM. No percussion wall, no vocals, no sudden loud accents. Leave room for gameplay sounds. Write a continuous repeating structure with a musical turnaround; no final cadence and no fade-out.'},\n {role:'COMBATE',title:'Letanía de ceniza',text:'El motivo de la exploración gana pulso: percusión ritual, órgano y cuerdas tensas. Los ataques deben seguir oyéndose con claridad.',prompt:'Instrumental dark fantasy combat music inside a blood-stained cult mansion. Develop a quiet organ exploration motif into tense rhythmic strings, low ritual drums, ominous bells and driving bass. Around 115 BPM. Energetic and readable, not an overwhelming wall of sound. No sung words. Continuous repeating combat structure with a harmonic return to the beginning, no ending and no fade-out.'},\n {role:'MINIJEFE · SACERDOTE',title:'El sermón sumergido',text:'Campanas y órgano con un coro grave sin palabras. La transformación puede sumar voces y una textura más extraña sin tapar los avisos de la pelea.',prompt:'Dark fantasy miniboss music for a tall faceless priest who transforms into an octopus demon. Solemn pipe organ, deep wordless choir, tolling bells and tense ritual percussion. Around 105 BPM. Express a disturbing sermon turning into submerged monstrous prayer. Clear repeating motif and dramatic development, controlled treble, no spoken words. Loop-friendly harmonic turnaround, no ending and no fade-out.'},\n {role:'JEFE · GRAN IMPERFECTO',title:'La falsa perfección',text:'Un inicio solemne que se deforma: belleza religiosa, coros quebrados y cuerdas ásperas. El contraste acompaña su cuerpo y su sufrimiento.',prompt:'Dark fantasy final boss game music called False Perfection. A beautiful sacred organ motif becomes unstable and tragic as a constructed perfect human mutates and falls apart. Layer low wordless choir, dissonant strings, deep ritual drums and restrained bells. Around 120 BPM. Grand, grotesque and sorrowful, with breathing room for combat sounds. A repeating boss structure that returns harmonically to the opening; no final cadence, no fade-out, no spoken dialogue.'}\n];\nconst players=[],urls=new Map();\nfor(const [i,t]of tracks.entries()){\n const card=document.createElement('article');card.innerHTML=`<small class=\"meta\">${t.role} · ${t.role.startsWith('MINIJEFE')?'TEMA PROPIO PENDIENTE':'INTEGRADA · COMPARAR VERSIÓN'}</small><h2>${t.title}</h2><p>${t.text}</p><label class=\"file\">Cargar propuesta de audio<input type=\"file\" accept=\"audio/*,.mp3,.wav,.ogg,.m4a,.flac\" aria-label=\"Cargar audio de ${t.role.toLowerCase()}\"></label><audio controls preload=\"metadata\" aria-label=\"Propuesta de ${t.role.toLowerCase()}\"></audio><div class=\"times\"><label>Inicio (s) <input type=\"number\" min=\"0\" step=\"0.1\" value=\"0\" aria-label=\"Inicio del bucle de ${t.role.toLowerCase()}\"></label><label>Final (s) <input type=\"number\" min=\"0.1\" step=\"0.1\" value=\"60\" aria-label=\"Final del bucle de ${t.role.toLowerCase()}\"></label><label><input type=\"checkbox\"> Repetir tramo</label></div><output role=\"status\" aria-live=\"polite\">Sin propuesta cargada.</output><details><summary>Indicación inicial para la IA</summary><p>Podés cambiar esta propuesta antes de usarla.</p><textarea readonly aria-label=\"Indicación musical para ${t.role.toLowerCase()}\"></textarea><button class=\"copy\" type=\"button\">Copiar indicación</button></details>`;\n document.querySelector('#tracks').append(card);const audio=card.querySelector('audio'),file=card.querySelector('input[type=file]'),[start,end]=card.querySelectorAll('input[type=number]'),repeat=card.querySelector('input[type=checkbox]'),status=card.querySelector('output'),prompt=card.querySelector('textarea');prompt.value=t.prompt;players.push(audio);\n const valid=()=>{const a=Number(start.value),b=Number(end.value);return Number.isFinite(a)&&Number.isFinite(b)&&a>=0&&b>a&&Number.isFinite(audio.duration)&&b<=audio.duration+.02};\n file.onchange=()=>{audio.pause();const f=file.files[0];if(!f)return;if(urls.has(i))URL.revokeObjectURL(urls.get(i));const url=URL.createObjectURL(f);urls.set(i,url);audio.src=url;audio.load();card.querySelector('.meta').textContent=t.role+' · PROPUESTA CARGADA';status.textContent='Archivo local: '+f.name};\n audio.onloadedmetadata=()=>{start.value='0';end.value=String(Math.floor(audio.duration*10)/10);start.max=String(audio.duration);end.max=String(audio.duration)};\n audio.onplay=()=>{for(const other of players)if(other!==audio)other.pause();if(repeat.checked&&!valid()){repeat.checked=false;status.textContent='Corregí el inicio y el final antes de repetir el tramo.'}else if(repeat.checked&&(audio.currentTime<Number(start.value)||audio.currentTime>=Number(end.value)))audio.currentTime=Number(start.value)};\n const loop=()=>{if(repeat.checked&&valid()&&audio.currentTime>=Number(end.value)-.04){audio.currentTime=Number(start.value);if(audio.paused)audio.play().catch(()=>status.textContent='Pulsá reproducir para continuar.')}};audio.ontimeupdate=loop;audio.onended=loop;\n for(const input of[start,end,repeat])input.onchange=()=>{if(repeat.checked&&!valid()){repeat.checked=false;status.textContent='El tramo debe estar dentro del audio y terminar después del inicio.'}else if(repeat.checked)status.textContent='Repitiendo del segundo '+start.value+' al '+end.value+'. Esta es una prueba de la unión; todavía no ajusta el archivo original.'};\n audio.onerror=()=>{status.textContent='No se pudo leer ese audio. Probá con MP3 o WAV.'};\n card.querySelector('.copy').onclick=async()=>{try{await navigator.clipboard.writeText(prompt.value);status.textContent='Indicación copiada.'}catch{prompt.focus();prompt.select();status.textContent='Texto seleccionado: podés copiarlo con Ctrl+C.'}};\n}\ndocument.addEventListener('visibilitychange',()=>{if(document.hidden)for(const p of players)p.pause()});\nwindow.addEventListener('keydown',e=>{if(e.key==='Escape'&&parent!==window){e.preventDefault();parent.postMessage('cult-music:close','*')}});\nwindow.addEventListener('beforeunload',()=>{for(const url of urls.values())URL.revokeObjectURL(url)});\n<\/script></html>\n";let frame=null,opened=false;
 function close(){if(!opened)return;opened=false;try{for(const p of frame.contentDocument.querySelectorAll('audio'))p.pause()}catch{}frame.remove();frame=null;showPauseMenu()}
 function open(){state.paused=true;keys.clear();resetTouchInput();mouse.down=false;const overlay=$('#overlay');overlay.hidden=false;overlay.replaceChildren();const title=document.createElement('h2');title.textContent='Música · Casa del culto';const back=document.createElement('button');back.textContent='Volver a pausa · Esc';back.onclick=close;if(!frame){frame=document.createElement('iframe');frame.title='Taller musical de la casa del culto';frame.srcdoc=page;frame.style.cssText='width:min(1100px,100%);height:65vh;border:1px solid #8e7384;border-radius:12px;flex-shrink:0;background:#241f2b'}overlay.append(title,back,frame);opened=true;back.focus()}
 const baseMenu=showPauseMenu;showPauseMenu=function(){const result=baseMenu();if(!$('#cult-music-workshop-button')){const b=document.createElement('button');b.id='cult-music-workshop-button';b.textContent='Música · Casa del culto';b.onclick=open;const actions=$('#overlay .pause-actions');if(actions)actions.append(b);else $('#overlay').append(b)}return result};
 window.addEventListener('message',e=>{if(opened&&e.source===frame?.contentWindow&&e.data==='cult-music:close')close()});
 window.addEventListener('keydown',e=>{if(opened&&['escape','p'].includes(e.key.toLowerCase())){e.preventDefault();e.stopImmediatePropagation();close()}},true);
 const basePause=togglePause;togglePause=function(...args){if(opened){close();return}return basePause(...args)};
 window.CULT_MUSIC_WORKSPACE=Object.freeze({open,close,get opened(){return opened}});
})();

// Cemetery proposals remain separate from the expedition soundtrack.
(function installCemeteryMusicWorkspace(){
 if(isLegacyMobileContent())return;const content="<!doctype html><html lang=\"es\"><head><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\"><title>M.O.H.O. · Música del cementerio</title><style>*{box-sizing:border-box}body{margin:0;background:#18252b;color:#e2e5d6;font:16px/1.6 system-ui;padding:30px 20px}main{max-width:1120px;margin:auto}header{max-width:820px}h1{font:42px/1.15 Georgia;margin:12px 0}h2{font:27px/1.2 Georgia;margin:20px 0 12px}.eyebrow,.meta{font:11px monospace;letter-spacing:1px;color:#bfc58e}header p,article p{color:#bbcacc}section{display:grid;grid-template-columns:repeat(auto-fit,minmax(min(100%,310px),1fr));gap:20px}article{background:linear-gradient(145deg,#34494d,#26333c);padding:24px;border:1px solid #718a84;border-radius:14px;box-shadow:0 10px 24px #0b141833}.meta{display:flex;flex-wrap:wrap;gap:10px;justify-content:space-between}article p{font-size:14px;min-height:126px}.mix{display:flex;gap:12px;align-items:center;flex-wrap:wrap;margin:24px 0;padding:15px 18px;background:#263a3e;border:1px solid #728a7d;border-radius:10px}.mix label,.repeat{font-size:13px}input{accent-color:#d2cc96}button,.file{background:#d5cc9f;color:#27333a;border:1px solid #e8ddb7;border-radius:7px;padding:11px 15px;min-height:42px;font:700 13px system-ui;cursor:pointer}button[aria-pressed=true]{background:#a5b9a9}button:focus-visible,input:focus-visible{outline:3px solid #c9e3d8;outline-offset:3px}audio{display:block;width:100%;margin:16px 0 10px}.repeat{display:flex;align-items:center;gap:6px}.status{display:block;font-size:12px;min-height:35px;color:#bac9bd;margin:10px 0}.sections{display:flex;flex-wrap:wrap;gap:6px;margin-top:12px}.sections button{background:#455c59;border-color:#81998d;color:#e1dfbe;font:11px system-ui;padding:7px 9px;min-height:34px}.section-name{font:18px Georgia;color:#dfd6ac;margin-top:16px;min-height:24px}footer{font-size:13px;color:#a6b8b7;margin:28px 0}footer p{max-width:940px}.file{display:block;margin-top:12px}.file input{display:block;max-width:100%;margin-top:10px}a{color:#d6ce9a}@media(max-width:600px){body{padding:22px 14px}h1{font-size:34px}article p{min-height:0}}</style></head><body><main><header><div class=\"eyebrow\">M.O.H.O. / CEMENTERIO · REVISIÓN 02</div><h1>La noche sigue bailando</h1><p>Funk electrónico nocturno para explorar, combatir y enfrentar al nigromante. Bajo marcado, guitarra sincopada, piano eléctrico, sintetizadores cálidos y campanas fantasmales. Tres canciones desarrolladas: cada una tiene temas propios, respuestas y puentes. Faroles conserva su comienzo; combate y jefe toman caminos distintos.</p><p>Este apartado permite cargar y comparar propuestas locales. Para escuchar las composiciones ya incluidas sin entrar al juego, usá MOHO-Musica-Cementerio.html. Los archivos que cargues aquí no se suben ni cambian la música de la partida.</p></header><div class=\"mix\"><label for=\"volume\">Volumen de escucha</label><input id=\"volume\" type=\"range\" min=\"0\" max=\"100\" value=\"80\"><output id=\"volume-value\">80%</output><button id=\"pause-all\" type=\"button\">Pausar todo</button></div><section><article><div class=\"meta\"><span>EXPLORACIÓN</span><span>1:07 · 100 BPM</span></div><h2>Faroles de medianoche</h2><p>Conserva el comienzo de Faroles y abre caminos nuevos: una respuesta melódica, un jardín de campanas y un regreso transformado. Bajo cálido, guitarra y piano eléctrico, con más aire entre las frases.</p><label class=\"file\">Cargar una propuesta local<input type=\"file\" accept=\"audio/*\" aria-label=\"Audio de exploración\"></label><button type=\"button\" data-track=\"0\" aria-pressed=\"false\">▶ Escuchar</button><audio controls loop preload=\"metadata\" aria-label=\"Faroles de medianoche\" ></audio><label class=\"repeat\"><input type=\"checkbox\" checked> Repetir canción al terminar</label><small class=\"status\" role=\"status\">Cargá un MP3, WAV u otro audio local.</small><nav class=\"sections\" aria-label=\"Secciones de la canción\"></nav><div class=\"section-name\"></div></article><article><div class=\"meta\"><span>COMBATE</span><span>1:04 · 120 BPM</span></div><h2>Los muertos no duermen</h2><p>Tema nuevo para combatir: persecución sincopada, una respuesta más oscura de guitarra, un puente a medio pulso y un último empuje con otra melodía. El bajo y la batería cambian con cada sección.</p><label class=\"file\">Cargar una propuesta local<input type=\"file\" accept=\"audio/*\" aria-label=\"Audio de combate\"></label><button type=\"button\" data-track=\"1\" aria-pressed=\"false\">▶ Escuchar</button><audio controls loop preload=\"metadata\" aria-label=\"Los muertos no duermen\" ></audio><label class=\"repeat\"><input type=\"checkbox\" checked> Repetir canción al terminar</label><small class=\"status\" role=\"status\">Cargá un MP3, WAV u otro audio local.</small><nav class=\"sections\" aria-label=\"Secciones de la canción\"></nav><div class=\"section-name\"></div></article><article><div class=\"meta\"><span>JEFE · NIGROMANTE</span><span>1:16 · Ritmo variable</span></div><h2>Último baile del nigromante</h2><p>Una pelea musical: fanfarria amenazante, embestida, baile fantasmal en 6/8, escondite tenso, cabalgata al galope y un tema final de duelo. Cambian las melodías, el ritmo y los instrumentos.</p><label class=\"file\">Cargar una propuesta local<input type=\"file\" accept=\"audio/*\" aria-label=\"Audio de jefe · nigromante\"></label><button type=\"button\" data-track=\"2\" aria-pressed=\"false\">▶ Escuchar</button><audio controls loop preload=\"metadata\" aria-label=\"Último baile del nigromante\" ></audio><label class=\"repeat\"><input type=\"checkbox\" checked> Repetir canción al terminar</label><small class=\"status\" role=\"status\">Cargá un MP3, WAV u otro audio local.</small><nav class=\"sections\" aria-label=\"Secciones de la canción\"></nav><div class=\"section-name\"></div></article></section><footer><p>Tomamos el aire de funk electrónico nocturno que pediste con «All Night Forever» de TWRP como referencia. Estas melodías y arreglos son originales: no se emplearon fragmentos de la grabación, su melodía ni su letra.</p><p>Estas tres canciones ya están elegidas e integradas en el cementerio del juego para computadora. Cada pieza tiene desarrollo y un regreso musical al inicio, sin fundido final a silencio.</p></footer></main><script>\nconst players=[...document.querySelectorAll('audio')],sections=[[{\"label\": \"Faroles · tema original\", \"start\": 0, \"end\": 19.2, \"bpm\": 100, \"meter\": \"4/4\", \"style\": \"walk\", \"leadColour\": \"warm\", \"bars\": 8}, {\"label\": \"Un camino nuevo · respuesta\", \"start\": 19.2, \"end\": 38.39999999999999, \"bpm\": 100, \"meter\": \"4/4\", \"style\": \"flow\", \"leadColour\": \"glass\", \"bars\": 8}, {\"label\": \"El jardín de las almas\", \"start\": 38.39999999999999, \"end\": 47.999999999999986, \"bpm\": 100, \"meter\": \"4/4\", \"style\": \"air\", \"leadColour\": \"bell\", \"bars\": 4}, {\"label\": \"Regresan los faroles\", \"start\": 47.999999999999986, \"end\": 57.59999999999998, \"bpm\": 100, \"meter\": \"4/4\", \"style\": \"walk2\", \"leadColour\": \"warm\", \"bars\": 4}, {\"label\": \"La última esquina\", \"start\": 57.59999999999998, \"end\": 67.19999999999999, \"bpm\": 100, \"meter\": \"4/4\", \"style\": \"turn\", \"leadColour\": \"reed\", \"bars\": 4}], [{\"label\": \"Despertar de los muertos\", \"start\": 0, \"end\": 8.0, \"bpm\": 120, \"meter\": \"4/4\", \"style\": \"alarm\", \"leadColour\": \"edge\", \"bars\": 4}, {\"label\": \"Persecución · tema propio\", \"start\": 8.0, \"end\": 24.0, \"bpm\": 120, \"meter\": \"4/4\", \"style\": \"fight\", \"leadColour\": \"edge\", \"bars\": 8}, {\"label\": \"La cripta contesta\", \"start\": 24.0, \"end\": 40.0, \"bpm\": 120, \"meter\": \"4/4\", \"style\": \"counter\", \"leadColour\": \"guitar\", \"bars\": 8}, {\"label\": \"Entre dos ataques\", \"start\": 40.0, \"end\": 48.0, \"bpm\": 120, \"meter\": \"4/4\", \"style\": \"halftime\", \"leadColour\": \"reed\", \"bars\": 4}, {\"label\": \"Atravesar la horda\", \"start\": 48.0, \"end\": 56.0, \"bpm\": 120, \"meter\": \"4/4\", \"style\": \"climax\", \"leadColour\": \"wide\", \"bars\": 4}, {\"label\": \"Nadie se queda atrás\", \"start\": 56.0, \"end\": 64.0, \"bpm\": 120, \"meter\": \"4/4\", \"style\": \"turnFight\", \"leadColour\": \"edge\", \"bars\": 4}], [{\"label\": \"El nigromante entra\", \"start\": 0, \"end\": 10.0, \"bpm\": 96, \"meter\": \"4/4\", \"style\": \"villain\", \"leadColour\": \"brass\", \"bars\": 4}, {\"label\": \"Primera embestida\", \"start\": 10.0, \"end\": 24.54545454545454, \"bpm\": 132, \"meter\": \"4/4\", \"style\": \"boss\", \"leadColour\": \"edge\", \"bars\": 8}, {\"label\": \"Las almas · 6/8\", \"start\": 24.54545454545454, \"end\": 32.04545454545454, \"bpm\": 144, \"meter\": \"6/8\", \"style\": \"ghost\", \"leadColour\": \"glass\", \"bars\": 6}, {\"label\": \"Escondite · pulso suspendido\", \"start\": 32.04545454545454, \"end\": 39.54545454545454, \"bpm\": 96, \"meter\": \"3/4\", \"style\": \"hide\", \"leadColour\": \"bell\", \"bars\": 4}, {\"label\": \"Cabalgata · ritmo al galope\", \"start\": 39.54545454545454, \"end\": 52.34545454545455, \"bpm\": 150, \"meter\": \"4/4\", \"style\": \"gallop\", \"leadColour\": \"guitar\", \"bars\": 8}, {\"label\": \"Último duelo · tema final\", \"start\": 52.34545454545455, \"end\": 66.25849802371542, \"bpm\": 138, \"meter\": \"4/4\", \"style\": \"finalBoss\", \"leadColour\": \"wide\", \"bars\": 8}, {\"label\": \"La risa queda en el aire\", \"start\": 66.25849802371542, \"end\": 76.25849802371542, \"bpm\": 96, \"meter\": \"4/4\", \"style\": \"returnBoss\", \"leadColour\": \"reed\", \"bars\": 4}]],urls=[];\nconst volume=document.querySelector('#volume');function levels(){for(const p of players)p.volume=Number(volume.value)/100;document.querySelector('#volume-value').textContent=volume.value+'%'}volume.oninput=levels;levels();\nfor(const [i,p]of players.entries()){const card=p.closest('article'),button=card.querySelector('[data-track]'),status=card.querySelector('.status'),name=card.querySelector('.section-name');button.onclick=()=>{if(!p.src){status.textContent='Primero cargá una propuesta de audio.';return}if(p.paused)p.play().catch(()=>status.textContent='Pulsá el control de audio para continuar.');else p.pause()};p.onplay=()=>{for(const other of players)if(other!==p)other.pause();button.textContent='Ⅱ Pausar';button.setAttribute('aria-pressed','true');status.textContent='Reproduciendo'};p.onpause=()=>{button.textContent='▶ Escuchar';button.setAttribute('aria-pressed','false');status.textContent='En pausa'};p.onended=()=>status.textContent='La canción terminó';p.onerror=()=>status.textContent='No se pudo leer el audio.';card.querySelector('input[type=checkbox]').onchange=e=>p.loop=e.target.checked;p.ontimeupdate=()=>{const s=sections[i].find(s=>p.currentTime>=s.start&&p.currentTime<s.end);name.textContent=s?.label||''};for(const b of card.querySelectorAll('[data-start]'))b.onclick=()=>{p.currentTime=Number(b.dataset.start);p.play()};const file=card.querySelector('input[type=file]');if(file)file.onchange=()=>{p.pause();if(!file.files[0])return;if(urls[i])URL.revokeObjectURL(urls[i]);urls[i]=URL.createObjectURL(file.files[0]);p.src=urls[i];status.textContent='Archivo local: '+file.files[0].name}}\ndocument.querySelector('#pause-all').onclick=()=>players.forEach(p=>p.pause());document.addEventListener('visibilitychange',()=>{if(document.hidden)players.forEach(p=>p.pause())});window.addEventListener('keydown',e=>{if(e.key==='Escape'&&parent!==window){e.preventDefault();parent.postMessage('cemetery-music:close','*')}});window.addEventListener('beforeunload',()=>urls.forEach(url=>URL.revokeObjectURL(url)));\n<\/script></body></html>";let frame=null;
 function close(){if(!frame)return;try{for(const p of frame.contentDocument.querySelectorAll('audio'))p.pause()}catch{}frame.remove();frame=null;showPauseMenu()}
 function open(){state.paused=true;keys.clear();resetTouchInput();mouse.down=false;APPROVED_MUSIC.sync();const panel=$('#overlay');panel.hidden=false;panel.replaceChildren();const title=document.createElement('h2');title.textContent='Música · Cementerio';const back=document.createElement('button');back.textContent='Volver a pausa · Esc';back.onclick=close;frame=document.createElement('iframe');frame.title='Apartado musical del cementerio';frame.srcdoc=content;frame.style.cssText='width:min(1100px,100%);height:65vh;border:1px solid #81998d;border-radius:12px;flex-shrink:0;background:#18252b';panel.append(title,back,frame);back.focus()}
 const baseMenu=showPauseMenu;showPauseMenu=function(){const result=baseMenu();if(!$('#cemetery-music-workshop-button')){const b=document.createElement('button');b.id='cemetery-music-workshop-button';b.textContent='Música · Cementerio';b.onclick=open;($('#overlay .pause-actions')||$('#overlay')).append(b)}return result};
 window.addEventListener('message',e=>{if(frame&&e.source===frame.contentWindow&&e.data==='cemetery-music:close')close()});window.addEventListener('keydown',e=>{if(frame&&['escape','p'].includes(e.key.toLowerCase())){e.preventDefault();e.stopImmediatePropagation();close()}},true);
 const basePause=togglePause;togglePause=function(...args){if(frame){close();return}return basePause(...args)};
 window.CEMETERY_MUSIC_WORKSPACE=Object.freeze({open,close,get opened(){return!!frame}});
})();
