 function preview(){returnBunker();CULT_FINAL_SETUP.test(25);const r=room(),d=r.cultFinal;d.stage='combat';d.giant.hp=0;d.scientist.free=true;fieldDeath(d.giant,r);d.age=8;d.rewarded=true;r.hazards=[];r.clear=true;state.paused=false;$('#overlay').hidden=true;begin(r,{preview:true});refresh();return true}
