// A boss gift, outside random exploration pools; deferred gifts survive full bags.
(function installColossusGift(){
 if(isLegacyMobileContent())return;
 const key='moho.return-home.v1',template=COLOSSUS_GIFT_TEMPLATE;
 let bombs=[],rings=[],context=null;
 const arena=()=>[window.SCRAPY_TITAN_BOSS,window.COLLECTOR_MINIBOSS,window.BULL_SHARK_MINIBOSS].find(a=>a?.active),sceneKey=()=>arena()||state.rooms;
 function progress(){try{const p=JSON.parse(PROGRESS_STORE.getItem(key)||'null');if(p?.version===1)return p}catch{}return{version:1,victories:0,pending:0,delivered:0}}
 function save(p){PROGRESS_STORE.setItem(key,JSON.stringify(p))}
 function award(){const p=progress();p.victories++;p.pending++;save(p)}
 function claim(){const p=progress();if(!p.pending)return false;if(state.player.bag.length>=state.player.capacity){notify('MOCHILA LLENA · EL COLOSO GUARDARÁ TU REGALO. PODÉS RECOGERLO DESDE PAUSA.');return false}const item={...template,uid:Math.random()};state.player.bag.push(item);p.pending--;p.delivered++;save(p);window.CHARACTER_ROSTER?.save();if(state.mode==='play')captureLevelCheckpoint();refresh();GAME_EVENTS.emit('item:collected',{item});ITEM_PICKUP.offer(item);return true}
 function clear(){bombs=[];rings=[];context=null}
 function area(b){if(window.CULT_RETURN?.active){CULT_RETURN.hitArea?.(b.x,b.y,82,b.damage);return}const custom=arena();if(custom){custom.hitArea(b.x,b.y,82,b.damage);return}for(const e of state.rooms?.[state.room]?.enemies||[])if(e.hp>0&&distance(b,e)<82+(e.r||0))damageItemEnemy(e,b.damage)}
 const baseShoot=shootPlayer;shootPlayer=function(angle){const before=new Set(state.shots),result=baseShoot(angle),p=state.player;if(!state.shots.some(b=>!before.has(b))||!passiveEffect('colossusBombs',p))return result;if(context!==sceneKey()){clear();context=sceneKey()}p.colossusShotCount=(p.colossusShotCount||0)+1;if(p.colossusShotCount<8)return result;p.colossusShotCount=0;const targets=(arena()||window.CULT_RETURN?.active?[]:state.rooms?.[state.room]?.enemies||[]).filter(e=>e.hp>0&&distance(p,e)<650),target=targets.sort((a,b)=>distance(p,a)-distance(p,b))[0],a=target?Math.atan2(target.y-p.y,target.x-p.x):angle;bombs.push({x:p.x,y:p.y,originY:p.y,vx:Math.cos(a)*310,vy:Math.sin(a)*310,age:0,fuse:.78,damage:stats().damage*2*passiveCount('colossusBombs',p)});soundSfx('activeReady');return result};
 function update(dt){if(context!==sceneKey()){bombs=[];rings=[];context=sceneKey()}for(const b of bombs){b.age+=dt;b.x+=b.vx*dt;b.y+=b.vy*dt;if(b.age>=b.fuse){area(b);if(!isMobileGame())for(let i=0;i<14;i++){const a=i*Math.PI/7;state.shots.push({x:b.x,y:b.y,vx:Math.cos(a)*280,vy:Math.sin(a)*280,r:7,life:.65,damage:b.damage*.25,colossusDebris:true,fromAlly:true})}rings.push({x:b.x,y:b.y,age:0});soundSfx('break')}}bombs=bombs.filter(b=>b.age<b.fuse);for(const r of rings)r.age+=dt;rings=rings.filter(r=>r.age<.4)}
 function drawBomb(x,y,t,scale=1){ctx.save();ctx.translate(x,y);ctx.scale(scale,scale);ellipse(ctx,0,9,17,6,'#10181466');ctx.rotate(Math.sin(t*8)*.13);ctx.fillStyle='#556046';ctx.strokeStyle='#202a24';ctx.lineWidth=3;ctx.beginPath();ctx.moveTo(-16,4);ctx.bezierCurveTo(-21,-10,-8,-21,1,-17);ctx.bezierCurveTo(17,-20,25,8,11,12);ctx.quadraticCurveTo(-4,19,-16,4);ctx.closePath();ctx.fill();ctx.stroke();artLine([[-13,-2],[12,5]],'#b7a781',3);artLine([[0,-16],[5,-24],[13,-26]],'#baa374',3);ellipse(ctx,13,-26,3+Math.sin(t*35),3,'#f1bd77');ctx.restore()}
 function draw(){for(const b of bombs)drawBomb(b.x,b.y-Math.sin(b.age/b.fuse*Math.PI)*33,state.elapsed,.85);for(const r of rings){ctx.save();ctx.globalAlpha=1-r.age/.4;ctx.strokeStyle='#d2b57c';ctx.lineWidth=4;ctx.beginPath();ctx.arc(r.x,r.y,82*r.age/.4,0,Math.PI*2);ctx.stroke();for(let i=0;i<12;i++){const a=i*Math.PI/6;ellipse(ctx,r.x+Math.cos(a)*r.age*180,r.y+Math.sin(a)*r.age*180,4,3,i%2?'#9aa785':'#a78b65')}ctx.restore()}}
 const baseTick=tick;tick=function(dt){const time=state.elapsed,result=baseTick(dt);if(state.elapsed>time&&state.mode==='play'&&!state.paused)update(state.elapsed-time);return result};
 const baseEffects=drawBossItemEffects;drawBossItemEffects=function(...args){const result=baseEffects(...args);draw();return result};
 const baseReady=drawActiveReadyCue;drawActiveReadyCue=function(...args){const result=baseReady(...args);if(arena())draw();return result};
 const basePause=showPauseMenu;showPauseMenu=function(){const result=basePause();if(progress().pending){const b=document.createElement('button');b.id='pause-colossus-gift';b.textContent=`Recoger regalo del Coloso · ${progress().pending}`;b.onclick=claim;$('#overlay .pause-actions')?.append(b)}return result};
 const baseClear=clearItemEffects;clearItemEffects=function(...args){clear();return baseClear(...args)};
 const debrisDraw=drawPlayerProjectile;drawPlayerProjectile=function(b){if(!b.colossusDebris)return debrisDraw(b);ctx.save();ctx.translate(b.x,b.y);ctx.rotate(state.elapsed*8+b.vx);ctx.fillStyle='#8b795a';ctx.strokeStyle='#dce5b4';ctx.lineWidth=1.5;ctx.fillRect(-6,-4,12,8);ctx.strokeRect(-6,-4,12,8);ctx.restore()};
 window.COLOSSUS_GIFT=Object.freeze({template,award,claim,update,draw,drawBomb,clear,get progress(){return progress()},get bombs(){return bombs.map(b=>({...b}))}});
})();

