 function tomb(x,y,k=1){ctx.save();ctx.translate(x,y);ctx.scale(k,k);ctx.fillStyle='#7d8382';ctx.strokeStyle='#31303b';ctx.lineWidth=4;ctx.beginPath();ctx.moveTo(-28,0);ctx.lineTo(-28,-73);ctx.bezierCurveTo(-28,-108,28,-108,28,-73);ctx.lineTo(28,0);ctx.closePath();ctx.fill();ctx.stroke();line([[-18,-67],[16,-67]],'#a7aaa0',3);line([[0,-83],[0,-51]],'#a7aaa0',3);line([[-15,-28],[13,-28]],'#b4b1a2',2);line([[-11,-17],[8,-17]],'#a5a89d',2);box(-33,0,66,9,'#666e70');ctx.restore()}
 function actor(kind,x,y,scale,t,pose={}){const key=kind+':'+(pose.stopIndex||0);let e=cache.get(key);const dump=['goblin','hungry','kid','lidKid'].includes(kind);if(!e){e=kind==='lidKid'?Object.assign(makeEnemy('spitter',0,0,0),{type:'dumpLidShooter',lidShooter:true,lidRise:1,lidOpenProgress:1,lidFlee:true,lidPhase:'fleeing',line:0,lidHat:true}):dump?ZONE_ONE_ENEMY_RUNTIME.create(kind==='kid'?'signal':kind,0,0):['reader','dagger','demon'].includes(kind)?CULT_ENEMIES.create(kind,0,0):CEMETERY_ENEMIES.create(kind,0,0);cache.set(key,e)}Object.assign(e,{x:0,y:0,phase:1,pose:'rest',spawnTime:0,cemArrival:'ready',flash:0,paralyzeTime:0,infection:null,...pose});const feet=kind==='goblin'?28:kind==='kid'?22.4:kind==='lidKid'?27:kind==='hungry'?(e.hungerPhase==='armored'?46:58):kind==='demon'?13:12;ctx.save();ctx.translate(x,y);ctx.scale(scale/FIELD_ROOM_SCALE,scale/FIELD_ROOM_SCALE);ctx.translate(0,-feet*FIELD_ROOM_SCALE);withScenePaint('raw',()=>{if(kind==='lidKid')ZONE_ONE_ENEMY_ART.drawLidKid(e);else if(dump)ZONE_ONE_ENEMY_RUNTIME.draw(e);else if(e.cultEnemy)CULT_ENEMIES.draw(e,t);else renderMonster(e,t)});ctx.restore()}
