 function scrapy(x,y,t,wave=true,pose={}){ctx.save();ctx.translate(x,y);ctx.scale(1.1,1.1);SCRAPY_ACTOR.draw(0,-55.2,{label:false,wave,time:t,jump:wave?Math.max(0,Math.sin(t*3))*3:0,...pose});ctx.restore()}
