  poly([[-43,-13],[-15,-31],[5,-18],[-8,7],[-37,12]],'#7e8162','#252e23',3);line([[-35,-8],[-16,-20],[0,-14]],'#b5ac81',2);for(const q of[[-30,-6],[-10,-17],[-25,5]])ellipse(ctx,...q,2,2,'#363d2c','#b9ad7b');
  ctx.save();ctx.translate(21,19);ctx.rotate(.4);barrel(0,0,.46);ctx.restore();line([[-39,16],[-13,31],[20,36],[43,18]],'#a18c60',5);line([[-39,16],[-13,31],[20,36],[43,18]],'#3a3927',1.5);
