  if(!isMobileGame()){
   ctx.save();ctx.beginPath();for(let x=left;x<right;x++)for(let y=0;y<s.world.height/80;y++)if(!CULT_RETURN.floorPoint(s,x*80+40,y*80+40))ctx.rect(x*80,y*80,80,80);ctx.clip();
   for(let y=15;y<s.world.height;y+=56)for(let x=left*80-70;x<right*80+70;x+=82){const seed=Math.floor(x/82)+y/56,jitter=Math.sin(seed*4.7)*13;DUMP_SCENERY.drawBag(x+(Math.floor(y/56)%2)*39,y+jitter,99+Math.sin(seed)*9,65,(Math.floor(Math.abs(seed))+1)%4,Math.sin(seed*2)*.14);if(Math.floor(x/82)%7===0&&Math.floor(y/56)%3===0){ctx.save();ctx.translate(x+20,y-9);ctx.rotate(Math.sin(seed)*.7);box(-26,-9,52,19,pal[Math.floor(Math.abs(seed))%4],'#1d281d',2);line([[-21,-3],[17,-4]],'#aba78366',2);ctx.restore()}}
   ctx.restore();
   for(let x=Math.floor(left*80/320)*320;x<right*80;x+=320)for(const y of[455,645])if(CULT_RETURN.floorPoint(s,x+40,y)){ctx.save();ctx.globalAlpha=.22;line([[x+4,y],[x+60,y-6]],'#272e21',8);for(let n=0;n<4;n++)line([[x+9+n*12,y-5],[x+13+n*12,y+3]],'#a99a70',2);ctx.restore()}
  }
  if(!isMobileGame()){for(let x=Math.floor(left*80/560)*560;x<right*80;x+=560){ctx.save();ctx.strokeStyle='#111b19';ctx.lineWidth=15;ctx.beginPath();ctx.moveTo(x+35,85);ctx.lineTo(x+55,320);ctx.moveTo(x+45,160);ctx.lineTo(x+420,135);ctx.stroke();line([[x+40,83],[x+62,322]],'#596657',4);ctx.strokeStyle='#1a2521';ctx.lineWidth=3;ctx.beginPath();ctx.moveTo(x+60,260);ctx.quadraticCurveTo(x+270,325,x+510,255);ctx.stroke();line([[x+285,290],[x+285,315]],'#766e52',3);ctx.shadowColor='#bba568';ctx.shadowBlur=14;ellipse(ctx,x+285,320,5,8,'#cab87d','#283126');ctx.restore()}}
  // Faces stay within solid cells; only their soft shadows reach the walkable ground.
  for(let x=left;x<right;x++)for(let y=0;y<s.world.height/80;y++){const px=x*80,py=y*80;if(!CULT_RETURN.floorPoint(s,px+40,py+40))continue;for(const [dx,dy]of[[0,-1],[0,1],[-1,0],[1,0]]){if(CULT_RETURN.floorPoint(s,px+40+dx*80,py+40+dy*80))continue;ctx.save();const vertical=dx!==0,ex=px+(dx>0?80:0),ey=py+(dy>0?80:0);ctx.translate(ex,ey);if(vertical){ctx.rotate(Math.PI/2);ctx.scale(1,dx)}else ctx.scale(1,dy<0?1:-1);const face=ctx.createLinearGradient(0,-30,0,0);face.addColorStop(0,'#3f4737');face.addColorStop(.28,'#242e21');face.addColorStop(1,'#10190f');ctx.fillStyle=face;ctx.fillRect(0,-30,80,30);for(let i=0;i<3;i++){ctx.fillStyle=i%2?'#343d2b':'#293523';ctx.beginPath();ctx.moveTo(i*27+1,-26);ctx.quadraticCurveTo(i*27+19,-32,i*27+26,-23);ctx.lineTo(i*27+24,-6);ctx.quadraticCurveTo(i*27+12,-1,i*27+3,-7);ctx.closePath();ctx.fill();line([[i*27+8,-23],[i*27+9,-12]],'#7b806044',1);line([[i*27+3,-7],[i*27+24,-6]],'#080f0aaa',1.5)}line([[0,-30],[23,-32],[53,-29],[80,-31]],'#818264',2);line([[0,-28],[80,-28]],'#151e14',2);const shadow=ctx.createLinearGradient(0,0,0,17);shadow.addColorStop(0,'#060d08a0');shadow.addColorStop(1,'#060d0800');ctx.fillStyle=shadow;ctx.fillRect(0,0,80,17);line([[0,0],[80,0]],'#182215',2);ctx.restore()}}

  if(s.phase==='chase'){ctx.save();ctx.beginPath();ctx.moveTo(s.crumble,400);for(let y=400;y<=640;y+=20)ctx.lineTo(s.crumble+Math.sin(y*.23+s.time*7)*5,y);ctx.lineTo(s.world.width,640);ctx.lineTo(s.world.width,400);ctx.closePath();ctx.fillStyle='#080e0b';ctx.fill();ctx.clip();for(let i=0;i<13;i++){const v=(s.time*.9+i*.16)%1,xx=s.crumble+v*85,yy=415+i%4*48+v*v*90;ctx.globalAlpha=1-v;DUMP_SCENERY.drawBag(xx,yy,25+v*7,20,i%4,v*2);line([[xx-9,yy-12],[xx+9,yy-3]],'#77714a',2)}ctx.restore();for(const y of[401,639])line([[s.crumble-12,y],[s.crumble+20,y+Math.sin(s.time*5)*4],[s.crumble+40,y]],'#aca07b',2)}
