 const ui=document.createElement('section');ui.id='return-journey-ui';ui.hidden=true;ui.innerHTML='<div class="return-heading"></div><div class="return-objective"></div><div class="return-caption" hidden><small></small><p></p><button>Continuar · E / Enter</button></div><div class="return-failure" hidden><h2>La basura te alcanzó.</h2><p>El tramo se reinicia con tus objetos y tu vida del punto de control.</p><button id="return-retry">Reintentar tramo</button><button id="return-abandon">Volver al búnker</button></div><div class="return-help"></div>';$('.viewport').append(ui);
