 function enter(s,phase,index=0){s.phase=phase;s.index=index;s.age=0;s.reveal=false;s.events={};s.voiceAt=.12;s.syllable=0;if(cue(s)?.text)$('#radio-text').textContent=(cue(s).who==='scrapy'?'Scrapy: ':'El Coloso: ')+cue(s).text;s.history.push(phase+':'+(cue(s)?.id||phase));inputs();state.shots=[];if(phase==='grab')sound('no');if(phase==='outro'&&cue(s).id==='cars')sound('warning');if(phase==='outro'&&cue(s).id==='fist')sound('impact');if(phase==='outro'&&cue(s).id==='apology'){s.defeated=true;sound('cry')}if(phase==='outro'&&cue(s).id==='accept'){sound('gift');if(!s.preview&&!s.rewardResolved){COLOSSUS_GIFT.award();s.rewardResolved=true;captureLevelCheckpoint()}}}
