 const pressClosed=s=>{const p=state.player,g=s.gates.find(g=>g.kind==='press');return(s.age%3.8)<1.2&&!(g&&p.x+p.r>g.x&&p.x-p.r<g.x+g.w&&p.y+p.r>g.y&&p.y-p.r<g.y+g.h)};
 function blocked(s,x,y,r=18,ignoreCrate=false,spectral=false){if(!circleFloor(s,x,y,r))return true;if(spectral&&window.CHARACTER_OUTFITS?.ghost)return false;if(s.gates.some(g=>!g.open&&(g.kind!=='press'||pressClosed(s))&&x+r>g.x&&x-r<g.x+g.w&&y+r>g.y&&y-r<g.y+g.h))return true;if((s.escapeObstacles||[]).some(o=>!o.broken&&x+r>o.x&&x-r<o.x+o.w&&y+r>o.y&&y-r<o.y+o.h))return true;return!ignoreCrate&&s.crate&&Math.abs(x-s.crate.x)<r+26&&Math.abs(y-s.crate.y)<r+26}
 function recoverPosition(s){const p=state.player;if(!blocked(s,p.x,p.y,p.r,false,true)){s.lastSafe={x:p.x,y:p.y};return false}const candidates=[];for(let radius=8;radius<=240;radius+=8)for(let i=0;i<24;i++){const a=i*Math.PI/12,x=p.x+Math.cos(a)*radius,y=p.y+Math.sin(a)*radius;if(s.phase==='chase'&&x+p.r>=s.crumble-24)continue;if(!blocked(s,x,y,p.r+1,false,true))candidates.push({x,y,d:radius})}const q=candidates.sort((a,b)=>a.d-b.d)[0]||s.lastSafe||(s.route||[]).filter(q=>!blocked(s,q.x,q.y,p.r+1,false,true)).sort((a,b)=>distance(a,p)-distance(b,p))[0];if(q){p.x=q.x;p.y=q.y;p.dash=0;p.activeDashX=0;p.activeDashY=0;return true}return false}
 function movePlayer(s,dx,dy){const p=state.player,steps=Math.max(1,Math.ceil(Math.hypot(dx,dy)/5));for(let i=0;i<steps;i++)for(const [x,y]of[[dx/steps,0],[0,dy/steps]]){const nx=p.x+x,ny=p.y+y,c=s.crate;if(!window.CHARACTER_OUTFITS?.ghost&&c&&!c.latched&&x!==0&&Math.abs(nx-c.x)<p.r+26&&Math.abs(ny-c.y)<p.r+26&&!blocked(s,c.x+x,c.y,27,true))c.x+=x;if(!blocked(s,nx,ny,p.r,false,true))p.x=nx,p.y=ny}if(s.crate&&!s.crate.latched&&distance(s.crate,s.crate.plate)<28){s.crate.latched=true;s.gates.find(g=>g.id==='plate').open=true;sound('switch')}}
