 function hitArea(x,y,r,damage,spectral=false){const s=journey();if(!s||!playing(s))return 0;let hits=0;if(!isMobileGame()&&s.phase==='chase'&&x+r>s.crumble-95&&x-r<s.crumble+650&&y+r>285&&y-r<710){if(!(s.repelCool>0)){s.crumble+=18;s.repelCool=.04;s.repelCount=(s.repelCount||0)+1;s.lastRepel={x,y,age:0};soundSfx('enemyHit')}return 1}if(spectral)return 0;for(const g of s.gates)if(!g.open&&g.kind==='rubble'&&x+r>g.x&&x-r<g.x+g.w&&y+r>g.y&&y-r<g.y+g.h){g.hp-=damage;hits++;if(g.hp<=0){g.open=true;sound('impact')}}for(const o of s.escapeObstacles||[])if(!o.broken&&o.hp&&x+r>o.x&&x-r<o.x+o.w&&y+r>o.y&&y-r<o.y+o.h){o.hp-=damage;hits++;if(o.hp<=0){o.broken=true;sound('impact')}}return hits}
 function interact(){const s=journey();if(!s||state.paused||state.map)return;if(s.phase==='step-wait'){enter(s,'village-step');return}if(!playing(s)){next();return}const p=state.player,lever=s.levers.find(l=>!l.done&&distance(l,p)<80);if(lever){lever.done=true;s.gates.find(g=>g.id===lever.gate).open=true;sound('switch');refresh();return}collectEscapeBag(s)}
 function shoot(s,dt){const p=state.player;let x=(keys.has('arrowright')?1:0)-(keys.has('arrowleft')?1:0)+TOUCH.aim.x,y=(keys.has('arrowdown')?1:0)-(keys.has('arrowup')?1:0)+TOUCH.aim.y;if(mouse.down){x=mouse.x-p.x;y=mouse.y-p.y}if((x||y)&&p.fire<=0){const angle=Math.atan2(y,x),carrying=!!s.carry;if(carrying)throwEscapeBag(s,angle);else shootPlayer(angle);p.fire=carrying?.35:Math.max(.12,stats().rate||.25)}for(const b of state.shots){b.previousX=b.x;b.previousY=b.y;if(b.shopReturnAge!==undefined){b.shopReturnAge+=dt;if(b.shopReturnAge>=.45){b.shopReturning=true;const a=Math.atan2(p.y-b.y,p.x-b.x),v=Math.hypot(b.vx,b.vy);b.vx=Math.cos(a)*v;b.vy=Math.sin(a)*v;if(distance(b,p)<16)b.life=0}}const steps=Math.max(1,Math.ceil(Math.hypot(b.vx,b.vy)*dt/12));for(let i=0;i<steps&&b.life>0;i++){b.x+=b.vx*dt/steps;b.y+=b.vy*dt/steps;if(!floorPoint(s,b.x,b.y)||hitArea(b.x,b.y,b.r||6,b.damage||1,!!b.spectralShot))b.life=0}b.life-=dt}state.shots=state.shots.filter(b=>b.life>0)}
 function collectEscapeBag(s){if(s.carry)return false;const p=state.player,pile=(s.bagPiles||[]).find(b=>b.cool<=0&&distance(b,p)<62);if(!pile)return false;s.carry={pile:pile.id};pile.cool=2;p.dash=0;p.activeDashX=0;p.activeDashY=0;sound('switch');refresh();return true}
 function throwEscapeBag(s,a){if(!s.carry)return false;const p=state.player;s.thrownBags.push({x:p.x+Math.cos(a)*34,y:p.y+Math.sin(a)*34,vx:Math.cos(a)*720,vy:Math.sin(a)*720,life:.85,angle:a});s.carry=null;s.bagThrows++;p.fire=.35;sound('impact');return true}
 function updateEscapeBags(s,dt){for(const b of s.bagPiles||[])b.cool=Math.max(0,b.cool-dt);if(state.player.dash>0)collectEscapeBag(s);for(const b of s.thrownBags||[]){const n=Math.max(1,Math.ceil(Math.hypot(b.vx,b.vy)*dt/12));for(let i=0;i<n&&b.life>0;i++){b.x+=b.vx*dt/n;b.y+=b.vy*dt/n;const target=s.targets.find(t=>!t.done&&distance(t,b)<39);if(target){target.done=true;s.gates.find(g=>g.id===target.gate).open=true;b.life=0;sound('switch');refresh()}else if(blocked(s,b.x,b.y,8,true))b.life=0}b.life-=dt;b.angle+=dt*8}s.thrownBags=s.thrownBags.filter(b=>b.life>0)}
 function trapPhase(s,t){const age=((s.age+t.offset)%t.period+t.period)%t.period;return age<.65?'warning':age<1.45?'active':'off'}
