    if(s.attacks.filter(a=>a.kind==='ball').length<2){let spot=null;for(const oy of[0,40,-40,80,-80]){for(const ox of[150,100,-210,0])if((s.phase!=='chase'||p.x+ox+48<s.crumble-8)&&!blocked(s,p.x+ox,p.y+oy,48,true)){spot={x:p.x+ox,y:p.y+oy};break}if(spot)break}if(spot){const a=Math.atan2(p.y-spot.y,p.x-spot.x);s.attacks.push({kind:'ball',...spot,age:0,roll:0,vx:Math.cos(a)*350,vy:Math.sin(a)*350,bounces:0,hitCool:0,r:48,aimLocked:false,steerRest:0,trail:[]});}}
