 function enter(s,index){s.index=index;s.age=0;s.reveal=false;s.voiceAt=.12;s.syllable=0;s.history.push(cue(s).id);inputs();if(['join','cheers'].includes(cue(s).id))fx('glass');if(['arrival','devotee-enters'].includes(cue(s).id))fx('door');if(cue(s).id==='plan-c')fx('omen');if(cue(s).text)$('#radio-text').textContent=(names[cue(s).who]||'')+': '+cue(s).text;persist()}
 function begin({preview=false,resume=false}={}){if(active())return false;const p=progress();if(!preview&&(!p.armed||p.completed||p.route!=='bunker'))return false;TUTORIAL_PHONE.interrupt();hideInventory();state.paused=false;state.dialog=false;state.map=false;$('#overlay').hidden=true;state.homecoming={version:1,active:true,cast:window.STORY_CAST?.capture(),preview,index:0,age:0,total:0,reveal:false,voiceAt:.12,syllable:0,history:[],originalView:closeView};inputs();const s=scene();if(resume&&p.cinema&&cues[p.cinema.index]){Object.assign(s,p.cinema);s.history=[cue(s).id]}else enter(s,0);persist();render();return true}
