 const baseRoom=CULT_HOUSE_ART.drawRoom;window.CULT_HOUSE_ART=Object.freeze({...CULT_HOUSE_ART,drawRoom(r){baseRoom(r);const e=r.vossErrand;if(!e||progress().recovered.includes(e.id))return;const x=e.x/FIELD_ROOM_SCALE,y=e.y/FIELD_ROOM_SCALE,t=state.elapsed;ctx.save();ctx.translate(x,y);ellipse(ctx,0,4,23,9,'#18242b44');ctx.fillStyle='#8f7357';ctx.strokeStyle='#302f38';ctx.lineWidth=2.3;ctx.beginPath();ctx.roundRect(-17,-13,34,25,4);ctx.fill();ctx.stroke();if(e.id==='notes'){ctx.fillStyle='#d4d4bc';ctx.fillRect(-13,-15,26,22);for(let i=0;i<3;i++)artLine([[-9,-10+i*5],[8,-10+i*5]],'#527a8c',1.5)}else if(e.id==='tools'){for(let i=0;i<3;i++){artLine([[-9+i*8,-11],[-5+i*8,6]],'#b6cfce',3);ellipse(ctx,-8+i*8,-11,3,3,'#91b8c4')}}else{artLine([[-7,-14],[-7,-21],[7,-21],[7,-14]],'#b7bfae',3);artLine([[0,-10],[0,9]],'#5b453e',2)}ctx.strokeStyle=`rgba(158,204,213,${.4+Math.sin(t*3)*.15})`;ctx.beginPath();ctx.ellipse(0,4,27,12,0,0,Math.PI*2);ctx.stroke();if(distance(state.player,e)<95*FIELD_ROOM_SCALE){ctx.font='9px monospace';ctx.fillStyle='#d9e7db';ctx.textAlign='center';ctx.fillText('E · '+labels[e.id],0,-31)}ctx.restore()}});
 function collect(){prepare();const r=state.rooms[state.room],e=r?.vossErrand,p=progress();if(!e||!r.clear||p.recovered.includes(e.id)||distance(state.player,e)>65*FIELD_ROOM_SCALE)return false;p.recovered.push(e.id);save(p);captureLevelCheckpoint();soundSfx('collect');notify(p.recovered.length===3?'ENCARGO COMPLETADO · La recompensa para los tres espera en el tablero.':labels[e.id]+` · ${p.recovered.length}/3`);refresh();return true}
