 function pin(id,q){if(id==='voss')window.VOSS_DAILY?.pin(q);positions[id]={x:q.x,y:q.y,floor:q.floor||0,facing:q.facing||0};if(RESIDENT_ROUTINE.owns(id))RESIDENT_ROUTINE.pin(id,q,q.floor,q.facing);save()}
 RESIDENT_ROUTINE.register('moho',{name:'Moho',available:()=>!!positions.moho,draw(r){VOSS_STORY.drawRestingMoho(r.point,r.facing)}});
 const baseApply=applyCharacter;
 applyCharacter=function(id,...args){
  const p=state.player,old=p?.characterId||'moho',inside=state.mode==='bunker'&&!GUEST_FLOOR.trip&&!window.HOMECOMING_FINALE?.active;
  if(!inside||old===id||!playableCharacterAllowed(id))return baseApply(id,...args);
  const from={x:p.x,y:p.y,floor:state.bunkerFloor||0,facing:p.facing||0},target=position(id),floor=from.floor;
  // A remote pause selection never transfers the player to another floor.
  let to=target.floor===floor?target:null;
  if(!to){const free=q=>floor===1?q.x>=130&&q.x<=915&&q.y>=164&&q.y<=628&&!GUEST_FLOOR.furniture.some(o=>Math.hypot(q.x-clamp(q.x,o.x-o.w/2,o.x+o.w/2),q.y-clamp(q.y,o.y-o.h/2,o.y+o.h/2))<26):BUNKER_REFINEMENT.free({...q,r:23});for(let radius=54;radius<=180&&!to;radius+=18)for(let i=0;i<16&&!to;i++){const q={...from,x:from.x+Math.cos(i*Math.PI/8)*radius,y:from.y+Math.sin(i*Math.PI/8)*radius};if(free(q))to=q}if(!to)return false} 
  const result=baseApply(id,...args);if(!result)return result;
  pin(old,from);Object.assign(state.player,{x:to.x,y:to.y,facing:to.facing,headX:Math.cos(to.facing),headY:Math.sin(to.facing),anim:{...state.player.anim,move:0,lean:0,direction:VOSS_CHARACTER_ART.view(to.facing)}});state.bunkerFloor=floor;
  positions[id]={...to};save();cameraKey='';refresh();return result;
 };
 function exchange(id){if(state.mode!=='bunker'||GUEST_FLOOR.trip)return false;return applyCharacter(id)}
 const baseNearest=nearestBunkerObject;
 nearestBunkerObject=function(){const base=baseNearest();if(state.mode!=='bunker'||state.player.characterId==='moho'||!positions.moho||positions.moho.floor!==(state.bunkerFloor||0))return base;const npc={id:'parked-moho',...position('moho'),label:'Moho',action:'Saludar y jugar como Moho'};return distance(state.player,npc)<86&&(!base||distance(state.player,npc)<distance(state.player,base))?npc:base};
 const baseAction=interactAction,baseInteract=interactBunker;
