 const baseBoss=updateBoss;updateBoss=function(...a){return withOwner(null,()=>baseBoss(...a))};
 const baseCharm=updateCharmedEnemy;updateCharmedEnemy=function(...a){return withOwner(null,()=>baseCharm(...a))};
 // Retaliation belongs to the player even when an enemy AI is currently attacking.
 const baseHurt=hurt;hurt=function(...a){return withOwner(player(),()=>baseHurt(...a))};
 const effects=window.ZONE_ONE_ITEM_EFFECTS,baseRegister=effects.registerCustom;
 const descriptors=Object.getOwnPropertyDescriptors(effects),baseCustom=effects.hitCustom;
 descriptors.registerCustom={enumerable:true,value(e,apply,boss=false){if(!boss)e.missionSummoned=true;return baseRegister(e,apply,boss)}};
 descriptors.hitCustom={enumerable:true,value(b,e,apply,boss=false){if(!boss)e.missionSummoned=true;return baseCustom(b,e,apply,boss)}};
