 function gratitude(){if(data.afterCelebration!=='gratitude'||state.mode!=='bunker'||state.paused||state.map||CHARACTER_CONVERSATIONS.active||HOMECOMING_FINALE.active||HOMECOMING_FINALE.transitioning||originIntro||GUEST_FLOOR.trip)return;if(GUEST_FLOOR.resting)GUEST_FLOOR.standUp();if(state.player.characterId!=='moho')applyCharacter('moho');state.bunkerFloor=0;window.VOSS_DAILY?.pin({x:264,y:382,floor:0,facing:0});Object.assign(state.player,{x:640,y:415,headX:-1,headY:0});cameraKey='';refresh();VOSS_STORY.gratitude()}
 const baseReset=reset;reset=function(...a){if(data.status==='away'&&!previewing())finish('abandoned');return baseReset(...a)};
 const baseReturn=returnBunker;returnBunker=function(...a){const result=baseReturn(...a);state.dayPreview=false;delete state.player.cinematicMood;return result};
 function hideRest(){$('#day-rest-card')?.remove()}
