 function canSleep(){return !needsColiseumVisit()&& state.mode==='bunker'&&state.player.characterId==='moho'&&(state.bunkerFloor===1&&!!GUEST_FLOOR.resting||!isMobileGame()&&!!window.BUNKER_REST?.resting)&&data.status==='spent'&&data.afterCelebration!=='gratitude'&&!waking}
 function offerRest(){hideRest();if(needsColiseumVisit()&&state.mode==='bunker'&&state.player.characterId==='moho'&&data.status==='spent'){notify('Darío te espera en el coliseo. Pasá por la sala de muñecos y escuchá su explicación antes de dormir.');return false}if(!canSleep())return false;const card=document.createElement('section');card.id='day-rest-card';if(!isMobileGame()&&window.BUNKER_REST?.resting){card.style.left='clamp(14px,4%,50px)';card.style.right='auto'}card.setAttribute('role','dialog');card.setAttribute('aria-label','Terminar el día');card.innerHTML=`<small>DÍA ${data.day} · NOCHE</small><h3>¿Descansamos hasta mañana?</h3><p>La aventura de hoy terminó. Un nuevo día te permitirá volver a explorar.</p><button id="day-sleep">Pasar al día ${data.day+1} · Enter</button><button id="day-stay">Seguir despierto</button>`;$('.viewport').append(card);$('#day-sleep').onclick=sleep;$('#day-stay').onclick=hideRest;$('#day-sleep').focus({preventScroll:true});return true}
 function restoreUpstairs(){state.bunkerFloor=1;const pad=BUNKER_OBJECTS.find(o=>o.id==='platform');Object.assign(state.player,{x:pad.x,y:pad.y+82});cameraKey='';refresh()}
