 function sleep(){if(!canSleep())return false;if(!isMobileGame())window.BUNKER_REST?.beginSleep();hideRest();waking=true;state.paused=true;keys.clear();mouse.down=false;update(d=>{d.day++;d.status='ready';d.sleepPending=true;d.afterCelebration=null;d.homecomingLine=0;if(d.arena.phase==='locked'&&HOMECOMING_FINALE.progress.completed)d.arena.phase='planned';if(d.arena.phase==='planned')d.waitingDescent=true;});if(!isMobileGame())CHARACTER_ROSTER.resetDailyLevels();RESIDENT_ROUTINE.advance(true);window.VOSS_DAILY?.advance();GAME_EVENTS.emit('day:changed',{day:data.day});const layer=document.createElement('section');layer.id='day-night-transition';layer.innerHTML=`<span>Buenas noches, Moho.</span><b>DÍA ${data.day}</b><small>Una nueva mañana en el búnker</small>`;$('.viewport').append(layer);setTimeout(wake,1400);return true}
 function queueExteriorRest(){if(isMobileGame())return;if(data.expedition==='exterior'&&!data.exteriorRest.seen){data.exteriorRest.pending=true;data.exteriorRest.line=0}data.expedition=null}
 const freeForTalk=()=>state.mode==='bunker'&&state.bunkerFloor!==1&&!state.paused&&!state.map&&!CHARACTER_CONVERSATIONS.active&&!originIntro&&!GUEST_FLOOR.trip&&!HOMECOMING_FINALE.active&&!inventoryVisible()&&!window.BUNKER_REST?.resting;
 function restReminder(){if(isMobileGame()||!data.exteriorRest.pending||data.afterCelebration==='gratitude'||!freeForTalk())return false;const lines=[['vera','Se te nota el cansancio. La aventura de hoy terminó; por hoy alcanza. Deberías descansar hasta mañana.'],['ibarra',GUEST_FLOOR.available?'Moho, podés usar el sillón de abajo o subir a descansar. Mañana la basura seguirá ahí, te lo garantizo.':'Moho, acostate en el sillón pequeño del laboratorio. Arriba sigue cerrado, pero no hace falta dormir de pie. Mañana seguimos.']],i=data.exteriorRest.line,[who,text]=lines[i];return CHARACTER_CONVERSATIONS.start(who,text,{unskippable:true,chain:i===0,action:i===0?'Escuchar a Ibarra':'Ir a descansar',reaction:'tired',callback(){update(d=>{d.exteriorRest.line++;if(d.exteriorRest.line>=lines.length){d.exteriorRest.seen=true;d.exteriorRest.pending=false}});restReminder()}})}
