 GAME_EVENTS.on('progress:flush',save);save();
 window.VOSS_DAILY=Object.freeze({advance,pin,draw,occupies(id){return unlocked()&&!DAY_CYCLE.vossUnavailable&&state.player.characterId!=='voss'&&r.floor===1&&!r.pinned&&r.pose==='chair'&&id==='chair-right'},get walking(){return !isMobileGame()&&unlocked()&&!r.pinned&&r.pose==='walk'&&!DAY_CYCLE.vossUnavailable&&state.player.characterId!=='voss'},get position(){return{...r.point,floor:r.floor,facing:r.facing}},get progress(){return structuredClone(r)},get unavailable(){return DAY_CYCLE.vossUnavailable}});
