 const passage=isMobileGame()?{a:{x:1530,y:790},b:{x:1810,y:650},radius:68}:{a:{x:1640,y:724},b:{x:1810,y:650},radius:52};
 function passagePoint(q){const a=passage.a,b=passage.b,dx=b.x-a.x,dy=b.y-a.y,t=clamp(((q.x-a.x)*dx+(q.y-a.y)*dy)/(dx*dx+dy*dy),0,1);return{x:a.x+dx*t,y:a.y+dy*t}}
 function floorFree(q,r){return Math.hypot((q.x-960)/(810-r),(q.y-880)/(310-r))<=1||distance(q,passagePoint(q))<=passage.radius-r||Math.abs(q.x-960)<=99-r&&q.y>=1120&&q.y<=1220-r}
 function projectFloor(p){if(floorFree(p,p.r))return;const rx=810-p.r,ry=310-p.r,dx=p.x-960,dy=p.y-880;let lo=0,hi=Math.max(rx*Math.abs(dx),ry*Math.abs(dy))+rx*rx;for(let i=0;i<32;i++){const t=(lo+hi)/2,f=Math.pow(rx*dx/(t+rx*rx),2)+Math.pow(ry*dy/(t+ry*ry),2);if(f>1)lo=t;else hi=t}const t=(lo+hi)/2,ellipse={x:960+rx*rx*dx/(t+rx*rx),y:880+ry*ry*dy/(t+ry*ry)},near=passagePoint(p),d=distance(p,near)||1,reach=passage.radius-p.r,bridge={x:near.x+(p.x-near.x)/d*reach,y:near.y+(p.y-near.y)/d*reach},south={x:clamp(p.x,861+p.r,1059-p.r),y:clamp(p.y,1120,1220-p.r)},closest=[ellipse,bridge,south].sort((a,b)=>distance(p,a)-distance(p,b))[0];p.x=closest.x;p.y=closest.y}
