 function updateTransfer(dt){if(!transfer||state.paused||state.map||CHARACTER_CONVERSATIONS.active)return;transfer.age+=dt;if(transfer.phase==='enter'&&transfer.age>=1.25){const q=queued();if(!q||!launch(q.id)){transfer=null;return}transfer={phase:'exit',age:0}}else if(transfer.phase==='exit'&&transfer.age>=.8)transfer=null;transferUi()}
 function prepare(id){if(isMobileGame())return launch(id);const b=list.find(b=>b.id===id);if(!inside||section!=='control'||sim||previewLobby||!b||!seenFor().includes(id)||arena().phase!=='ready'||PROGRESS_STORE.temporary)return false;closeMonitor();recoverDrops();DAY_CYCLE.update(d=>d.arena.prepared={id,character:state.player.characterId||'moho'});notify('Simulación lista. Dirigite al coliseo para comenzar.');state.toastTime=6;$('#radio-text').textContent='Simulación lista: '+b.name+'. Volvé al coliseo por la puerta de la izquierda.';transferUi();return true}
 function seenFor(id=state?.player?.characterId||'moho'){return isMobileGame()?arena().seen:arena().seenByCharacter?.[id]||[]}
