 function finish(result){if(!sim||recover)return false;recover=true;const s=sim,d=structuredClone(s.baseline);d.arena.pending=null;d.arena.resume=isMobileGame()?'control':'arena';if(!isMobileGame())d.arena.prepared=null;if(result==='win'){d.arena.wins[s.id]=(d.arena.wins[s.id]||0)+1;d.arena.rewards.push({ticket:s.ticket,character:s.character,amount:18})}if(!isMobileGame())chosenDifficulty=s.previousDifficulty;transfer=null;curtain.hidden=true;readyNotice.hidden=true;PROGRESS_STORE.endSandbox();DAY_CYCLE.restoreState(d);PROGRESS_STORE.freezeWrites();state.paused=true;keys.clear();mouse.down=false;const banner=$('#coliseum-sim-banner');if(banner)banner.textContent=result==='win'?'PROYECCIÓN SUPERADA · +18 XP':result==='loss'?'PROYECCIÓN TERMINADA · Tu equipo y progreso están a salvo':'PROYECCIÓN CANCELADA';setTimeout(()=>location.reload(),450);return true}
