 let data={version:1,cleared:{village:false,dump:false,cemetery:false,cult:false},migrated:false},pressure=null;
 try{const old=JSON.parse(PROGRESS_STORE.getItem(key)||'null');if(old?.version===1)data={...data,...old,cleared:{...data.cleared,...old.cleared}}}catch{}
 const preview=()=>!!(state?.dayPreview||window.DAY_CYCLE?.previewing||PROGRESS_STORE.sandboxed||window.TRAINING_COLISEUM?.active||window.TRAINING_COLISEUM?.simulating||window.BUNKER_TRAINING?.active);
 function save(){if(!preview())PROGRESS_STORE.setItem(key,JSON.stringify(data))}
