 if(!data.migrated){const counts=BUNKER_COLLECTIONS.counts.moho||{},seen=DAY_CYCLE.progress.arena.seen||[];for(const [region,kill,encounter]of[['dump','boss:scrapyTitan','colossus'],['cemetery','cemNecromancer','necromancer'],['cult','cultGrandImperfect','imperfect']])if(counts[kill]>0&&seen.includes(encounter))data.cleared[region]=true;data.migrated=true;save()}
 if(!data.cleared.village){try{if(JSON.parse(PROGRESS_STORE.getItem('moho.scrapy-first-meeting.v1')||'null')?.complete||data.cleared.dump){data.cleared.village=true;save()}}catch{}}
 function visitVillage(){if(preview()||state.player.characterId!=='moho'||data.cleared.village)return false;data.cleared.village=true;save();return true}
 function shy(id,region){return overrides.has(id+':'+region)?overrides.get(id+':'+region):characters.get(id)?.shy===true}
