  dialog(pressure.count===1?`${name} es tímido`:'Demasiada presión',text,state.mode==='bunker'?'Dejarlo descansar':'Quedarme en esta zona',closeDialog);if(state.mode==='play'){const back=document.createElement('button');back.id='timid-return';back.textContent='Volver al búnker';back.onclick=()=>returnBunker();$('#overlay').append(back)}return false;
