  const p=state.player,b=roomBounds(room()),count=e.phase===2?40:30,cols=e.phase===2?8:7,rows=e.phase===2?6:5,stepX=(b.right-b.left-160*S)/(cols-1),stepY=(b.bottom-b.top-160*S)/(rows-1),gap=Math.floor(Math.random()*cols),points=[];
  for(let y=0;y<rows;y++)for(let x=0;x<cols;x++){if(x===gap)continue;points.push({x:b.left+80*S+x*stepX+(y%2?10:-10)*S,y:b.top+80*S+y*stepY,near:Math.hypot(b.left+80*S+x*stepX-p.x,b.top+80*S+y*stepY-p.y)})}
