  if(e.pose==='idle'){const p=state.player;if(distance(e,p)>250*S){e.moving=true;const a=Math.atan2(p.y-e.y,p.x-e.x),before={x:e.x,y:e.y};moveBody(e,Math.cos(a)*45*S,Math.sin(a)*45*S,dt);const b=roomBounds(room());e.x=clamp(e.x,b.left+230*S,b.right-230*S);e.y=clamp(e.y,b.top+335*S,b.bottom-45*S);e.walk=(e.walk||0)+distance(before,e)/(20*S)}if(e.cool<=0)beginAttack(e,d);return}
