 const baseAction=interactAction;interactAction=function(...args){const d=room()?.cultDemon;if(!owner&&d?.stage==='victory'&&!state.paused&&!state.map&&distance(state.player,d.portal)<120*FIELD_ROOM_SCALE)return open();return baseAction(...args)};
