 const enemyLabels={garbage:'Duende de basura',dry:'Infectado del laboratorio / Zombi',rat:'Rata de descarte',spitter:'Escupidora',slime:'Masa amorfa',stalker:'Acechador',synthetic:'Tirador robótico',thick:'Humano corpulento',worm:'Gusano',fungus:'Hongo perseguidor',thorn:'Moho arraigado',spore:'Hongo escupidor',hunger:'El Hambriento',mimic:'Bolsa mímica',kid:'Niño con señal',big:'Niño grande',lid:'Tirador de las tapas',metal:'Robot de cuerda',rot:'Masa podrida',bone:'Órgano óseo',ectoplasm:'Fantasmas',maggot:'Larvas',eye:'Ojo de Fran',heart:'Corazón de Fran',fist:'Puño de Fran',foot:'Pie de Fran',blood:'Órgano sanguíneo',stitch:'Muestra antigua',reader:'Lector del culto',dagger:'Cultista de la daga',devout:'Devotos',demon:'Demonios',tentacle:'Tentáculo del culto',squid:'Pulpo del sacerdote'};
 function carried(){return [...pocket(),...state.player.bag.filter(i=>i.id==='skinBundle').flatMap(i=>i.skins)]}
 function deposit(){if(!panel||!TAILOR_SHOP.active||!eligible())return false;const samples=carried();if(!samples.length)return false;const add=counts(samples);if(Object.entries(add).some(([id,n])=>(data.depot[id]||0)+n>1e9))return false;for(const[id,n]of Object.entries(add))data.depot[id]=(data.depot[id]||0)+n;data.pockets[player()]=[];const removed=new Set(state.player.bag.filter(i=>i.id==='skinBundle').map(i=>i.uid));state.player.bag=state.player.bag.filter(i=>!removed.has(i.uid));state.selected=state.selected.filter(uid=>!removed.has(uid));save();CHARACTER_ROSTER.save();notify(`La Recepcionista guardó ${samples.length} muestras y las separó por criatura.`);render();refresh();return true}
 const materialZones=[['Laboratorio / Tutorial',['rat','spitter','slime','dry','stalker','synthetic','thick','fungus','thorn','spore','worm']],['Basurero',['garbage','hunger','mimic','kid','big','lid','metal','blood','bone']],['Cementerio',['rot','ectoplasm','maggot','eye','heart','fist','foot','stitch']],['Culto',['reader','dagger','devout','demon','tentacle','squid']]];
 function cards(stock){return materialZones.map(([zone,ids])=>{const rows=ids.filter(id=>stock[id]>0).map(id=>`<article data-skin-group="${id}">${art(id)}<div><small>${enemyLabels[id]||'Material preservado'}</small><h3>${name(id)}</h3><b>×${stock[id]}</b>${id==='dry'?'<small>También: zombis del cementerio</small>':''}</div></article>`).join('');return rows?`<section class="skin-zone" data-skin-zone="${zone}"><h3>${zone}</h3><div class="skin-material-grid">${rows}</div></section>`:''}).join('')}
