 function selectOutfit(id,style){if(state.mode!=='bunker'||state.bunkerFloor!==1||id!==player())return false;if(style!=='default'&&!Object.entries(CHARACTER_OUTFIT_RECIPES).some(([key,r])=>r.character===id&&r.styles.includes(style)&&data.outfits.unlocked[key]))return false;data.outfits.selected[id]=style;save();refresh();return true}
