 const chats=[['Él parece callado, pero sabe que estás acá. Esos ojos no se pierden una puntada. Yo prefiero hablar con los clientes; alguien tiene que hacerlo.'],['Una vez intenté ordenar los hilos por color. Él los volvió a ordenar por el ruido que hacían al cortarlos. No le pregunté cómo lo sabía.'],['Él ya tiene los primeros patrones. Yo separo cada muestra. Una piel del duende y una del Hambriento jamás terminan en el mismo cajón.'],['La luz es para vos. Al Costurero le gusta trabajar del otro lado. Si desaparece una tijera, esperá a que vuelva sola.'],['A veces la gente me pregunta si los ojos del fondo son una lámpara. Una vez le hice esa pregunta. Parpadeó. Fue toda la respuesta.']];let chatIndex=0;
 function chat(){if(!panel)return false;close();const text=chats[chatIndex++%chats.length];return CHARACTER_CONVERSATIONS.start('costurera',text[0],{skin:'costurera',lines:text,render:TAILOR_SHOP.renderScene,world:{width:960,height:1000},unitScale:1,cameraFrame:{x:100,y:170,w:760,h:810},cameraHeadOffset:110,reaction:'happy',action:'Volver a la mesa',callback:()=>setTimeout(()=>{if(TAILOR_SHOP.active)open()},0)})}
 function previewSamples(){if(state.mode!=='bunker'||state.bunkerFloor===1||CHARACTER_CONVERSATIONS.active)return false;const samples=Object.keys(ENEMY_SKIN_TYPES).filter(id=>!['stitch','worm'].includes(id)),p=state.player,freePocket=Math.max(0,limit-pocket().length),stackFree=()=>p.bag.filter(i=>i.id==='skinBundle'&&validEnemySkinList(i.skins)).reduce((n,i)=>n+limit-i.skins.length,0),slotsNeeded=()=>Math.ceil(Math.max(0,samples.length-freePocket-stackFree())/limit);if(p.bag.length+slotsNeeded()>p.capacity){if(BUNKER_COLLECTIONS.capacity-BUNKER_COLLECTIONS.box.length<p.bag.length){notify(`Liberá ${slotsNeeded()} espacios para las muestras. La prueba usa primero el compartimento de pieles.`);return false}BUNKER_COLLECTIONS.storeReturnedBag(p)}if(p.bag.length+slotsNeeded()>p.capacity){notify('No hay espacio para todas las muestras. Guardá algunos objetos e intentá de nuevo.');return false}for(const id of samples)store(id,true);state.paused=false;state.dialog=false;$('#overlay').hidden=true;refresh();openInventory();notify(`PRUEBA · ${samples.length} muestras. Primero el compartimento; el resto, en grupos de cinco.`);return true}

 function render(){if(!panel)return;const samples=carried(),upgraded=eligible(),stored=Object.values(data.depot).reduce((a,b)=>a+b,0);panel.innerHTML=`<header><div><small>EL COSTURERO · RECEPCIÓN</small><h2>Una muestra, un cajón.</h2><p>«Traeme las pieles. Yo las separo; él se encarga de las costuras.»</p></div><button id="skin-exchange-close">Volver · Esc</button></header><nav aria-label="Mesa del Costurero"><button data-skin-tab="materials" aria-pressed="${tab==='materials'}">Llevás · ${samples.length}</button><button data-skin-tab="depot" aria-pressed="${tab==='depot'}">Guardadas · ${stored}</button><button data-skin-tab="outfits" aria-pressed="${tab==='outfits'}">Trajes</button><button id="skin-chat">Charlar</button></nav>${!upgraded?`<article class="skin-upgrade"><h3>Preparar esta mochila</h3><p>Dos espacios normales y un compartimento para cinco pieles. La recolección se habilita solo para este personaje.</p><button id="skin-upgrade" ${CHARACTER_TREES.current.xp<TAILOR_SHOP.price?'disabled':''}>Reforzar · ${TAILOR_SHOP.price} XP</button><small>Frasco: ${Math.floor(CHARACTER_TREES.current.xp)} XP</small></article>`:''}<div class="skin-content">${tab==='outfits'?outfitCards():tab==='depot'?`<p class="skin-instructions">Muestras entregadas a la Recepcionista · Compartidas por tus personajes.</p><div class="skin-zone-list">${cards(data.depot)||'<p class="skin-empty">Los cajones todavía están vacíos.</p>'}</div>`:`<p class="skin-instructions">${upgraded?'25% de encontrar una muestra · 40% en el laboratorio. Las moscas, los gusanos del tutorial y Fran entero no dejan pieles.':'Necesitás reforzar esta mochila para empezar a encontrar pieles.'}</p><button id="skin-deposit" ${!samples.length||!upgraded?'disabled':''}>Entregar todas las pieles · ${samples.length}</button><div class="skin-zone-list">${cards(counts(samples))||'<p class="skin-empty">Todavía no trajiste muestras.</p>'}</div><p class="skin-instructions">Compartimento: ${pocket().length}/5. Para liberar espacio, dejá las pieles en esta mesa.</p>`}</div>`;$('#skin-exchange-close').onclick=close;for(const b of panel.querySelectorAll('[data-skin-tab]'))b.onclick=()=>{tab=b.dataset.skinTab;render()};$('#skin-upgrade')?.addEventListener('click',()=>{if(TAILOR_SHOP.upgrade(player(),true)){render();refresh()}});$('#skin-deposit')?.addEventListener('click',deposit);$('#skin-chat').onclick=chat;for(const b of panel.querySelectorAll('[data-craft-outfit]'))b.onclick=()=>craft(b.dataset.craftOutfit)}
 const basePause=showPauseMenu;showPauseMenu=function(...args){const result=basePause(...args),actions=$('#overlay .pause-actions');if(actions){const button=document.createElement('button');button.id='pause-skin-samples';button.textContent='Probar pieles · Una de cada criatura';button.disabled=state.mode!=='bunker'||state.bunkerFloor===1;button.title='Añade muestras a la mochila; usa primero el compartimento y guarda objetos en la caja si necesita espacio. No habilita la recolección.';button.onclick=previewSamples;actions.append(button)}return result};

 const style=document.createElement('style');style.textContent=`#skin-exchange{position:absolute;inset:6%;z-index:65;display:flex;flex-direction:column;gap:16px;padding:24px;border:2px solid #a85a75;border-radius:18px;background:linear-gradient(135deg,#2b1d2d,#171d23);box-shadow:0 18px 65px #000b;color:#ebdfd6}#skin-exchange header{display:flex;align-items:start;justify-content:space-between;gap:20px}#skin-exchange h2{font:26px Georgia;margin:8px 0}#skin-exchange p{line-height:1.55}#skin-exchange header small{color:#d78ba4;letter-spacing:.13em}#skin-exchange nav{display:flex;gap:12px}#skin-exchange nav button[aria-pressed=true]{background:#dcb2b8;color:#372638}.skin-content{overflow:auto;min-height:0}.skin-material-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(220px,1fr));gap:12px}.skin-material-grid article{display:flex;align-items:center;gap:14px;padding:13px;border:1px solid #6e5669;border-radius:12px;background:#ffffff08}.skin-material-grid svg{width:55px;height:55px}.skin-sample-strip{display:flex;gap:5px;flex-wrap:wrap;margin:7px 0}.skin-sample-strip span{display:inline-flex;width:30px;height:30px;padding:2px;border:1px solid #ac93a366;border-radius:6px;background:#ffffff09}.skin-sample-strip svg{width:100%;height:100%}.skin-content>#skin-deposit{margin:0 0 16px}.skin-material-grid small{display:block;color:#c5a9ba;font:10px/1.5 monospace;margin-bottom:4px}.skin-material-grid h3{font:17px Georgia;margin:0 0 8px}.skin-instructions{color:#c4bbc5;font:12px/1.7 monospace}.skin-empty{padding:24px;text-align:center;color:#cbbdc8}.skin-empty>span{font:40px Georgia;color:#d6aab9}.skin-upgrade{padding:15px;border:1px solid #8b7184;border-radius:12px;background:#b1806d15}.skin-upgrade small{margin-left:14px}.skin-bundle{border-color:#a58292!important}.skin-pocket{border-color:#9b6678;background:linear-gradient(120deg,#3d273a,#253139)}html body #inventory>.skin-pocket{grid-column:1/-1;display:grid;grid-template-columns:64px minmax(0,1fr);align-items:center;gap:16px;padding:14px 18px;min-height:120px;border:1px solid #9b6678;border-radius:10px}html body #inventory>.skin-pocket .tailor-part-art{width:64px;height:64px;align-self:center}html body #inventory>.skin-pocket .tailor-part-art svg{width:100%;height:100%}html body #inventory>.skin-pocket small{display:block;font:10px/1.5 monospace;letter-spacing:.05em}html body #inventory>.skin-pocket b{display:block;margin:4px 0;font:17px/1.4 Georgia;color:#eed8da}html body #inventory>.skin-pocket p{margin:4px 0;font:12px/1.5 system-ui}.skin-pocket small{color:#d7adbc}.skin-pocket p{color:#c7c1bd}#scientist-conversation.costurera{border-color:#bc7993;background:linear-gradient(130deg,#342337f5,#1b2730f5);box-shadow:0 12px 40px #0008;color:#ebdfd6}#scientist-conversation.costurera small{color:#dfa0b8}.catalog-filters{flex-wrap:wrap}.catalog-filters button{flex:1 0 105px;font-size:11px}`;document.head.append(style);
 window.addEventListener('keydown',e=>{if(!panel||e.key!=='Escape')return;e.preventDefault();e.stopImmediatePropagation();close()},true);
 const baseReturn=returnBunker;returnBunker=function(...args){close();return baseReturn(...args)};const baseReset=reset;reset=function(...args){close();return baseReset(...args)};
