// World-space night lighting leaves HUDs, dialogue and hit detection untouched.
(function(){
 if(isMobileGame())return;
 function draw(width,height,{lamps=[],windows=[],sleepers=[]}={}){if(!window.DAY_CYCLE?.night)return;return withScenePaint('raw',()=>{ctx.save();ctx.fillStyle='#0b17345c';ctx.fillRect(0,-120,width,height+240);for(const light of lamps){const {x,y}=light,r=light.r||135,g=ctx.createRadialGradient(x,y,5,x,y,r);g.addColorStop(0,'#efc47b33');g.addColorStop(.45,'#c99d6020');g.addColorStop(1,'#d49e6500');ctx.fillStyle=g;ctx.fillRect(x-r,y-r,r*2,r*2);ellipse(ctx,x,y,4,5,'#e5c78a','#6e705b')}for(const w of windows){ctx.fillStyle='#bf9d6344';ctx.fillRect(w.x,w.y,w.w,w.h);ctx.strokeStyle='#c5ac7a66';ctx.lineWidth=1;ctx.strokeRect(w.x,w.y,w.w,w.h)}for(const [i,p]of sleepers.entries()){ctx.globalAlpha=.48+Math.sin(state.elapsed*1.4+i)*.12;ctx.fillStyle='#bccbd0';ctx.font='12px monospace';ctx.textAlign='center';ctx.fillText('z',p.x,p.y-4-Math.sin(state.elapsed+i)*3);ctx.font='9px monospace';ctx.fillText('z',p.x+10,p.y-15-Math.sin(state.elapsed+i)*3)}ctx.restore()})}
 window.EXTERIOR_NIGHT=Object.freeze({draw,get active(){return !!window.DAY_CYCLE?.night}});
})();

