Object.assign(PATIENT_PAINT,{'#c5b6a1':'#ffd15c','#7b8170':'#b84e27','#cad7ac':'#fff39c','#ce9992':'#f2b24c','#895465':'#b14c29','#ffbd8e':'#ffe399','#a5b998':'#f3c154','#b2c7ae':'#ffdf85','#a9c8c6':'#ffd15c','#5b7882':'#b84e27','#b9f1de':'#fff39c','#a5b49d':'#e6a13b','#839888':'#e4ac47','#3e5951':'#94432d','#afd7d0':'#ffcd48','#435f58':'#9c3d27','#b5f2e4':'#fff09a','#d0e8cd':'#ffe171','#d7c6a4':'#f6ce78'});
const PATIENT_RAGE_PAINT={'#a5b998':'#f25b46','#b2c7ae':'#ff9d7d','#ce9992':'#f35745','#a9c8c6':'#ff6955','#c5b6a1':'#f8795b','#895465':'#a63536','#5b7882':'#9d2736','#7b8170':'#aa3c35','#ffbd8e':'#ff9a75','#b9f1de':'#ffd1ad','#cad7ac':'#ff986e','#8f686a':'#b53933','#a5b49d':'#e7443b','#d7c6a4':'#ff8f70','#d6c29c':'#f67b59','#f1e0b477':'#ff977577','#f1ad85':'#ff9c7a','#db8c79':'#e65d43','#79434e':'#8d2636','#9b7779':'#ae3737','#d1a390':'#fa7959','#aa8884':'#d84b3c','#65505a':'#79283a','#a9a184':'#e66c4e','#93997b':'#e45a42','#827c7d':'#b84036','#92594f':'#942b34','#ffe1ad':'#ffb88f','#d0e8cd':'#ff9f7b','#dfbc8466':'#ff705c66','#e9d2a3':'#ffa07a','#839888':'#f0533e','#3e5951':'#872839','#afd7d0':'#ff574b','#435f58':'#8d2336','#b5f2e4':'#ffd0ad'};
function scenePaint(value){
 if(typeof value!=='string'||scenePaintScope==='raw')return value;
 const color=value.toLowerCase(),theme=scenePaletteKey();
 if(scenePaintScope==='bunkerEnvironment')return bunkerEnvironmentPaint(value);
 if(state&&state.mode==='bunker')return value;
 if(['patient','patientRage'].includes(scenePaintScope)&&color.startsWith('rgba(249,200,158,'))return value.replace('249,200,158',scenePaintScope==='patientRage'?'255,94,73':'249,200,110');
 let custom=null;
 if(scenePaintScope==='moho')custom=state.mode==='bunker'||state.levelIndex===0?MOHO_MACABRE:state.levelIndex===1?MOHO_OXIDE:MOHO_FUNGAL;
 else if(ENEMY_B_PAINT[scenePaintScope])custom=ENEMY_B_PAINT[scenePaintScope];
 else if(scenePaintScope==='patient')custom=PATIENT_PAINT;
 else if(scenePaintScope==='patientRage')custom=PATIENT_RAGE_PAINT;
 return custom&&custom[color]||SCENE_PALETTES[theme].colors[color]||value;
}
function bunkerEnvironmentPaint(value){
 const color=value.toLowerCase();
 if(['#3f51342b','#81946955','#d6d7a4','#d5d8ab88','#394c30','#4a5942','#8f9c79','#a3bba077'].includes(color))return value;
 if(color==='#81907a')return '#929696';
 const match=/^#([0-9a-f]{6})([0-9a-f]{2})?$/.exec(color);if(!match)return value;
 const rgb=[0,2,4].map(i=>parseInt(match[1].slice(i,i+2),16)),gray=rgb[0]*.2126+rgb[1]*.7152+rgb[2]*.0722;
 return '#'+[.99,1,1.025].map(k=>Math.min(255,Math.round(gray*k)).toString(16).padStart(2,'0')).join('')+(match[2]||'');
}
function withScenePaint(scope,draw){const previous=scenePaintScope;scenePaintScope=scope;try{return draw()}finally{scenePaintScope=previous}}
// Offscreen floor caches, maps, gradients and regular sprites all receive the same scene palette.
for(const property of ['fillStyle','strokeStyle','shadowColor']){
 const native=Object.getOwnPropertyDescriptor(CanvasRenderingContext2D.prototype,property);
 Object.defineProperty(CanvasRenderingContext2D.prototype,property,{...native,set(value){native.set.call(this,scenePaint(value))}});
}
const nativeGradientColor=CanvasGradient.prototype.addColorStop;
CanvasGradient.prototype.addColorStop=function(offset,color){return nativeGradientColor.call(this,offset,scenePaint(color))};
const sceneMonsterBase=renderMonster;
renderMonster=function(enemy,time){const raging=enemy.boss&&enemy.type==='patient'&&enemy.enraged,scope=enemy.boss&&enemy.type==='patient'?(raging?'patientRage':'patient'):enemy.level===1&&ENEMY_B_PAINT[enemy.type]?enemy.type:null;return withScenePaint(scope,()=>{sceneMonsterBase(enemy,time);if(raging)withScenePaint('raw',()=>{ctx.save();ctx.translate(enemy.x,enemy.y);const pulse=(Math.sin(time*9)+1)/2;ctx.globalAlpha=.65+pulse*.25;artLine([[31,-78],[39,-83],[36,-73],[45,-76]],'#ff4e52',2.5);artLine([[30,-68],[38,-67]],'#ffc4a2',2);ctx.restore()})})};
const sceneClayBase=clay;
clay=function(...args){return withScenePaint(state.mode==='bunker'?'raw':'moho',()=>sceneClayBase(...args))};
const sceneBossAttackBase=drawBossAttack;
drawBossAttack=function(enemy){return withScenePaint(enemy.type==='patient'?'patient':null,()=>sceneBossAttackBase(enemy))};
const sceneArmsBase=drawStretchedArm;
drawStretchedArm=function(...args){return withScenePaint('patient',()=>sceneArmsBase(...args))};
const sceneHostileBase=drawHostileBullet;
drawHostileBullet=function(...args){return withScenePaint('raw',()=>sceneHostileBase(...args))};
const sceneProjectileBase=drawPlayerProjectile;
drawPlayerProjectile=function(...args){return withScenePaint('raw',()=>sceneProjectileBase(...args))};
const sceneRecoveryBase=drawRecoveryPickup;
drawRecoveryPickup=function(...args){return withScenePaint('raw',()=>sceneRecoveryBase(...args))};
// The green trapdoor becomes a macabre laboratory access panel; its interaction area is unchanged.
const sceneHatchBase=drawTutorialHatch;
drawTutorialHatch=function(){if(state.mode==='bunker')return withScenePaint('raw',()=>sceneHatchBase());return withScenePaint('raw',()=>{
 ctx.save();ctx.translate(740,320);ellipse(ctx,0,14,35,13,'#2c243c55');roundedInkRect(-28,-34,56,68,'#61536f');roundedInkRect(-21,-27,42,54,'#b3a5bd');
 ctx.strokeStyle='#7d6b8f';ctx.lineWidth=3;for(let i=0;i<5;i++){ctx.beginPath();ctx.moveTo(-15,-21+i*10);ctx.lineTo(15,-21+i*10);ctx.stroke()}
 roundedInkRect(-9,-12,18,24,'#d8e3ad');ctx.strokeStyle='#625575';ctx.lineWidth=3;ctx.beginPath();ctx.moveTo(0,-8);ctx.lineTo(0,8);ctx.moveTo(-5,0);ctx.lineTo(5,0);ctx.stroke();
 ellipse(ctx,23,-21,3,3,'#d5eaaf');ctx.fillStyle='#ece3cf';ctx.font='bold 10px monospace';ctx.textAlign='center';ctx.fillText('TUTORIAL',0,-45);ctx.font='9px monospace';ctx.fillText('E · EXPLORAR',0,49);ctx.restore();
})};
// Gray architecture, original-colored furnishings and people.
const sceneBunkerBase=drawBunker;
drawBunker=function(){return withScenePaint('bunkerEnvironment',()=>sceneBunkerBase())};
const originalBunkerFurniture={scientist,scienceDesk,bunkerTable,bunkerDoor,missionBoard};
scientist=function(...args){return withScenePaint('raw',()=>originalBunkerFurniture.scientist(...args))};
scienceDesk=function(...args){return withScenePaint('raw',()=>originalBunkerFurniture.scienceDesk(...args))};
bunkerTable=function(...args){return withScenePaint('raw',()=>originalBunkerFurniture.bunkerTable(...args))};
bunkerDoor=function(...args){return withScenePaint('raw',()=>originalBunkerFurniture.bunkerDoor(...args))};
missionBoard=function(...args){return withScenePaint('raw',()=>originalBunkerFurniture.missionBoard(...args))};
function updateScenePalette(){
 const key=scenePaletteKey(),tag=key+':'+(state.mode==='bunker'?'bunker':state.levelIndex);if(sceneCssKey===tag)return;sceneCssKey=tag;
 let style=document.querySelector('#scene-palette');if(!style){style=document.createElement('style');style.id='scene-palette';document.head.append(style)}
 const moho=state.mode==='bunker'?{'#d2dda9':'#d2dda9','#8ca779':'#8ca779'}:key==='oxide'?MOHO_OXIDE:state.levelIndex===2?MOHO_FUNGAL:MOHO_MACABRE;
 style.textContent=SCENE_PALETTES[key].css+`.clay-icon{background:linear-gradient(140deg,${moho['#d2dda9']},${moho['#8ca779']});border-color:#293b35}`;
 document.documentElement.dataset.palette=key;
}

